pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual fit is better; sharpen with square.
    score = score * score / bin_capacity as f64 + post_residual as f64 * 0.5;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chain: post_residual exactly equals next item size -> huge reward.
        let gap = (post_residual as f64 - nxt).abs();
        if gap < 1.0 {
            score -= 120.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits into this bin's leftover: reward proportionally.
            score -= 25.0 + 30.0 * (nxt / post_residual as f64);
        } else {
            // Next item won't fit here: penalize dead space, worse when gap is small
            // (we nearly could have chained) and when post_residual is tiny.
            score += gap.min(30.0) * 0.8 + if post_residual < 10 { 15.0 } else { 0.0 };
        }
        // Coupling with mean residual: bins far below mean residual are "wasted" slots.
        let dev = mean_residual - post_residual as f64;
        score += 0.3 * dev.max(0.0);
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoid opening a new bin unless residual
        // after placement is essentially unusable (< 10) and next item is small.
        let dead = post_residual < 10 && next_item_size > 0 && next_item_size >= 10;
        if !dead {
            score -= 60.0;
        } else {
            score -= 10.0; // mild preference still, new bin may chain better
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when many bins are
        // already open and current fit is poor; discourage otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 - 20.0 * progress - 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 40.0; // next item is huge, fresh bin is very useful
        }
    }

    // Mild penalty for leaving exactly-zero residual if next item exists (bin closes,
    // which is fine, but tie-break toward chaining fits).
    if post_residual == 0 && next_item_size > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits into post_residual: mild reward proportional to how well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    }
    // Next item would NOT fit here: mild penalty for leaving awkward gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Compare residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 10.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when good existing options exist,
    // but allow it when the new bin would be much better used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin starts with score = capacity; adjust to compete with open bins.
        score -= 70.0;
        // Early in stream: be more willing to open bins.
        score -= 20.0 * (1.0 - progress);
        // If next item is huge and this item is small, opening fresh bin is fine.
        if next_item_size > 60 && item_size < 40 {
            score -= 15.0;
        }
    }

    score
}

