pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for any plausible next item
        if next_item_size > post_residual && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: reward tightest fit only
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual far below mean are scarce space;
    // using them for a tight fit is good.
    let r = post_residual as f64;
    if r < mean_residual {
        score -= 10.0 * (mean_residual - r) / bin_capacity as f64;
    } else {
        score += 5.0 * (r - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly everywhere
    // (handled implicitly: empty bin has max post_residual, penalized unless offsets apply).
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly, but less when many bins are open and fragmented.
        score += 20.0 - 2.0 * open_bins_count as f64;
        // If next item is large and current item is small, new bin may be fine.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins earlier in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (1..=100) fits well;
    // gaps in (0..=12) are practically dead, gaps up to ~30 are risky.
    if post_residual > 0 {
        if post_residual <= 12 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 25 {
            score += 25.0; // hard to fill
        } else if post_residual <= 40 {
            score += 8.0; // moderate risk
        } else {
            // Large residual: reward tightness relative to capacity
            score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Exact-fill lookahead: if next item exactly consumes post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits in post_residual, mild reward (chaining placements).
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot fit here, mild penalty for wasted chain potential.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // encouraging consolidation into fewer bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: default mild penalty so we prefer existing bins,
    // but relax it when the fit is terrible (large dead space would be created).
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let bad_fit = if dead <= 12 { 45.0 } else if dead <= 25 { 20.0 } else if dead <= 40 { 6.0 } else { 0.0 };
        // Open new bin when existing placements would create dead space,
        // scaled by stream progression (late stream: be more conservative).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 5.0 + bad_fit - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) * 2.0;

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open bins pressure: penalize creating many open bins; encourage filling existing ones.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins with residual below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make empty bins attractive only when the fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0 + (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of residual after placement
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strong bonus to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling bins with small residuals relative to fleet mean
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Encourage bin consolidation when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Time horizon: early in stream, be conservative (favor new bins slightly less);
    // late in stream, squeeze everything into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = 25.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, avoid opening new bins
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect lookahead match: next item exactly fills this bin
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain fill bonus
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here: penalize wasted lookahead potential
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fit)
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.5 * mean_gap;

    // Penalize tiny unusable dead space unless lookahead rescues it
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_load = 1.0 - mean_residual / bin_capacity as f64;
        score += 55.0 - 50.0 * avg_load;
    }

    // Early stream: be more conservative, keep bins open for future flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit via post_residual, with a superlinear waste penalty
    // so that small leftover slivers are strongly discouraged.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    }
    // Penalize near-miss: next item almost fits (dead-end risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many competing bins: prefer the tightest one, dampen spread noise.
    if fitting_bins_count > 3 {
        score += 0.05 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: when mean residual across open bins is large,
    // we can afford looser fits; when it is tight, prefer frugal placements.
    score += 0.1 * (mean_residual - pr);

    // Time horizon: early in the stream, be conservative about opening
    // bins (favor filling existing ones); late in the stream, allow
    // opening fresh bins since leftover space matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    // Penalize it mildly by default so existing bins are preferred, but
    // discount the penalty when the item is large and no bin fits well
    // (large post_residual everywhere), letting the fresh bin win when
    // existing placements would strand the item's size class.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let large_item_relief = (item_size as f64 / cap) * 20.0;
        let crowd_relief = 0.5 * open_bins_count as f64;
        score += base_penalty - large_item_relief - crowd_relief;
    }

    // Exact-fit celebration: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial coupling to stream progress.
    let pr_norm = pr / cap;
    let coupling = pr_norm * (1.0 + 0.9 * progress * progress) - 0.55 * progress * pr_norm * pr_norm;
    score += 30.0 * coupling;

    // Penalize residual that cannot plausibly hold the next item (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += 0.35 * gap * gap;
        } else {
            score -= 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Prefer bins with residuals near the mean (smooth deviation penalty).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Mild reward for consolidating into fewer bins.
    score -= 0.4 * open_bins_count as f64;

    // New-bin candidate: prefer it only when post-residual would be very large
    // (i.e., item is small) and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 - 55.0 * pr_norm * pr_norm - 25.0 * progress;
        score += new_bin_penalty.max(-20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover space, but with a non-linear (quartic) dead-space curve.
    let mut score = norm_pr.powi(4) * 40.0;

    // Smooth polynomial coupling between post-residual and stream progress:
    // early in the stream, leftover space is cheap; later, it becomes costly.
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 6.0
                 - norm_pr * progress * 10.0
                 + norm_pr * norm_item * 4.0;
    score += coupling;

    // Reward tight fits: exact fill strongly favored via smooth term.
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Penalize opening a new bin when existing bins could fit, scaled by progress.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
