        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill_after = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 30.0 * fill_after;
        } else {
            // next item does not fit in residual: penalize proportionally to waste
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Crowding penalty: with many open bins, prefer bins with below-mean residual
    // (consolidate fuller bins) to keep the pool of large residuals available.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.5 * diff;
    }

    // Time horizon: early in the stream, be conservative with new bins (favor filling
    // existing ones); late in the stream, allow slightly more freedom (less penalty for
    // opening bins since remaining stream is short).
    let horizon = 1.0 - progress;
    score += 20.0 * horizon * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Penalize the new bin by its inherent waste (capacity - item_size),
    // softened when the item is large or few bins fit.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 1.5;
        if fitting_bins_count == 0 {
            score -= 10000.0; // forced: no open bin fits, must open new bin
        } else if item_size >= 70 {
            score -= 120.0; // large items are fine in fresh bins
        } else if fitting_bins_count == 1 {
            score += 150.0; // an open bin exists and is a last chance: prefer it
        }
        // Early stream: opening bins is cheap and useful for future flexibility
        score -= 60.0 * horizon;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let progress_coupling = poly * (0.5 + progress) * cap;

    let mut score = pr + progress_coupling;

    // Reward tight fits via smooth residual decay term
    score -= (1.0 - x).powi(3) * item_size as f64 * 0.5;

    // Penalize waste relative to mean residual (smooth quadratic)
    score += (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin bonus (smoothly gated by progress)
    if fitting_bins_count == 1 {
        score -= cap * (0.3 + 0.7 * progress);
    }

    // Lookahead: reward leaving space usable by next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        let k = (-d * d * 8.0).exp();
        score -= k * nx * 0.4;
    }

    // Mild penalty for bin proliferation early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual buckets of 10 units
    let post_class = post_residual / 10;
    let next_class = next_item_size / 10;

    // Reward when next item exactly fits the post residual class (perfect chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // exact fit lookahead: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize dead space
        score += 8.0;
        // harmonic class mismatch penalty (modulo arithmetic)
        if post_class != next_class {
            score += 5.0;
        }
    }

    // Penalize small unusable residuals (dead space classes 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 10.0 * fill;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer good existing fits,
    // but allow opening when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 6.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0; // fragmentation high: new bin is fine
        }
    }

    // Mid-stream preference to consolidate into fewer bins
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below the minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable sliver
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Penalize leaving a residual that only huge items could use poorly:
    // dead space in (0, 20) is nearly unusable; scale penalty smoothly.
    if post_residual > 0 {
        let usable = (post_residual as f64 / 10.0).floor() * 10.0;
        let dead = post_residual as f64 - usable;
        score += 8.0 * dead;
    }

    // If the next item fits exactly into the post residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }
    // If next item almost fits (miss by small margin), slight penalty.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual is already large; encourage consolidating into fuller bins.
    if bin_residual != bin_capacity {
        score += 0.5 * open_bins_count as f64;
        score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., all fits would leave large dead space) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 50.0; // item small relative to bin
        if poor_fit && progress > 0.1 {
            score += 120.0; // prefer squeezing into open bins
        } else {
            score -= 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Perfect chaining: next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers.
            score += 8.0;
        }
    }

    // Compare with global mean residual: prefer bins whose post residual
    // stays close to the mean (keeps bin pool balanced).
    let diff = post_residual as f64 - mean_residual;
    score += (diff * diff) * 0.05;

    // New bin candidate handling: opening a new bin wastes capacity equal
    // to bin_residual of that empty bin; make it costly unless few bins open
    // or late in the stream with large items expected.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 20.0;
        // Cheaper to open new bins early (more future items to fill them).
        new_bin_cost *= 1.0 - 0.5 * progress;
        // If the only alternative bins leave big waste, new bin is more attractive:
        // handled implicitly by open-bin scores being high.
        if open_bins_count == 0 {
            new_bin_cost = -100.0;
        }
        score += new_bin_cost;
    }

    // Slight preference for fuller bins among many open bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prn = pr / cap;

    // Base: quadratic in normalized post-residual (favor small leftovers, smooth)
    let mut score = 2.0 * prn * prn + 0.5 * prn;

    // Smooth coupling: residual waste penalized more as stream progresses
    score += 3.0 * prn * prn * progress;

    // Reward large item fraction placed (fills bin tightly)
    score -= (it / cap) * (1.0 - prn);

    // Mean-residual coupling: prefer bins deviating from mean when tight
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.5 * prn;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening new bins mildly, less when many open bins crowded
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (open_bins_count as f64).sqrt() + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes (0..10, 10..20) are excellent targets.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic bucket 0..=10
    match class {
        0 => score -= 40.0,                       // near-perfect fill
        1 => score -= 25.0,                       // small dead space
        2 => score -= 10.0,
        3 => score -= 2.0,
        4 => score += 5.0,
        5 => score += 10.0,                       // half-full: mediocre
        6 => score += 14.0,
        7 => score += 18.0,
        8 => score += 22.0,
        9 => score += 26.0,
        _ => score += 30.0,                       // barely touched bin
    }

    // Modulo coupling: leftover that is congruent to small residues mod 25
    // tends to pair with common item sizes; reward such alignments.
    let m = pr % 25;
    if m <= 5 { score -= 8.0; }
    else if m >= 20 { score += 4.0; }

    // Lookahead: if the next item fits exactly into the post residual,
    // this bin chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += 0.05 * (pr as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate: prefer bins with below-mean residual
    // (tighter bins) to reduce bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // New-bin candidate: opening a bin is only attractive when no open bin
    // offers a tight fit (post_residual would be large).
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        let tightness_elsewhere = (post_residual as f64) - (bin_residual as f64 - item_size as f64);
        let _ = tightness_elsewhere;
        // base cost of a fresh bin, discounted early when few bins exist
        score = cap * 0.9 + (open_bins_count as f64) * 2.0 - progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size >= 60 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Gaps that are too small for typical future items are "dead space".
    // Penalize them super-linearly; the smaller the gap, the worse it is.
    let min_useful = 10u32; // smallest plausible item size
    if post_residual < min_useful {
        // Completely wasted capacity: harsh quadratic penalty.
        score += 60.0 + 2.0 * (min_useful - post_residual) as f64;
    } else if post_residual <= 25 {
        // Small awkward gap: mild super-linear penalty scaled by emptiness.
        let gap = post_residual as f64;
        score += 0.35 * (25.0 - gap) * (25.0 - gap) / 25.0;
    }

    // ---- Tight-fit reward ----
    // Reward near-perfect fills strongly (subtracted from score).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 25.0 * (fill_ratio - 0.85) / 0.15;
    }

    // ---- Exact / lookahead match bonus ----
    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // This gap will be exactly consumed by the next item.
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap still usable by lookahead: small bonus.
        score -= 4.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap unusable by the next item: penalize mildly.
        score += 6.0;
    }

    // ---- Last-chance pressure ----
    // If this is the only fitting bin, prefer using it over opening a new bin
    // unless the fit would create severe dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < min_useful {
            score += 15.0; // undo the discount for truly dead fits
        }
    }

    // ---- Open-bin pressure ----
    // Many open bins: discourage spreading; favor filling existing bins,
    // especially the emptiest ones (align with mean residual).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Favor bins tighter than average (they're closer to closing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // ---- New-bin candidate handling ----
    // An empty bin is a fallback: only attractive when this item is huge
    // (would otherwise leave a large unusable gap) or no bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size > 60;
        let poor_fit = post_residual < min_useful || post_residual > 60;
        if big_item || poor_fit {
            score -= 20.0;
        } else {
            // Prefer reusing open bins for ordinary items.
            score += 15.0 + open_pressure * 4.0;
        }
    }

    // ---- Stream-progression nudge ----
    // Late in the stream, waste becomes costlier: tighten dead-space policy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra bonus for exact match
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for any plausible next item
        if next_item_size > post_residual && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: reward tightest fit only
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual far below mean are scarce space;
    // using them for a tight fit is good.
    let r = post_residual as f64;
    if r < mean_residual {
        score -= 10.0 * (mean_residual - r) / bin_capacity as f64;
    } else {
        score += 5.0 * (r - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly everywhere
    // (handled implicitly: empty bin has max post_residual, penalized unless offsets apply).
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly, but less when many bins are open and fragmented.
        score += 20.0 - 2.0 * open_bins_count as f64;
        // If next item is large and current item is small, new bin may be fine.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins earlier in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.02 * (post_residual as f64).powi(2);

    // Reward filling bins completely (post_residual near 0 or perfect fit).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual
    // (chaining placements in the same bin), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space that the next item cannot use: penalize more when
            // post_residual is small-but-unusable (classic fragmentation).
            if post_residual > 0 && post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Prefer placing into bins whose residual is already below the mean
    // (consolidate small leftovers rather than draining big bins).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_diff;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins tight for later); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: score relative to mean residual so that it wins
        // only when open bins are fragmented.
        score = 45.0 + 0.3 * mean_residual - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    } else {
        // Late stream: extra reward for closing out bins.
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth interaction: weight of residual grows non-linearly with progress
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (x * x) * cap * 0.5;

    // Penalize very tight fits late in the stream (dead space risk), reward mid fits
    let tight = 1.0 - x;
    score -= 3.0 * progress * tight * tight;

    // Last-chance bin bonus, modulated by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for next item (smooth quadratic overlap)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 2.0 * (gap / cap) * (1.0 + progress);
        } else {
            score += 4.0 * ((-gap) / cap) * (1.0 + progress);
        }
    }

    // Mean residual coupling: bins far from mean residual get slight penalty
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: penalize opening new bins early, relax later
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "good" dead space
    // (divisible by common item sizes) get rewarded, odd/tiny residues penalized.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus -= 6.0; }        // perfectly harmonizable residual
        else if pr % 5 == 0 { class_bonus -= 3.0; }
        else if pr % 2 == 0 { class_bonus -= 1.0; }
        else { class_bonus += 4.0; }                   // odd residue: likely dead space
    } else {
        class_bonus -= 10.0;                            // perfect closure: excellent
    }
    score += class_bonus;

    // Integer-division threshold classes on post_residual
    let pr_class = pr / 20; // 0..=5
    score += match pr_class {
        0 => -4.0,               // residual 0..19: tight fit, valuable bin
        1 => 0.0,
        2 => 2.0,                // 40..59: mediocre
        3 => 4.0,
        4 => 6.0,
        _ => 8.0,                // 80..: nearly empty bin being consumed
    };

    // Lookahead: if next item can exactly fill this bin's post_residual, reward strongly
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
            // harmonic compatibility: next item divides remaining-after-next
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 { score -= 2.0; }
        } else {
            score += 3.0; // next item cannot use this residual
        }
    } else if next_item_size == 0 {
        // last item: prefer closing bins tightly
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += cap * 0.9;
        // if item fits snugly in a fresh bin (harmonic class), discount
        let rem = bin_capacity - item_size;
        if rem % 10 == 0 { score -= 25.0; }
        if next_item_size > 0 && rem >= next_item_size && (rem - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // open bins: reward reusing bins relative to how many are open
        score -= (open_bins_count.min(20) as f64) * 0.3;
        // prefer bins below mean residual (denser bins) — pack tight first
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.15;
    }

    // Fractional capacity coupling: fill ratio reward
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Post-residual that can't fit even the smallest item is pure waste.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // If mean residual is large, existing bins likely have room; penalize new bin more.
        score += mean_residual.clamp(0.0, 100.0);
        // If the next item could pair with this item in a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit character).
        score += 0.15 * (bin_residual as f64 - item_size as f64).abs();
        // Coupling: prefer bins with residual below mean (consolidate fuller bins).
        score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);
        // Lookahead: if next item fits the post-residual exactly-ish, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        }
        // If post-residual is too small for the next item, slight penalty (dead end).
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Early in the stream, be more willing to spread items (soften new-bin cost).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: next item exactly fills the remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Two-step lookahead: reward when next item fits comfortably in post_residual,
    // penalize if next item cannot fit (dead space likely).
    if next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack < 0.0 {
            // Next item won't fit here; residual is likely wasted.
            score += 0.4 * (-slack);
        } else if slack <= 10.0 {
            // Near-perfect 2-step match: strong reward.
            score -= 35.0 - 2.0 * slack;
        } else {
            // Larger slack than next item needs: mild penalty proportional to waste.
            score += 0.15 * slack;
        }
    }

    // Penalize residuals too small for any plausible item (dead space).
    if post_residual < 10 {
        score -= 20.0; // tiny residual is fine (bin nearly full)
    } else if post_residual < 30 {
        // Awkward zone: residual too big to waste but small to be useful.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins tighter than average residual (best-fit bias).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for opening new bins early in the stream when many bins
    // already exist and residual is large (avoid fragmenting many bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: baseline score equals capacity; adjust so it wins
        // only when open bins are fragmented or item is large.
        score -= 5.0 + 30.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: small post-residual but nonzero is bad if next item can't use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += 8.0 * (1.0 - post / nxt);
        } else if nxt > 0.0 && post >= nxt {
            // reward bins whose leftover fits the next item
            score -= 12.0 * (1.0 - ((post - nxt) / cap));
        }
    } else {
        // last item: prefer minimal leftover
        score += 5.0;
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when many open bins could fit
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current item is large relative to mean residual
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let ratio = item_size as f64 / cap;
        let pressure = (mean_residual / cap) - ratio;
        score = cap * (1.0 + 0.5 * progress) + 25.0 * pressure.max(0.0) - 20.0 * ratio;
        if mean_residual < ratio * cap {
            score -= 10.0; // open bins too full, new bin good
        }
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_pr * norm_pr; // in (0,1], high when residual small
    score -= 40.0 * tightness * (progress * progress + 0.15 * progress);

    // Penalize post_residual that is too small to fit anything useful,
    // smoothly via cubic decay rather than a hard cutoff.
    let dead = (1.0 - norm_pr).powi(3);
    score += 15.0 * dead * norm_pr;

    // Interaction with mean residual: prefer bins whose residual deviates
    // smoothly from the mean (diversity of residual sizes).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev.abs() * (1.0 - progress);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = 1.0 - (pr - n).abs() / cap;
        score -= 12.0 * compat.max(0.0) * (1.0 - progress * progress);
    }

    // Mild penalty for opening new bins when many are already open.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post-residual falls into
    // "usable" classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else if pr <= 5 {
        score += 25.0; // tiny dead space, wasted bin
    } else if pr % 10 == 0 {
        score -= 12.0; // class-aligned leftover, highly reusable
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 20.0; // sub-10 dead space is nearly unusable
    }

    // Fraction-of-capacity classes: residuals near capacity fractions.
    let frac = pr as f64 / bin_capacity as f64;
    if (0.45..0.55).contains(&frac) {
        score -= 5.0; // half-full leftover is flexible
    }
    if frac > 0.9 {
        score -= 4.0; // nearly empty bin again, still very usable
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Harmonic match: next item exactly consumes a class of the leftover.
        if pr % next_item_size == 0 {
            score -= 14.0;
        } else {
            score -= 7.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        score += 6.0; // next item won't fit here anyway; leftover is dead weight
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize spreading across too many open bins when mean residual is high.
    if open_bins_count > 2 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual / bin_capacity as f64 > 0.5 {
            score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        } else {
            // Opening a new bin is bad unless current fit is very poor.
            score += 15.0 + (post_residual as f64 - item_size as f64).abs() * 0.1;
        }
    }

    // Mild tightness reward: smaller item_size relative to residual = better packing.
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward exact match with the lookahead item (k=2 lookahead exploitation).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Pressure from many open bins: when bins are plentiful, prefer tighter
    // packing (reward low post_residual harder); when few bins, spreading out
    // (keeping large residuals) is cheaper, so penalize consuming big bins.
    let bins_f = open_bins_count as f64;
    score -= score * (bins_f / (bins_f + 5.0)) * 0.4;

    // Discourage opening a new bin while open bins still have room, unless
    // the current item is huge relative to remaining capacity.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / 4.0;
        let item_heaviness = item_size as f64 / bin_capacity as f64;
        score += 40.0 + pressure * 10.0 - item_heaviness * 45.0;
    }

    // Mild stream-progression tightening: late in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward when the next item exactly fills the remaining space.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Reward closeness, scaled by how tight the fit is.
            score -= 30.0 / (1.0 + diff / 10.0);
        }

        // Penalize if next item would be stranded: post_residual too small for next item
        // while the current item leaves a large dead zone relative to mean residual.
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 8.0 + (post_residual as f64) * 0.15;
        }

        // Bonus if post_residual could take next item plus still be useful.
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0;
    }

    // Penalize leaving residuals far above the mean (fragmentation risk).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.10; // slight reward for below-mean residuals
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin normally, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 15.0 * (1.0 - progress);
        // But if next item is large and current item is small, a fresh bin may be good.
        if next_item_size >= item_size * 2 && item_size <= 30 {
            score -= 20.0;
        }
        // Attractive when many bins exist with tiny residuals (fragmented state).
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 18.0;
        }
    }

    // Mild penalty for wasting capacity of a nearly-full bin on small items.
    if item_size < 20 && post_residual > 50 {
        score += 6.0;
    }

    // Reward tight overall packing: small post_residual is inherently good.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared waste penalization
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward using bins whose residual matches the item closely
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating very small dead space that nothing can use later
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Time horizon: early in the stream, be conservative (prefer new bins
    // when fits are loose); late in the stream, fill anything available.
    let t = step_index as f64 / total_items as f64;
    score -= t * 20.0 * fit_ratio;
    score += (1.0 - t) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    score += mean_residual * 0.05;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are plentiful/roomy,
        // reward opening a new bin when existing bins are nearly full.
        score += mean_residual * 0.3;
        score -= (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if fit_ratio < 0.4 && t < 0.5 {
            score += 25.0; // avoid wasting fresh bins early on loose fits
        }
    }

    // Mild penalty for very large leftover relative to typical item sizes
    score += (post_residual as f64 / 80.0).powi(3) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted residual
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Later in the stream, we care more about compact residual usage (favor small post_residual).
    let progress_weight = 0.5 + 1.5 * progress * progress; // quadratic ramp-up
    score += progress_weight * norm_pr * pr * (norm_pr - 1.0).abs();

    // Cubic interaction: penalize mid-range residuals more strongly as stream progresses
    let mid_range = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += (0.3 + 1.7 * progress) * mid_range * pr;

    // Perfect-fit reward (smooth, no hard cutoffs)
    let tightness = 1.0 - norm_pr;
    score -= (1.0 - norm_pr * norm_pr) * (pr / (1.0 + pr)) * 6.0 * (0.5 + tightness);

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let gap = (pr - nxt).abs();
        score -= 3.0 * (fits_next / cap) * (1.0 - gap / cap);
        score += 1.5 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it (smooth reward)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).abs();
        score += 4.0 - 6.0 * fragmentation * (1.0 - progress);
    }

    // Mean residual coupling: penalize bins deviating from mean (keeps bin states uniform)
    score += 0.4 * ((pr - mean_residual) / cap).abs() * (1.0 + progress);

    // Many open bins: prefer closing out existing bins over spreading
    score -= (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity quantized into 8 classes
    let class = post_residual / (bin_capacity / 8).max(1);
    let class_bonus = match class {
        0 => 60.0,               // near-perfect fit: heavily reward
        1 => 40.0,
        2 => 20.0,
        3 => 5.0,
        4 => 0.0,
        5 => -10.0,
        6 => -20.0,
        _ => -35.0,              // large leftover: penalize
    };
    score -= class_bonus;

    // Modular dead-space detection: post_residual that no common item size (1..100)
    // can be expected to fill well. Residuals in {0} are perfect; small odd residuals
    // are dead space. Penalize post_residual that is odd and small (hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Integer-division threshold coupling with next item (lookahead k=2)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward keeping this bin usable
            score -= 15.0;
            // extra reward if next item nearly fills the bin after this one
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 25.0;
            }
        } else {
            // next item won't fit after this placement: mild penalty
            score += 8.0;
            // strong penalty if the overflow amount is small (wasted potential)
            let overflow = next_item_size - post_residual;
            if overflow <= 10 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer exact fill
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // cheaper to open a bin early in the stream (more future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // more open bins with high mean residual -> discourage opening another
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual - 50.0).max(0.0) * 0.5;
        // if item is large relative to capacity, opening fresh is more attractive
        score -= item_size as f64 * 0.2;
        // if next item is large too, a fresh bin can host the pair
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += ((bin_residual as f64 - mean_residual) * 0.1).max(-10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful are heavily penalized.
    // Treat residual < 10 (min plausible item) as pure waste; also penalize the
    // awkward band (10..30) where few items fit.
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 30 {
        score += 12.0 + (30 - post_residual) as f64 * 0.8;
    }

    // Reward very tight fits (post_residual small but still >= item floor).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0;
    }

    // Exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that fails to host the lookahead item: mild dead-space penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage scattering across many bins when alternatives exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Align with mean residual: bins with residual far above mean are better targets.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead alignment: next item fits into post_residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (post_residual as f64 / (next_item_size as f64).max(1.0)).min(2.0);
    }
    // Penalize post_residual that is small but nonzero (dead space the next item can't use)
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual dominates).
    // Non-linear: penalize large residuals more than linearly when they are "dead" space.
    let dead_threshold = 10.0;
    if post_residual as f64 > dead_threshold {
        score += (post_residual as f64 - dead_threshold) * 0.6;
    }

    // Reward bins whose residual is close to item size (near-perfect fill).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (bin_residual - item_size) as f64 * 0.3;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    // (creates a chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 + chain_quality * 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving residual too small for the next item (wasted sliver),
        // but only mildly if the sliver is tiny (nearly full bin is good).
        let sliver = post_residual as f64;
        if sliver > 0.0 && sliver < 5.0 {
            score -= 6.0; // nearly-full bin is fine even if next item can't use it
        } else {
            score += sliver * 0.4; // unusable mid-range dead space
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= pressure * 6.0;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when existing
        // bins have plenty of room, or late in the stream.
        score += 15.0 + pressure * 20.0 + progress * 10.0;
        // But if no open bin fits at all, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Early stream: be slightly more willing to open bins (build diversity of residuals).
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    // Mild preference for bins with residual just above item size (best-fit sharpening).
    let gap = bin_residual as f64 - item_size as f64;
    if gap >= 0.0 && gap <= 3.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Reward tight fits: quadratic decay of usefulness of remaining space.
    let tightness = 1.0 - (norm_post * norm_post);
    score -= 2.5 * tightness * cap * 0.1;

    // Smooth progress coupling: later in the stream, prefer filling existing bins harder.
    score -= progress * 3.0 * (1.0 - norm_post);

    // Penalize large post-residual with cubic term (dead space).
    score += 0.4 * norm_post * norm_post * norm_post * cap;

    // Lookahead: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill_after = (post - nxt) / cap;
            score -= 4.0 * (1.0 - fill_after * fill_after);
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += 0.5 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening new bins unless item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 8.0;
        score -= 0.03 * (item_size as f64);
        score += 0.2 * (open_bins_count as f64).ln().max(0.0);
        // Early in stream, opening bins is cheaper.
        score -= 4.0 * (1.0 - progress);
        // If few fitting bins, new bin less costly.
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    // Mean residual coupling: if this bin is far from mean residual, slight penalty.
    let dev = (post - mean_residual).abs() / cap;
    score += 1.0 * dev * (1.0 - progress);

    // Prefer bins whose residual closely matches item (smooth gaussian-like fit reward).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 3.0 * (-10.0 * fit_gap * fit_gap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as u32;

    // Harmonic class logic: decompose post_residual into residue classes mod 10
    // and mod 25; dead space in "awkward" classes is penalized more.
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    score += class10 * 0.08;
    score += class25 * 0.05;

    // Penalize large leftover space quadratically (fragmentation risk)
    score += (pr as f64) * (pr as f64) * 0.0015;

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 2.0 + slack * 0.04;
        } else {
            score += 0.8;
        }
    }

    // Integer-division threshold: perfect or near-perfect fits are strongly favored
    let fits_exact = pr == 0;
    let fits_tiny = pr <= 5;
    if fits_exact { score -= 6.0; }
    if fits_tiny { score -= 2.0; }

    // New-bin candidate handling: bin_residual == bin_capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default: discourage opening a new bin when existing bins fit
        score += 7.0;
        // But if this bin is the only option (nothing else fits), open it
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // If existing fits leave very awkward classes (post_residual >= 40 everywhere),
        // opening fresh may still be preferable for long streams
        let t = step_index as f64 / (total_items.max(1) as f64);
        if pr >= 40 && t < 0.7 {
            score -= 1.0;
        }
    } else {
        // Last-chance bonus: this is the only open bin that fits the item
        if fitting_bins_count == 1 {
            score -= 1.5;
        }
        // Prefer bins below mean residual (tighter bins get used first)
        score -= (mean_residual - (post_residual as f64)) * 0.05;
    }

    // Mild stream-progress term: later in the stream, be slightly more greedy
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Penalize gaps that can't fit the lookahead item (dead space w.r.t. near future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 15.0; // gap likely reusable by next item
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage opening new bins when many are open,
    // unless this placement is very tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as more bins are open / stream progresses.
        score += 10.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow opening if the item is huge and no tight fit exists.
        if item_size > 70 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Favor using existing bins, especially under pressure.
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using it rather than stranding it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual is near the mean (keeps bin profile balanced),
    // and mildly favor bins with larger residual for large items.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * (item_size as f64 - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is a huge win.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.35;
        }
        // If next item can still fit after this placement, mild bonus.
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use: penalize.
            score += (post_residual as f64) * 0.25;
        }
    } else {
        // Last item: just minimize leftover.
        score = post_residual as f64;
    }

    // Relative fill quality: bins below mean residual are emptier; prefer filling tighter bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * (open_bins_count as f64).sqrt();
    }

    // Mild late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on post-residual (dead space grows superlinearly).
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize residuals too small to be useful later.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Small usable residual granularity: reward leaving residuals that many item sizes can use.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Global state: when many bins are open, prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or late in stream,
        // but allow opening when mean residual of open bins is very fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 + 8.0 * open_bins_count as f64 + 20.0 * progress - fragmentation.min(40.0);
    } else {
        // Reward placing into bins whose residual is below mean (consolidating fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        // Early stream: slight preference for existing bins to keep bin count low.
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize creating residuals in the "awkward zone" (1..10) that rarely fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (waste compounds),
    // early on, tolerate larger residuals to keep bins flexible.
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += (pr / cap).powi(2) * (0.5 + 2.5 * t);

    // Reward filling large fraction of the bin (high fill ratio)
    let fill = item_size as f64 / cap;
    score -= fill * fill * (1.0 + t);

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - nxt / cap) * (0.3 + 0.7 * t);
        } else {
            // penalize blocking the next item
            score += ((nxt - pr) / cap) * (0.2 + 0.8 * t);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 0.4 + 0.6 * t;
    }

    // New-bin candidate: penalize opening a bin unless the item is huge
    // relative to current mean residual (i.e., existing bins fit poorly)
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs() / cap;
        score += 0.6 - 0.5 * (item_size as f64 / cap) - 0.4 * mean_fit_gap;
        // late in stream, opening fresh bins is less attractive
        score += 0.3 * t;
    }

    // Mild penalty tied to mean residual: placing into a bin far below
    // mean residual spreads waste; prefer bins near/below mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // ---- Harmonic class logic on post_residual ----
    if pr == 0 {
        // Perfect fit: strongest reward
        score -= 100.0;
    } else {
        // Dead-space class: residuals < 10 are nearly unusable (item sizes 1..100)
        if pr < 10 {
            score += 30.0;
        }
        // Decimal harmonic class: multiples of 10 are highly reusable
        if pr % 10 == 0 {
            score -= 10.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
        // Integer-division thresholds: coarse classes of leftover capacity
        let class = pr / 20; // 0..5
        score += class as f64 * 3.0; // larger leftovers mildly penalized beyond raw value
        if pr >= 80 {
            score += 10.0; // huge leftover = wasted bin space
        }
    }

    // ---- Lookahead (k=2) coupling ----
    if next_item_size > 0 {
        if next_item_size == pr {
            // Next item exactly fills this bin's leftover
            score -= 60.0;
        } else if next_item_size < pr {
            let left_after_next = pr - next_item_size;
            if left_after_next == 0 {
                score -= 45.0;
            } else if left_after_next < 10 {
                score += 8.0; // next item leaves dead space
            } else if left_after_next % 10 == 0 {
                score -= 12.0; // harmonic leftover
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover
            score += 6.0;
        }
    }

    // ---- Last-chance bin: only fitting bin should be strongly favored ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mismatch = (mean_residual - item_size as f64).abs();
        // Base new-bin score is high (post_residual == capacity) so it loses to good fits,
        // but drop it when existing open bins match poorly.
        score = 40.0 + mismatch * 0.6 + pr as f64 * 0.3 - progress * 10.0;
        if next_item_size >= 60 {
            score -= 8.0; // big next item: fresh bin more attractive
        }
        if fitting_bins_count == 1 {
            // The single fitting open bin is likely tight; keep new bin competitive
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic future item are pure waste -> heavy penalty.
    // Treat gaps <= 10 (below min item size) as total dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        // Small gap: unlikely to be usable, but not impossible.
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (low post residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation); with few open bins, new-bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: penalize more when many bins open.
        score += 15.0 + 3.0 * pressure;
        // But if the item is large and no bin fits well, new bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward more when open-bin pressure is high.
        score -= 2.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 10 {
            score += 10.0; // leaves a nearly-dead gap after next item
        } else {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight -> prefer consolidating into it.
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the remaining residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 700.0;
    }
    // Next item fits into post_residual: chain placement possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Next item will NOT fit: post_residual becomes dead space for the lookahead.
    if next_item_size > 0 && next_item_size > post_residual {
        // Penalize more when post_residual is small (unusable sliver).
        if post_residual < 10 {
            score += 80.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: bins tighter than average are good to fill further.
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.5;

    // Last-chance bin: only bin that fits this item — strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }
    // Many bins fit: prefer the tightest (post_residual already handles this),
    // but mildly discourage wasting a nearly-full bin's uniqueness.
    if fitting_bins_count > 1 && post_residual > 0 {
        score += post_residual as f64 * 0.05;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity if any
    // open bin gives a decent fit. Make the empty bin attractive only when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        } else if item_size >= 50 {
            score -= 150.0; // big items pair well in a fresh bin
        } else {
            score += waste * 0.6 + 100.0; // discourage opening for small items
        }
    }

    // Late in stream: consolidate, avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    // Slight preference for filling bins when many are open (bin count pressure).
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * tightness * tightness;
    }

    // Penalize dead space that no plausible future item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // Extra reward if next item fills the bin almost completely after placement.
            let nr = post_residual - next_item_size;
            if nr == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins over emptier ones (best-fit flavor scaled by open-bin load).
    let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * fill_frac;

    // Time horizon: early in stream, encourage keeping residuals large (flexibility);
    // late in stream, prioritize closing bins out (minimize residual aggressively).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.04 * post_residual as f64;
    score -= t * 0.05 * (bin_capacity - post_residual) as f64;

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    // into already-open bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual / (bin_capacity as f64));
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large post_residual in fitting bins is already penalized) or stream is early.
    if bin_residual == bin_capacity {
        // Base new-bin cost: resist opening new bins mildly.
        score += 3.0;
        // But if many bins are open and this item would leave big waste elsewhere,
        // a fresh bin keeps flexibility early on.
        if t < 0.5 && post_residual_proxy_hack(item_size, bin_capacity) > 20 {
            score -= 4.0;
        }
        // Late stream: strongly discourage new bins.
        if t > 0.8 {
            score += 10.0;
        }
    }

    score
}

// Helper-free proxy: expected post-residual if item went into an average bin.
fn post_residual_proxy_hack(item_size: u32, bin_capacity: u32) -> u32 {
    let m = (bin_capacity as f64 * 0.5) as u32;
    m.saturating_sub(item_size)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: tightness of fit, non-linearly amplified
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, squeeze hard.
    let w = 1.0 + 2.5 * progress * progress * (3.0 - 2.0 * progress);
    score *= w;

    // Reward filling a bin completely (post_residual near zero)
    score -= 12.0 * (1.0 - pr / cap).powi(6);

    // Lookahead: penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // dead space for the next item
            score += 0.35 * (nx - pr).min(40.0);
        } else {
            // next item fits nicely: reward proportional to residual consumed
            score -= 0.5 * (nx / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate handling: make fresh bins mildly unattractive
    // unless existing residuals are large / item is big.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score = cap + 20.0 * progress;
        // open a new bin if existing bins are mostly full (mean residual small)
        score += 0.6 * mean_residual;
        score -= 2.0 * openness.max(0.0).ln().max(0.0);
        // if item is large, opening fresh is more acceptable
        score -= 0.15 * item_size as f64;
        // if very few bins fit, opening is fine
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild penalty for many open bins (fragmentation control)
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot band" does the leftover fall in?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: tiny leftover (1..=9) -> nearly perfect, reward.
    // Class 2: medium leftover (10..=29) -> mildly usable, small reward.
    // Class 3: large leftover (30..=59) -> neutral.
    // Class 4: huge leftover (60..=99) -> wasteful placement, penalize.
    let harmonic_class = if post_residual == 0 { 0u32 }
        else if post_residual <= 9 { 1 }
        else if post_residual <= 29 { 2 }
        else if post_residual <= 59 { 3 }
        else { 4 };

    match harmonic_class {
        0 => score -= 40.0,
        1 => score -= 22.0,
        2 => score -= 8.0,
        3 => score -= 0.0,
        _ => score += 12.0,
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // leftover after chaining the next item
            let chain_left = post_residual - next_item_size;
            if chain_left <= 5 {
                score -= 15.0;
            } else if chain_left > 50 {
                score += 6.0;
            }
        } else {
            // next item cannot use this bin's leftover; leftover is likely dead
            // unless another bin or new bin handles the next item.
            if post_residual < 10 {
                score += 4.0; // small dead space, mild penalty
            } else if post_residual < next_item_size {
                score += (post_residual as f64) * 0.08;
            }
        }
    }

    // Integer-division threshold: residual divisible into coarse 20-blocks
    // (harmonic bands of capacity). Finer alignment is better.
    let band = post_residual / 20;
    score -= (4 - band.min(4)) as f64 * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if harmonic_class >= 3 {
            score += 10.0; // soften if fit is bad
        }
    }

    // New-bin candidate: give it a moderate baseline so it wins only when
    // all open bins offer poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 - (mean_residual * 0.15).min(20.0);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure to keep mean residual low (pack tightly overall).
    score += mean_residual * 0.03;

    // Perfect-fit modulo bonus: post_residual exactly divisible by common
    // item granularities (10, 20, 25) suggests reusable leftover.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1) is impossible, but gaps of
    // 1..=9 are "dead" if the distribution's minimum is 10; be distribution
    // agnostic: penalize gaps smaller than next_item_size when nonzero.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 1.5;
        }
        // Tight fits are excellent: reward near-perfect packing.
        if post_residual <= 3 {
            score -= 12.0;
        }
    } else {
        // Perfect closure of a bin.
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many open bins early;
    // encourage consolidating into open bins rather than opening new ones.
    score += (open_bins_count as f64).sqrt() * 1.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., they are already "full-ish") to keep large residuals available.
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Slight preference for opening a new bin late in the stream is removed:
    // consolidation is always preferred; add mild new-bin penalty.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but zero is golden.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly fills the post-residual,
    // strongly favor this bin (perfect 2-item chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how much space it consumes.
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * consumed;
            // Bonus for leaving a small usable remainder after the next item too.
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit here: penalize bins whose residual would be
            // "almost big enough" (wasted opportunity), less so for tiny residuals.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Penalize residuals far below mean (dead space relative to fleet average),
    // reward bins with above-average residual absorbing items.
    let r = post_residual as f64;
    let dev = r - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or all open bins are nearly full.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        let fleet_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        // Open a new bin only when item is big or fleet is quite full.
        score += 30.0 - 45.0 * load_ratio - 40.0 * fleet_fullness;
        // Lookahead: a fresh bin guarantees the next item also fits.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Early in stream: be slightly conservative about wasting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = post;

    // Reward tight fits: superlinear penalty on leftover space.
    score += 0.35 * (post / cap).powf(2.0) * cap;

    // Penalize placing small items into large residuals (waste of prime space),
    // scaled by how much slack is being burned relative to the item.
    let slack_ratio = residual / cap;
    score += 6.0 * slack_ratio * (1.0 - item / cap) * (1.0 - progress);

    // Last-chance bin: strong reward, this bin disappears if unused.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (item / cap);
    } else {
        // Slight penalty when many bins compete: prefer spreading load.
        score += 1.5 * ((fitting_bins_count as f64).ln().max(0.0));
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    // (chaining items leaves no dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - post / cap);
        } else if nxt <= residual {
            // Next item fits the current bin but not after this placement:
            // mild penalty for breaking a better pairing.
            score += 3.0 * (1.0 - progress);
        }
        // If next item is large, prefer consolidating now to keep small residuals
        // from fragmenting.
        if nxt > post && nxt > 0.6 * cap && post < nxt {
            score += 2.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // -> discourage opening/keeping loose bins, prefer filling existing ones.
    let frag = mean_residual / cap;
    score += 4.0 * frag * (open_bins_count as f64).sqrt() * 0.25;

    // Late in the stream: be greedy about closing bins out.
    score -= 5.0 * progress * (1.0 - post / cap);

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large or existing bins are fragmented; otherwise make it unattractive so
    // we fill open bins first.
    if bin_residual == bin_capacity {
        let item_ratio = item / cap;
        if item_ratio > 0.5 {
            score -= 10.0 * item_ratio; // large items start fresh bins happily
        } else {
            score += 18.0 * (1.0 - item_ratio); // small items should use leftovers
        }
        // If existing bins are very fragmented, a fresh bin is fine.
        if frag > 0.5 {
            score -= 6.0 * frag;
        }
        // Early stream: new bins are cheap; late stream: avoid opening them.
        score += 10.0 * progress;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: reward small post-residual with a non-linear (quartic) shaping
    let mut score = pr as f64;
    score -= 40.0 * (1.0 - x).powi(2) * (1.0 - progress);
    score += 25.0 * x.powi(4);

    // Smooth coupling of post-residual with stream progress:
    // early on, tolerate large residuals; late, penalize them strongly
    score += 60.0 * x * x * progress;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = (x * cap / 10.0).floor();
    score -= 15.0 * dead / (1.0 + progress);

    // Lookahead: if next item fits the post-residual, reward strongly (smooth bell)
    if next_item_size > 0 {
        let fit = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = (post_residual - if fit > 0.0 { next_item_size } else { 0 }) as f64 / cap;
        score -= 30.0 * fit * (1.0 - slack * slack) * (1.0 - 0.5 * progress);
        // penalize leaving a gap just under next item size
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 20.0 * (1.0 - gap).max(0.0) * gap * 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins below mean residual (tighter bins) with smooth scaling
    score += 10.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * (open_bins_count as f64).ln().max(0.0) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "dead zone" (small but non-zero) are penalized; exact/zero leftover
    // is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Class the residual by its fraction of capacity (harmonic buckets)
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 25.0; // tiny unusable sliver -> dead space
        } else if frac < 0.25 {
            score += 8.0;
        } else if frac < 0.5 {
            score -= 5.0; // medium residual is reusable
        } else {
            score -= 12.0; // large residual, very reusable
        }
    }

    // Lookahead coupling: reward when post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact chaining bonus (harmonic divisibility check)
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // leftover can't fit next item: penalize proportionally to how
            // close it came (wasted opportunity)
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 12.0 * (1.0 - gap / next_item_size as f64);
        }
    } else {
        // last item: strongly prefer zero-waste
        score -= 15.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its residual is full capacity
        score += 30.0;
        // open new bins more readily late in the stream (less future to plan)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // if many bins are open with small mean residual, prefer consolidating
        score += 0.5 * open_bins_count as f64;
    } else {
        // prefer bins tighter than the average residual (best-fit flavor)
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (1..=100) fits well;
    // gaps in (0..=12) are practically dead, gaps up to ~30 are risky.
    if post_residual > 0 {
        if post_residual <= 12 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 25 {
            score += 25.0; // hard to fill
        } else if post_residual <= 40 {
            score += 8.0; // moderate risk
        } else {
            // Large residual: reward tightness relative to capacity
            score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Exact-fill lookahead: if next item exactly consumes post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits in post_residual, mild reward (chaining placements).
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot fit here, mild penalty for wasted chain potential.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // encouraging consolidation into fewer bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate handling: default mild penalty so we prefer existing bins,
    // but relax it when the fit is terrible (large dead space would be created).
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let bad_fit = if dead <= 12 { 45.0 } else if dead <= 25 { 20.0 } else if dead <= 40 { 6.0 } else { 0.0 };
        // Open new bin when existing placements would create dead space,
        // scaled by stream progression (late stream: be more conservative).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 5.0 + bad_fit - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 8.0 * (1.0 - tightness.min(1.0));

    // Exact / near-exact fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space for the next item: penalize proportionally.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // If next item fits comfortably in post-residual with room to spare,
        // mild reward for keeping the stream flowing in this bin.
        if post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (wasteful bins) mildly;
    // prefer placing into bins with more residual than average.
    if bin_residual as f64 > mean_residual {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive if
    // no open bin fits well (post_residual large or few fitting bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If many bins fit the item, discourage the new bin.
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
        // If the next item is large and would leave this bin nearly empty anyway,
        // a fresh bin is reasonable.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < post_residual as f64 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong best-fit core: exact fills are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits non-linearly (tightness ratio).
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);
    }

    // Lookahead coupling: favor leaving residuals that the next item can use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // perfect handoff
        } else if post_residual >= next_item_size {
            score -= 40.0 * (post_residual as f64 - next_item_size as f64 + 1.0).recip().max(0.01);
        } else {
            // Residual too small for the next item: penalize dead space, more if item is large.
            score += 15.0 + 0.25 * next_item_size as f64;
        }
    } else {
        // Last item: any placement is fine, prefer minimal residual.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are crowded (large item, small residuals).
    if bin_residual == bin_capacity {
        let avg_crowding = mean_residual / bin_capacity as f64;
        // If existing bins are roomy, discourage opening a new one.
        score += 80.0 * (1.0 - avg_crowding);
        // Large items relative to mean residual justify opening fresh bins.
        score -= (item_size as f64 - mean_residual).max(0.0);
        // Early in the stream, opening bins is cheap; late, reuse matters.
        score += 40.0 * t;
    }

    // Mild penalty for placing into a bin whose residual is far below
    // the mean (keeps larger residuals available for bigger items).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    }

    // Slight bonus for consolidating when many bins are open.
    score -= (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post_residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early in stream, waste is cheap; late in stream, punish large residuals more.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * cap * x * x * (1.0 - x);

    // Penalize residuals that are too small to ever fit a future item (dead space)
    // smooth via sigmoid-like term on min item size (unknown, use next_item_size)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let unusable = ((ns - pr) / cap).max(0.0);
        score += 8.0 * unusable * (1.0 + progress);
    }

    // Reward using bins that are nearly full (x small) with extra cubic term
    score -= 3.0 * (1.0 - x).powi(3) * cap * 0.1;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when residuals are high
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: neutral-ish baseline; only prefer it when all open bins fit poorly
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).abs();
        score += 20.0 - 10.0 * (1.0 - (mean_gap / cap).min(1.0));
        // late in stream, opening new bins is cheaper than fragmenting
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that commonly combine
    // with typical item sizes (multiples of 5/10) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        60.0 // perfect fit: strong reward
    } else if pr % 10 == 0 {
        25.0
    } else if pr % 5 == 0 {
        12.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Dead-space penalty: small unusable residues are worse than large ones.
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr >= 10 && pr < 20 {
        score += 10.0;
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as i64 - item_size as i64) >= 0
            && mean_residual >= item_size as f64 * 0.9;
        if good_fit_exists {
            score += 55.0; // discourage opening a new bin when open ones fit decently
        } else {
            score -= 15.0; // prefer a fresh bin over a terrible fit
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if the next item can exactly fill this bin's post-residual,
    // reward placing current item here (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        } else if next_item_size > pr {
            // next item won't fit here; slight penalty for leaving a bad residue
            score += 5.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Penalize moderately small gaps that are unlikely to fit future items.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // If the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover becomes dead space.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and spread-out placements).
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in the stream, opening bins is cheap-ish; late in the stream,
    // consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than average (good fits relative to fleet state).
    score += 5.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact pairing of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect two-item fill
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0 * (1.0 - gap / 60.0); // next item still fits after this placement
        } else {
            score += 6.0 + gap * 0.15; // next item won't fit: dead space risk
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 25.0;
    }

    // Relative-to-mean residual shaping: bins tighter than average are more valuable.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist, unless nothing fits well.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 5.0 * open.sqrt() + 10.0 * (1.0 - progress);
        // Allow new bin if existing fits are all poor (large post residual) and next item is big.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Penalize small unusable leftovers (dead space), unless it's a near-perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill bonus
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty if we waste residual.
        score += 4.0 * (post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals large (flexibility);
    // late in the stream, prefer filling bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate logic: only attractive when current bin fits are poor
    // (item leaves big post_residual everywhere or few fitting bins).
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_elsewhere = if fitting_bins_count > 0 {
            (bin_capacity.saturating_sub(item_size)) as f64 / bin_capacity as f64
        } else {
            1.0
        };
        let early = 1.0 - progress;
        // New bin is penalized normally, but less so when fits are wasteful or stream is early.
        score += 15.0 - 12.0 * waste_elsewhere * (0.5 + 0.5 * poor_fits) - 8.0 * early * poor_fits;
    }

    // Mild penalty for spreading across many bins when this bin is already fragmented.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, superlinearly (dead space is quadratic bad).
    let mut score = pr + (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to item size gets a bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Smooth interaction: as stream progresses, prefer filling existing bins more aggressively.
    let urgency = progress * progress;
    score -= urgency * (cap - pr) * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mild penalty scaled by overshoot.
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: neutral-ish base; penalize slightly more early on,
    // and increasingly when many bins are already open with small mean residual.
    if bin_residual == bin_capacity {
        score += 2.0 + 8.0 * progress;
        score += (open_bins_count as f64).ln().max(0.0) * (cap - mean_residual) * 0.05;
    } else {
        // Slight preference for bins with residual close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (integer division thresholds) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect or near-perfect fill -> heavily reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= bin_capacity / 20 {
        score -= 40.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    } else {
        // large dead space: penalize extra
        score += 20.0;
    }

    // --- Harmonic class of the item itself (capacity fractions) ---
    let item_class = item_size / (bin_capacity / 4); // 0,1,2,3 for quarters
    match item_class {
        0 => score -= 6.0,           // tiny items fit anywhere cheaply
        1 => score -= 2.0,
        2 => score += 0.0,
        _ => score += 6.0,           // large items: prefer tightest fit anyway
    }

    // --- Modulo arithmetic on post_residual vs next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size;
        // Does the next item exactly consume the post residual? Huge reward.
        if nxt == post_residual as u32 {
            score -= 55.0;
        } else if nxt <= post_residual as u32 {
            // next item fits: reward proportional to how cleanly
            let rem = (post_residual - nxt) % (bin_capacity / 10).max(1);
            if rem == 0 {
                score -= 18.0; // leaves a harmonic remainder
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize wasting it
            score += 12.0;
        }
        // modulo coupling: residual divisible by next item's harmonic class
        let nxt_class = nxt / (bin_capacity / 8).max(1);
        if nxt_class > 0 && post_residual as u32 % (nxt_class * (bin_capacity / 8).max(1)) == 0 {
            score -= 10.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // only this bin can take the item; opening a new bin is worse
        score -= 30.0;
    }

    // --- New-bin candidate: only attractive when nothing fits well ---
    if bin_residual == bin_capacity {
        // baseline penalty: prefer using existing space unless it's hopeless
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // early in stream, a fresh bin is cheaper to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // --- Mean residual coupling: avoid drifting far from fleet mean ---
    score += 0.15 * (post - mean_residual).abs();

    // --- Congestion: many open bins -> prefer tighter packing ---
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= 10)
    // is pure waste; a residual just below a mid-size item is also suspect.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Unusable dead space: heavy penalty.
        score += 150.0;
    } else if post_residual < 25 {
        // Narrow gap: mild penalty scaled by gap size.
        score += (25.0 - post_residual as f64) * 3.0;
    }

    // Reward keeping residual large enough to be flexible for future items.
    if post_residual >= 50 {
        score -= 20.0;
    } else if post_residual >= 30 {
        score -= 8.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; slight bonus for tight fits.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= pressure * (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here anyway; penalize leaving a gap that
            // neither fits next item nor is reusable.
            if post_residual < next_item_size && post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // Early in the stream, be slightly more willing to use existing bins
    // (fewer bins opened early compounds savings).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: make an empty bin mildly unattractive unless
    // existing placements look bad (high mean residual waste).
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual > 40.0 {
            score -= mean_residual * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = (post_residual as f64) * 1.0;

    // Strong reward when the leftover exactly or nearly matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 10.0 + (nxt - post_residual as f64).min(30.0);
        }
    }

    // Relative to mean residual: prefer bins that deviate favorably
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.4; // tighter than average: good
    } else {
        score += (pr - mean_residual) * 0.3; // looser than average: bad
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; make it slightly worse than a decent fit
        // but better than a very poor fit in an open bin
        score = 55.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can chain large items
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Penalize creating tiny unusable slivers (<10 assumed min item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            // Dead space that the next item cannot use; penalize proportionally.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score += 25.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score -= 10.0; // near-perfect fit bonus
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are large (poor fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let avg = mean_residual.max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Penalize new bins generally; discount penalty when open bins are mostly full.
        score += 45.0 - 0.5 * avg - 4.0 * open_pressure + 10.0 * progress;
        // If item is huge, a fresh bin is often the best home.
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild preference to fill bins with smaller residuals overall.
    score -= 0.15 * bin_residual as f64;

    // Global balance: encourage using bins with below-average residual slightly less
    // (keep some bins flexible), above-average residual bins slightly more.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth progress coupling: tighten residual tolerance as stream progresses
    let tightness = 0.5 + 1.5 * progress * progress;
    score += tightness * pr * norm_pr;

    // Reward near-perfect fits smoothly (quadratic trough near zero residual)
    score -= (1.0 - norm_pr).powi(2) * item_size as f64 * 0.5;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if next item can use the post-residual, reward this bin
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 - gap / cap;
        if fit_quality > 0.0 {
            score -= 10.0 * fit_quality * fit_quality;
        }
    }

    // Penalize bins that are already slack relative to mean residual
    score += 2.0 * (bin_residual as f64 - mean_residual).max(0.0) * (0.3 + 0.7 * progress);

    // Mild penalty for many open bins, encouraging consolidation
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // New-bin candidate: keep it neutral-slightly-worse unless residual is huge
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "waste-like" the leftover is.
    // Residuals that are multiples of common item sizes (or their complements)
    // are more likely to be filled later -> reward (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Harmonic classification via integer division thresholds on post_residual.
    // Class 0: tiny leftover (0..=5)  -> nearly perfect fit, big reward.
    // Class 1: small (6..=15)         -> still very usable.
    // Class 2: medium (16..=40)       -> moderate.
    // Class 3: large (41..=100)       -> mostly empty, poor placement.
    let class = post_residual / 15; // 0,1,2,3...
    let class_penalty = match class {
        0 => -18.0,
        1 => -6.0,
        2 => 4.0,
        _ => 14.0,
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: leftover divisible by common item
    // sizes (10, 20, 25, 50) is reusable -> reward.
    let reusable = (post_residual % 10 == 0 && post_residual > 0)
        || (post_residual % 25 == 0 && post_residual > 0)
        || post_residual == 50;
    if reusable {
        score -= 8.0;
    }

    // Coupling with next_item_size: if the next item fits exactly into the
    // post residual, strongly favor this bin (perfect lookahead chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves a residual; evaluate the chain quality.
            let chain_residual = post_residual - next_item_size;
            score -= 10.0 - (chain_residual as f64) * 0.15;
        } else {
            // Next item cannot use this bin's leftover -> mild penalty scaled
            // by how "dead" the leftover is.
            score += frac * 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has a huge base residual; make
    // it attractive only when no open bin offers a decent fit, i.e., when the
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // If the item is big, starting fresh is cheap (it leaves a large,
        // usable residual complement).
        let big_item = (item_size as f64) / cap;
        score -= big_item * 25.0;
        // If many bins are open and mean residual is large, prefer existing
        // bins (penalize new bin less when mean residual is small).
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Prefer tighter fits among open bins: reward small pre-residual gap.
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.05;
        // Prefer bins whose residual is close to the item (best-fit flavor)
        // with a harmonic scaling on the gap.
        let gap = bin_residual - item_size;
        let gap_class = gap / 10;
        score -= match gap_class {
            0 => 5.0,
            1 => 2.0,
            _ => 0.0,
        };
    }

    // Global pressure: when many bins are open relative to progress, tighten
    // scoring to discourage waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > progress * (total_items as f64) * 0.5 {
        score += pr * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful later are heavily penalized. Define "unusable" as residual
    // below the minimum plausible item size (1..100 stream, but small gaps
    // under ~12 rarely get filled); the smaller and more stranded, the worse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 4.0 * progress; // later in stream, less patience for gaps
    if (post_residual as f64) < dead_threshold {
        // Quadratic dead-space penalty, stronger as stream progresses.
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * (1.5 + 2.0 * progress);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins; the more
    // bins already open, the more we favor packing into existing ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // attractive when existing bins would waste large dead space or when
    // the next item pairs well with the residual left here.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins fit item.
        score += 12.0 + 3.0 * fitting_bins_count as f64;
        // If the next item would fit exactly in the fresh residual left by
        // this item, opening a new bin is fine (pairing bonus).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
        // Late in the stream, opening new bins is cheap since tail items
        // can't fill old bins anyway.
        score -= 10.0 * progress;
    } else {
        // Existing bin: mild bonus if the leftover residual can host the
        // lookahead item (good chaining).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        } else if next_item_size > 0 && post_residual > 0 {
            // Residual too small for next item: penalize proportional to waste.
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.15;
        }
        // Favor bins whose residual is close to the item (tight fit).
        score -= (bin_residual - item_size) as f64 * 0.1;
        // Slightly favor bins below mean residual (packing the emptier ones
        // keeps a few large-residual bins available for big future items).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is a jackpot: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Proximity reward: the closer post_residual is to next_item_size,
            // the better (bounded influence).
            score -= (30.0 / (1.0 + gap * 0.15)) * (next_item_size as f64 / bin_capacity as f64);
        }
        // Penalize post_residuals that are large but useless for the next item
        // (dead space that no plausible item can consume).
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just minimize leftover waste.
        score += 20.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    // A post_residual well below mean_residual means we compressed this bin
    // more than average — desirable.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate handling: an empty bin has huge residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins fit poorly:
        // few fitting bins or very fragmented (high mean residual).
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (mean_residual / bin_capacity as f64).powi(2) * 0.5
                + if fitting_bins_count == 1 { 0.35 } else { 0.0 }
        };
        // Base high cost for a new bin, discounted by pressure.
        score += 55.0 * (1.0 - pressure.min(1.0));
        // Early in the stream, new bins are cheaper to open.
        score -= (1.0 - step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    // Slight preference for tighter fits overall (nonlinear in fill ratio).
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= fill * fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is barely consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin only if we DON'T place current item here
            score += 6.0;
        }
        // If next item is large, prefer leaving roomy bins
        if next_item_size > 50 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: strong reward to use the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let time = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, avoid bin proliferation.
        score = 45.0 + 40.0 * time + 60.0 * pressure + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin is useful
        }
    }

    // Mild preference for bins deviating from mean residual (keep diversity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small global load balancing: many open bins -> prefer filling existing ones.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize large residual, quadratically (dead space avoidance)
    let mut score = pr * (1.0 + 0.6 * x);

    // Non-linear coupling with stream progress: early on tolerate large residuals,
    // late in stream penalize them more aggressively (polynomial interaction)
    let progress_term = 0.5 + 1.5 * progress * progress;
    score *= progress_term;

    // Smooth interaction: residual squared times progress (cubic coupling)
    score += (x * x) * cap * (progress * (1.0 - progress) * 4.0) * 2.0;

    // Reward tight fits: subtract for small post residual, stronger late
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);

    // Lookahead: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_margin = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        let bonus = fit_margin * (1.0 - nx) * 15.0 * (0.5 + progress);
        if pr >= next_item_size as f64 {
            score -= bonus;
        } else {
            score += bonus * 0.5;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is unusually roomy
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += (x - mean_residual / cap).abs() * 8.0 * openness;

    // New-bin candidate: keep neutral-ish, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.6 * progress) + (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual by capacity fraction.
    let cap = bin_capacity as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Penalize dead space quadratically, but give harmonic-class discounts.
    score += (post_residual as f64) * (post_residual as f64) / (cap * cap) * 10.0;

    // Modulo-class logic: residuals near multiples of 25 are more reusable.
    let res = post_residual;
    let class = res % 25;
    let class_bonus = match class {
        0 => 12.0,
        1..=5 => 6.0,
        20..=24 => 5.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize wasted small residual less if it's a "dead class".
            if post_residual < 10 {
                score -= 8.0; // tiny residual is nearly dead anyway, acceptable
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tight bins relative to mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a bin is fine early, costly late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score = capacity minus a progress discount.
        score = cap - 20.0 * (1.0 - progress);
        if post_residual == cap {
            // Empty new bin: only attractive if item is large or few fitting bins.
            if item_size >= 50 || fitting_bins_count == 0 {
                score -= 10.0;
            }
        }
    }

    // Integer-division threshold: residuals divisible into quarter chunks are valuable.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual >= (quarter as u32) && post_residual < (3.0 * quarter) as u32 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let dead_threshold = 10.0; // smallest item size seen in typical streams
    if (post_residual as f64) < dead_threshold {
        score -= 500.0 * (1.0 - post_residual as f64 / dead_threshold);
    }

    // Tightness reward: quadratic bonus for near-perfect fits.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize medium dead gaps that can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap still reusable by next item
    }

    // Open-bin pressure: prefer consolidating into existing bins as bin count grows.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Slight pull toward bins with residuals near the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly favor bins that become perfectly full.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward relative to item size: small post_residual is good.
    let tightness = (post_residual as f64) / (item_size as f64).max(1.0);
    score += tightness * 20.0;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement creates a perfect two-item packing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover after the lookahead placement.
            let second_leftover = post_residual - next_item_size;
            score += (second_leftover as f64) * 0.8;
        } else {
            // Next item does not fit here: slight penalty for stranding capacity.
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Penalize bins whose residual is far from the mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64) * 3.0;
        // Discourage new bins as stream progresses (sunk cost of open bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + open_penalty + progress * 30.0;
        // Allow a new bin if the item is large and would leave little dead space.
        score -= (item_size as f64) * 0.4;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit baseline already captured by post_residual.
    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead: if the next item can fit exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use the leftover: dead space risk grows
            // with how small the leftover is relative to the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.05 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so we prefer reusing open bins
    // unless the fit elsewhere is very poor. Penalize more when many bins
    // are already open (fragmentation control).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (filling the "driest" bins first),
    // keeping larger residual bins flexible for future big items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more conservative with open bins
    // (keep flexibility); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Smooth non-linear coupling: reward tight fits more as stream progresses.
    score -= (fill * fill) * (30.0 + 70.0 * progress);

    // Penalize large dead space quadratically (wasted capacity).
    score += (post / cap) * (post / cap) * 40.0;

    // Last-chance bonus: strongly favor the only bin that fits (avoid opening new bin).
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; else penalize mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress * 0.5);
        score += 8.0 * (gap / cap) * (gap / cap);
    }

    // Prefer bins with below-mean residual (tighter bins get priority).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight penalty for opening a new bin when many bins are open and item is small.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - item / cap);
        score -= 8.0 * progress; // late in stream, new bins are acceptable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: post_residual is a multiple of 16 (nice power-of-two friendly slot)
    // Class 1: multiple of 8; Class 2: multiple of 4; else awkward.
    let harmonic_class = if post_residual % 16 == 0 {
        0
    } else if post_residual % 8 == 0 {
        1
    } else if post_residual % 4 == 0 {
        2
    } else {
        3
    };
    score -= (3 - harmonic_class) as f64 * 3.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Small dead space is bad if it can't fit even the smallest item.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    }

    // Lookahead coupling: does the leftover pair with the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item fits here too; reward tight two-item packing
            let gap = post_residual - next_item_size;
            if gap < 8 {
                score -= 120.0;
            } else {
                score -= 30.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Integer-division threshold on residual: bins whose residual falls into
    // "large chunk" classes are more valuable to preserve -> discourage wasting them.
    let big_chunk = bin_residual / 32; // 0..3 classes
    if big_chunk >= 2 {
        score += (big_chunk as f64) * 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // prefer the tightest among several candidates (post_residual already does this)
        score += (fitting_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: an empty bin is a precious resource.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if the item is large or nothing fits well.
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 150.0 * pressure;
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score += 25.0; // save fresh bin for the big next item
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    // Mild penalty proportional to how much worse this bin is vs the mean residual.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit a mid-range item (<= 25) are semi-dead.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap just barely too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size + 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (penalize the new-bin candidate and diffuse placements).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 2.5;
    } else {
        score -= pressure * 0.8;
    }

    // Prefer bins tighter than the mean residual (consolidating space).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Slight preference for tighter fits overall (quadratic dead-space cost).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits the post residual exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let slack = post - next;
            // exact match is ideal; penalize slack quadratically
            score -= 60.0 - 0.02 * slack * slack;
            if slack == 0.0 {
                score -= 40.0; // perfect 2-step chain
            }
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 0.15 * (next - post);
        }
    }

    // Penalize residuals far below the mean residual (fragmenting small leftovers)
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Discourage opening a new bin when a reasonable fit exists in an open bin
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty unless post residual is very usable
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Tight fits are good: reward small post residuals
    if post_residual > 0 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (small post_residual dominates the choice).
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * 12.0;

    // Penalize tiny unusable slivers more than proportional (dead space).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0;
        // Extra reward if next item fits almost exactly.
        let next_slack = post - next_item_size as f64;
        score -= (1.0 - next_slack / cap) * 4.0;
    } else if next_item_size > 0 {
        // Penalize leaving space the next item cannot use.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when few bins fit the item,
    // or when all open residuals are small relative to the item.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let open_pressure = (open_bins_count as f64).ln().max(0.5);
        let mean_fit = mean_residual / item_size.max(1) as f64;
        let mut open_penalty = 14.0;
        open_penalty -= scarcity * 6.0;
        open_penalty -= (1.0 - mean_fit.min(1.0)) * 4.0;
        // Late in the stream, keep using existing bins more aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_penalty += progress * 6.0;
        open_penalty *= open_pressure.max(1.0).min(3.0);
        score += open_penalty;
    }

    // Mild preference for filling bins closer to the mean residual state.
    let dev = (post - mean_residual).abs();
    score -= (1.0 - dev / cap).max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling bins tightly; later, tolerate slack to keep bins reusable
    let progress_weight = 0.35 * t * t - 0.15 * t;
    score = score * (1.0 + progress_weight);

    // Non-linear penalty on small-but-nonzero dead space (unusable slivers)
    let dead = x * (1.0 - x);
    score += 18.0 * dead * (1.0 - t);

    // Reward bins whose residual matches the next item's likely need
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        let gap2 = gap * gap;
        score -= 10.0 * (1.0 - gap2.min(1.0)) * (1.0 - t * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty relative to mean residual: avoid leaving this bin far below average clutter
    score += 0.5 * (pr as f64 - mean_residual) * (1.0 - x);

    // Encourage consolidation when many bins are open
    score += 0.3 * open_bins_count as f64 * x;

    // New-bin candidate: keep it attractive only when item is large relative to residuals
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score -= 20.0 * tightness * tightness * (1.0 - t);
        score += 30.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on residual space
    let pr = post_residual;
    let class = pr % 10; // harmonic sub-class
    let decade = pr / 10; // integer-division decade of residual

    // Reward residuals that are "friendly" multiples / near multiples of common sizes
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0; // nearly full, tiny waste
    } else if class == 0 {
        score -= 12.0; // residual divisible by 10 -> likely reusable
    } else if class == 5 {
        score -= 6.0;
    } else {
        score += (10 - class) as f64 * 0.8; // penalize awkward remainders
    }

    // Decade penalty: large residuals mean poor packing so far
    score += decade as f64 * 4.0;

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact harmonic match of next item with post residual
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - slack * 0.15;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 8.0; // divisible pairing
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    } else {
        // last item: strongly prefer filling existing bins
        score -= 40.0;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (fitting_bins_count == 0) as i32;
        score = cap * 0.55 + mean_residual * 0.2 - progress * 10.0 - congestion as f64 * 20.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (min item size = 1, but practically tiny gaps
    // below a "usefulness" threshold) are heavily penalized.
    let dead_threshold = 8u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0; // lookahead cannot use this bin's remainder
        }
    }

    // Tight-fit preference: fraction of bin filled by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac * fill_frac;

    // Last-chance bonus: only one bin can fit the item -> keep it usable.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.8 * open_bins_count as f64;

    // Slight preference toward bins with below-average residual (denser bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: prefer opening a new bin only when current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0 - 30.0 * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual matches the next item size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);
        // Perfect chain bonus: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Post-residual too small for the next item: penalize dead space creation,
        // scaled by how unusable the leftover is relative to the next item.
        let dead = next_item_size - post_residual;
        score += 0.8 * dead as f64;
    }

    // Tightness reward: small post_residual generally good (best-fit flavor).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative-to-mean coupling: prefer bins tighter than average when many bins open.
    if open_bins_count > 1 {
        let rel = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 25.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it moderately expensive; only attractive when
    // item leaves a large, well-shaped residual (near half capacity) for future items.
    if bin_residual == bin_capacity {
        score = 70.0 + (post_residual as f64 - bin_capacity as f64 / 2.0).abs() * 0.6;
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If an open bin fits perfectly with lookahead, never open a new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the placement: reward near-perfect fits strongly
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Reward exact fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can use the post-residual, this placement
    // leaves valuable space; reward keeping a "compatible" gap.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if next_item_size <= post_residual {
            // next item fits in the leftover: good chaining
            score -= (next_item_size as f64 / bin_capacity as f64) * 12.0;
        } else {
            // leftover too small for next item: potential dead space
            let waste = gap / bin_capacity as f64;
            score += waste * waste * 25.0 * (1.0 + t);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Penalize spreading residual mass unevenly vs. the global mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to typical leftover space, or late in stream
    // when fragmentation is high.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // base penalty for opening a new bin
        let mut new_bin_score = 55.0;
        // large items justify new bins, especially if open bins have small residuals
        new_bin_score -= item_frac * 40.0;
        new_bin_score -= (mean_frac * 30.0).min(30.0);
        // late in stream, avoid opening bins unless item is big
        new_bin_score += t * 15.0 * (1.0 - item_frac);
        // if many open bins already, discourage more bins slightly
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // if no other bin fits, new bin is the only option: make it acceptable
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        return new_bin_score;
    }

    // Mild preference for bins with larger residual among equals (keep
    // small-residual bins for small items): prefer placing into the bin
    // whose residual is closest to item size.
    let fit_gap = (bin_residual as f64 - item_size as f64);
    score += fit_gap * 0.1;

    // Small time-varying exploration term to break ties differently over time
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post_residual), with non-linear sharpening
    let mut score = x * (1.0 + 2.0 * (1.0 - x) * (1.0 - x));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, punish it quadratically
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 6.0 * progress_weight * x * x;

    // Reward bins whose residual matches the next item size (smooth kernel)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let diff = (x - nx).abs();
        score -= 3.0 * (-8.0 * diff * diff).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * (1.0 - x);
    } else if fitting_bins_count > 1 {
        // mild penalty when many bins compete, scaled by residual waste
        score += 0.5 * (fitting_bins_count as f64).ln() * x;
    }

    // Penalize bins far above mean residual (fragmentation risk), smooth in t
    let mean_x = mean_residual / cap;
    score += 2.0 * (x - mean_x).abs() * (0.5 + t);

    // Slightly discourage opening new bins when few remain / many bins open
    if bin_residual as f64 == cap {
        score += 1.5 + 3.0 * t - 0.2 * (open_bins_count as f64);
        // but allow new bin if item is large and post_residual would be tiny anyway
        if x < 0.05 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are more valuable to keep.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are "harmonically aligned" with capacity fractions.
        let harmonics = [10u32, 20, 25, 50, 100];
        let mut align = 0.0f64;
        for h in harmonics.iter() {
            if pr % h == 0 {
                align += 8.0;
            }
        }
        // Small residual classes: exact fits are great (post_residual 0 handled above),
        // tiny dead space (< 10) is nearly unusable for items >= 10.
        if pr < 10 {
            score += 15.0 * (1.0 - pr as f64 / 10.0); // penalize tiny dead space
        } else {
            score -= align;
        }
    }

    // Integer-division threshold: classify residual into capacity-eighth buckets.
    let eighth = (bin_capacity / 8).max(1);
    let bucket = pr / eighth;
    match bucket {
        0 => score += 5.0,       // nearly full bin: good closure
        1 | 2 => score -= 3.0,   // moderately filled: fine
        _ => score += 2.0,       // large residual: keep for bigger items later
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0; // next item closes bin almost perfectly
            } else {
                score -= slack as f64 * 0.1;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot class
            let over = next_item_size - post_residual;
            score += (over / 10) as f64 * 2.0;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin harmonically matches
    // the item (item likely to pair with future items in a fresh bin).
    if bin_residual == bin_capacity {
        let perfect = post_residual == 0;
        let fresh_bonus = if perfect {
            -30.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -15.0
        } else {
            // opening a new bin wastes capacity equal to bin_residual - item
            10.0 + (mean_residual - post_residual as f64).abs() * 0.2
        };
        score += fresh_bonus;
        // Later in the stream, discourage proliferation of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0 + open_bins_count as f64 * 0.5;
    }

    // Mild pressure toward tighter fits overall.
    score -= (bin_residual - item_size) as f64 * 0.05;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are already handled, but residuals that are small relative to typical
    // item sizes become "unusable dead space". Penalize small gaps hard.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Non-linear penalty: the smaller the leftover gap, the worse.
        score += (dead_threshold - post_residual as f64).powf(1.8) * 3.0;
    }

    // Perfect fits are golden: heavily reward post_residual == 0.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Reward tight fits (small relative waste).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 40.0;
    }

    // Exact match with lookahead: if the next item fits the post_residual
    // exactly, this placement is ideal — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    }
    // If the next item fits in the leftover space, mildly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for the next item: penalize as probable dead space.
        score += 60.0;
    }

    // Open-bins pressure: discourage spreading across many bins; prefer
    // filling existing bins when the stream is far along.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (5.0 + 10.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced),
    // but only mildly — tight fit dominates.
    score += ((bin_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 15.0;

    // New-bin candidate: only open a new bin if the item is large and no
    // open bin offers a decent fit. Make the empty bin moderately expensive
    // so it loses against any reasonable existing fit.
    if bin_residual == bin_capacity {
        score += 80.0 + 0.5 * (open_bins_count as f64);
        // But if the item is huge, opening a fresh bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: perfect chain (item + next item fills bin).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item fits after this one: mild reward proportional to slack left.
            score -= 40.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Dead space relative to lookahead: penalize unusable gap.
            let gap = (post_residual - next_item_size) as f64;
            score += 2.0 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize tiny residual fragments (< smallest plausible item) as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Prefer bins tighter than average (best-fit style) relative to mean residual.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: discourage unless open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let poor_fit = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 200.0 - 15.0 * crowd - 250.0 * poor_fit;
    }

    // Slight preference to consolidate into fewer bins early on.
    score += 5.0 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: post_residual too small to fit a typical item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is small (open bins nearly full)
        score += 20.0 + 60.0 * crowding - 15.0 * progress;
        // Discourage opening new bins when many are already open
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mildly prefer bins with residuals near the item (harmonic-style)
        let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * waste * waste;
        // Prefer bins with residual below mean (consolidate emptier space elsewhere)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor low post_residual anyway);
    // late in the stream, dead space becomes increasingly costly.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.5;

    // Smooth reward for tight fits (small post_residual), stronger as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= (tightness * tightness * tightness) * item_size as f64 * (0.4 + 1.2 * progress);

    // Penalize bins whose residual is far below the mean residual (poorly reusable).
    score += 0.3 * (mean_residual - pr).max(0.0) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 6.0 * (1.0 - (leftover as f64 / cap));
    }

    // New-bin candidate: make it mildly unattractive so open bins are preferred,
    // but increasingly acceptable late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        score = cap * (1.1 - 0.25 * progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes (10..80 multiples / small ints)
    // Perfect fits (post_residual == 0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small dead space classes: post_residual in [1..9] is nearly unusable (min item 10)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score -= 25.0; // usable by smallest items, decent class
    } else if post_residual <= 40 {
        score -= 15.0;
    } else if post_residual <= 60 {
        score -= 20.0;
    } else {
        score -= 10.0; // large residual, bin still flexible
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with item sizes
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does post_residual exactly fit next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize small residuals more
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: prefer opening a new bin when existing residuals are large/wasted
    if bin_residual == bin_capacity {
        // base for new bin: slightly worse than a good fit, better than bad fits
        score = 45.0;
        if fitting_bins_count > 0 && post_residual_penalty_is_low(mean_residual) {
            score += 30.0; // existing bins are roomy, keep using them
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: fresh bin attractive
        }
    }

    // Progress-aware mild scaling
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

#[inline]
fn post_residual_penalty_is_low(mean_residual: f64) -> bool {
    mean_residual > 45.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum plausible
    // future item size are nearly worthless -> heavy penalty.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect fit, unreachable in practice
    } else if post_residual < 10 {
        // gap too small for any item in the original regime; treat as dead space
        score += 12.0;
    } else {
        // smooth dead-space penalty growing as the gap shrinks
        let gap = post_residual as f64;
        score += 8.0 * (1.0 - gap / bin_capacity as f64).powi(6);
    }

    // Reward tight fits relative to item size (fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill * fill;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via this reward on real bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
        // but if no other bin fits well (few fitting bins), soften
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            // next item won't fit in the leftover; mild penalty for wasting space
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mean-residual coupling: when average leftover is high, be pickier
    // about which bin receives the item (favor below-average residual bins).
    score += 0.25 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + item_size as f64 * 0.5;
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 1.5;
    }
    // Next item cannot fit here: penalize proportionally to wasted potential
    else if next_item_size > 0 {
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 0.4;
    }

    // Penalize tiny dead space (unusable residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tightening the bin toward capacity
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that reduce dispersion
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Early in stream: be greedy with new bins later; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residuals everywhere are fragmented
        score += 20.0 - progress * 15.0 + mean_residual * 0.1;
    } else if progress > 0.7 {
        score -= 5.0;
    }

    // Few open bins: mild pressure to fill existing bins rather than spread
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Strongly reward perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown, use 10 as floor heuristic scaled).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // partial reward proportional to how well next item uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * usage;
        } else {
            // next item cannot fit here: mild penalty scaled by wasted leftover
            score += 5.0 + 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post residual.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // extra pull if the fit is decent
        if post_residual <= bin_capacity / 3 {
            score -= 15.0;
        }
    }

    // Penalize opening a new bin when good fitting bins exist and stream is late.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty if open bins exist
        score += 18.0;
        if open_bins_count > 0 {
            score += 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
        // early in stream, opening bins is cheaper (stockpiling capacity)
        score -= 20.0 * (1.0 - t);
        // if mean residual is large, open bins are roomy; still prefer them
        score += 0.15 * mean_residual;
    }

    // Prefer bins with low residual among equals (fill fuller bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to keep number of open bins from exploding late in stream.
    if bin_residual != bin_capacity {
        score -= 2.0 * t * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Tight fits rewarded more strongly as stream progresses
    let tightness = (1.0 - x) * (1.0 - x) * (1.0 + 2.0 * progress);
    score -= 60.0 * tightness;

    // Penalize small-but-unusable residuals, smoothly via cubic term
    let dead = x * (1.0 - x) * (1.0 - 2.0 * x);
    score += 40.0 * dead;

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 25.0 * fit_quality * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 15.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // New-bin candidate: mildly penalize early, allow later via progress coupling
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 15.0 * progress * (1.0 - x);
        // open new bin if remaining residual is large dead space
        if x < 0.2 { score -= 20.0; }
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 relative to capacity fractions.
    let cap10 = bin_capacity / 10; // 10
    let residue_class = (post_residual % cap10) as f64;
    let decade = (post_residual / cap10) as f64;

    // Penalize post-residuals that are small but nonzero (dead space: nothing fits later).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward post-residuals in "usable" classes (>= 10 multiples or large enough for typical items).
    if post_residual >= 10 {
        score -= 5.0 + 0.5 * decade;
    }

    // Harmonic coupling: post_residual divisible by 10 is clean; divisible by 5 semi-clean.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += residue_class * 0.3; // awkward remainders are less reusable
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 120.0;
        } else if slack < 10 {
            score -= 20.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; leftover is likely dead.
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or this is a fresh stream start with many items remaining.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score = 150.0 + waste * 0.5 - progress * 30.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // pairing potential in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Mean residual coupling: if this bin is much fuller than average, prefer it.
    let fullness = (bin_capacity - bin_residual) as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - (bin_capacity as f64 - fullness)) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are heavily penalized.
    // Treat "unusable" as gaps smaller than the next item's size when a lookahead exists,
    // or very small absolute gaps when it doesn't.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 8 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: fraction of the bin's space consumed by this placement.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: reward leaving a residual that exactly fits the next item,
    // penalize residuals that would strand the next item into a new bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Mean-residual coupling: if this bin is much emptier than average, it's a good dump target.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a fresh bin only attractive when the item is large
    // or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 8.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, graded penalty for near misses
        if diff == 0.0 {
            score -= 200.0;
        } else if diff <= 5.0 {
            score -= 60.0 - diff * 8.0;
        } else {
            score += diff * 0.5;
        }

        // Penalize residuals that can't fit the next item at all (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        // Reward residual large enough to hold both current leftover and next item flexibly
        if post_residual >= next_item_size && post_residual >= 20 {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual (tighter packs)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins have decent space
        score += 30.0 + pressure * 50.0;
        // But allow new bin if current item is large and mean residual is small
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 55.0;
        }
    }

    // Slight stream-progression tightening: later in stream, favor tighter fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 1.0 };
    score -= 30.0 * (-tightness).exp();

    // Penalize dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: mild reward proportional to leftover usability
            score -= 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // dead space for the lookahead: heavy penalty
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many competing fitting bins: prefer the fullest (smallest residual already via post_residual)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Time horizon: early in the stream, be conservative about wasting space;
    // late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer bins with residual
    // near the mean (balanced packing); if low, prefer the tightest bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_fit = if post_residual > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        // A fresh bin costs one bin; open it only if it prevents worse waste
        score += 15.0 - 20.0 * scarcity - 12.0 * bad_fit * progress;
        // Late in stream, opening new bins is cheaper than fragmenting
        score -= 5.0 * progress;
    }

    // Slight preference to fill bins with larger items completely
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - post / cap;

    // Non-linear polynomial coupling: reward tight fits with super-linear decay
    let tight = (1.0 - post / cap).powi(3);
    score -= 40.0 * tight;

    // Penalize post_residual scaled by stream progress (later waste is costlier)
    score += (post * post) / cap * (0.5 + progress);

    // Interaction: fill ratio vs progress — early on, prefer balanced fills
    score -= 15.0 * fill * (1.0 - progress) * fill;

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 20.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 5.0 * ((nxt - post) / cap).powi(2);
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - fit_ratio) * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins with residual near mean (balance load), non-linear
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev * dev;
    }

    // Mild penalty for opening many bins late
    score += (open_bins_count as f64).ln() * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    score -= 3.0 * ((cap - post_residual as f64) / cap).powi(2) * 20.0;

    // Dead-space penalty: residual too small to ever be useful (assume min item 1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harmonic class: residuals divisible by common item sizes are more reusable.
    let r = post_residual;
    if r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0 {
        score -= 8.0;
    }
    // Integer-division thresholds: classify residual into thirds of capacity.
    let third = (r * 3) / bin_capacity;
    score -= third as f64 * 4.0;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 0.15 * (next_item_size as f64 - r as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (large post_residual elsewhere, many bins).
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            // There exists a fitting open bin; only prefer new bin if mean fit is bad.
            if mean_residual > 0.35 * cap {
                score -= 35.0;
            }
        }
        // Early stream: allow new bins more liberally to build a good pool.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size = 1, but practically small gaps)
    // are heavily penalized. Treat gaps < 12 as near-dead space.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins whose residual is already
    // tighter than average (i.e., filling the emptiest bins first keeps
    // many medium gaps alive elsewhere).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.6;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins and encourage consolidation into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; but attractive if
        // no existing bin fits well (this call is the fallback anyway).
        score = 100.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 120.0; // no alternative: opening is fine
        } else if fitting_bins_count == 1 {
            // last-chance bin exists: strongly prefer using it
            score += 10.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward being the unique fitting option.
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else if fitting_bins_count == 2 {
            score -= 8.0;
        }
        // Lookahead: if the post residual can exactly host the next item,
        // this is an excellent chaining placement.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Mild bonus for filling large items into tight bins.
        if item_size >= 50 {
            score -= (item_size - 50) as f64 * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * next_item_size as f64;
        // extra reward for tight two-item packing (post_residual barely above next item)
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        let unusable = if post_residual < next_item_size { post_residual as f64 } else { 0.0 };
        score += 0.6 * unusable;
    }

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer tight fits relative to mean residual
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: using it avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 - progress);
    }

    // New-bin candidate: open a fresh bin only when no good fit exists among open bins
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.5 * next_item_size as f64;
        if poor_fit || (next_item_size > 0 && next_item_size > post_residual) {
            score -= 55.0; // open new bin rather than fragment an existing one
        } else {
            score += 70.0; // prefer existing bins when fit is decent
        }
        // late in the stream, discourage opening bins that will be nearly empty
        score += 30.0 * progress;
    }

    // Mild penalty for spreading across too many bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Exact chain fit: item then next item perfectly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bins are crowded
    // or the fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        let poor_fit = fill_ratio < 0.5;
        if poor_fit || (next_item_size > 0 && next_item_size as f64 > mean_residual) {
            score += 30.0; // keep using open bins
        } else {
            score += 5.0 + pressure.min(20.0);
        }
    }

    // Global state coupling: when mean residual is high, prefer spreading load
    // into emptier bins; when low, prefer tightest fills (post_residual dominates).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_ratio = mean_residual / bin_capacity as f64;
    score -= 6.0 * mean_ratio * (1.0 - progress);

    // Late in the stream, avoid leaving many near-empty bins; favor consolidation.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 4.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty proportional to fragmentation risk (post_residual mod small sizes).
    let frag = (post_residual % 10) as f64;
    score += 0.4 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: reward small post_residual non-linearly
    let pr_norm = pr / cap;
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 12.0 * (0.5 + 0.5 * progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - pr_norm);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins late in the stream mildly
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands
    let frac = post_residual as f64 / bin_capacity as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes of post_residual: 1..10 (dead), 11..25 (poor), 26..50 (medium), >50 (usable)
    let harmonic_class = match post_residual {
        0..=10 => 0,
        11..=25 => 1,
        26..=50 => 2,
        _ => 3,
    };
    score -= harmonic_class as f64 * 12.0;

    // Modulo arithmetic: post_residual divisible by common item sizes is more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover: penalize proportional waste
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: make it less attractive than decent fits,
    // but attractive when residual space in open bins is tight
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 45.0 + 40.0 * pressure;
        if next_item_size > item_size && next_item_size > 0 {
            score -= 15.0;
        }
        return score;
    }

    // Tight fill fraction of current bin: reward bins that get fuller
    let fill = 1.0 - frac;
    score -= fill * 10.0;

    // Small dead-space penalty scaled by stream progress (later, more careful)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.05 * progress;

    // Mild penalty for scattering across many open bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below mean residual (less full) when residuals are plentiful
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // (min item size is 1, but small gaps rarely match future items).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 4.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins whose residual is close to
    // the item (tight fit relative to fleet state).
    score += 0.35 * (bin_residual as f64 - item_size as f64 - mean_residual).abs();

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount when no
        // existing bin gives a decent fit (post_residual large everywhere).
        score += 25.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward using an existing bin, more so under pressure.
        score -= 3.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // (avoid opening a new bin needlessly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here later: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the residual: penalize large leftover
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Penalize residuals too small to ever be useful (below min item size 1 => dead space)
    // Prefer bins whose residual is close to mean (keep balance), slight effect
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // discourage opening new bins when existing ones can fit
            score += 150.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small relative to item size.
    let tightness = (post_residual as f64) / (item_size as f64).max(1.0);
    score += 0.35 * tightness * (item_size as f64);

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size as u32 {
            (next_item_size as f64 - post_residual as f64)
        } else {
            0.0
        };
        score += 0.25 * dead;
    }

    // Lookahead coupling: if the next item fits exactly in post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size as u32 {
            score -= 20.0;
        } else if post_residual >= next_item_size as u32 {
            score -= 0.15 * next_item_size as f64;
        }
        // Penalize if post-residual blocks the next item while a tighter bin exists.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strong reward to use the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Progress-scaled term: as the stream advances, favor consolidating into fewer bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 4.0 * progress * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    // Global state coupling: when mean residual is high, prefer bins below mean (balance residuals).
    let dev = mean_residual - post_residual as f64;
    score += 0.10 * dev;

    // When many bins are open, discourage opening new ones; new-bin candidate gets a penalty.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
        // But if the item is large and mean residual is low, a new bin may be better.
        if item_size > 60 && mean_residual < 20.0 {
            score -= 6.0;
        }
    }

    // Mild bonus for leaving post-residual in a "useful" range (>= 10 or == 0).
    if post_residual == 0 {
        score -= 5.0;
    } else if post_residual < 10 {
        score += 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual, non-linearly shaped by stream progress.
    // Early on, prefer filling bins partially (higher progress weight on tightness);
    // late in the stream, dead space becomes more costly, so tighten more.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: squared normalized post-residual penalizes large dead space
    // super-linearly, but only as the stream matures.
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 30.0 * (-pr / 12.0).exp();

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly;
    // if the next item would fit in this bin but not after placing here, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt) / cap).abs() * (1.0 + progress);
        } else if nxt <= bin_residual as f64 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when existing
    // bins have ample mean residual and the item fits reasonably.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item).max(0.0) / cap;
        score += 20.0 + 30.0 * (1.0 - mean_gap) * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this placement leaves
    // awkward residual relative to mean residual.
    score += 3.0 * ((pr - mean_residual).abs() / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions, integer division) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (post_residual in smallest harmonic band)
    if post_residual <= bin_capacity / 20 {
        score -= 30.0;
    }
    // Class B: post_residual divisible structure — dead space quantization
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 8.0 * (1.0 - pr / (quarter as f64));
    } else if post_residual < bin_capacity / 2 {
        score += 4.0 * (pr - quarter as f64) / (quarter as f64);
    } else {
        // large leftover: strong penalty, this bin is wasteful for this item
        score += 10.0 + 0.1 * (pr - (bin_capacity / 2) as f64);
    }

    // Modulo arithmetic on post_residual: favor residuals that align with
    // common small item sizes (harmonic divisors of capacity).
    let harmonics: [u32; 5] = [10, 20, 25, 50, bin_capacity / 3];
    for h in harmonics.iter() {
        if *h > 0 && post_residual % h == 0 && post_residual > 0 {
            score -= 5.0;
            break;
        }
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - waste / cap);
        } else {
            // next item cannot follow: post-residual becomes dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.15 * gap;
        }
    }

    // --- Last-chance bin: strongly prefer using it before opening new bins ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, reward tighter fits more aggressively
        score += 0.05 * (fitting_bins_count as f64);
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if no existing bin fits well.
        let fit_quality = 1.0 - (item_size as f64) / cap;
        // Penalize new bin proportionally to how well the item would fit
        // existing bins (approximated by mean residual vs item size).
        let existing_usable = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        score = 0.5 * cap + 20.0 * fit_quality + 40.0 * existing_usable
              - 10.0 * (1.0 - (open_bins_count as f64) / ((open_bins_count + 4) as f64));
        // Late in the stream, slightly discourage opening bins (consolidation)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // --- Mean residual interplay: prefer bins below mean residual (tighter) ---
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff; // tighter-than-average bins get lower score
    }

    // Small tie-break noise-free deterministic jitter on bin index proxy
    score += 0.001 * ((post_residual as usize).wrapping_mul(2654435761) % 97) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / cap;
    score -= 10.0 * fill_ratio;

    // Penalize leaving a gap that neither the next item nor small items can use.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0; // gap is reusable by lookahead item
        } else if post_residual > 0 {
            score += 12.0; // gap wasted relative to lookahead
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate: make empty bin moderately attractive only when item is large
    // and would leave a big useful gap, otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win.
        score += 18.0;
        // Large items fit better in fresh bins.
        score -= 0.25 * item_size as f64;
        // If no other bin fits well (this is the only candidate context), ease penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual as f64 - next_item_size as f64) * 0.5;
        } else {
            score += 15.0; // dead space for the next item
        }
        // perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer tighter bins relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 20.0
            + open_bins_count as f64 * 2.0
            + (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
        // allow new bin if next item is large and this item is small (pairing strategy)
        if next_item_size > item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is ideal, but leave room
    // for a possible follow-up item via lookahead.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead synergy: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally to waste.
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - t);
    }

    // Penalize bins with residuals far above mean (fragmentation risk),
    // reward bins already below mean residual (consolidating fill).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Mild pressure to prefer filling existing bins over opening new ones,
    // stronger early in the stream when bin count is still low.
    if bin_residual < bin_capacity {
        score -= 3.0 + 2.0 * (1.0 - t);
    } else {
        // New empty bin candidate: penalize slightly so it only wins when
        // fits into open bins are poor (large post_residual there).
        score += 6.0 + 4.0 * t;
    }

    // Squared waste term: heavily punish leaving medium dead space
    // (neither empty nor usable), which is the classic failure mode.
    let pr = post_residual as f64;
    if pr > 0 {
        score += 0.02 * pr * pr;
    }

    // Slight preference for bins with small current residual (denser bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear quadratic coupling of post_residual with stream progress:
    // dead space becomes increasingly costly as the stream matures.
    let dead = pr / cap;
    score += 60.0 * dead * dead * (0.3 + progress);

    // Smooth reward for tight fits (small post_residual), stronger late in stream.
    score -= 25.0 * (1.0 - dead) * (1.0 - dead) * (0.5 + progress);

    // Lookahead: reward residual that can host the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = (pr - nx) / cap;
            score -= 15.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
        } else {
            score += 10.0 * ((nx - pr) / cap);
        }
    }

    // Penalize new-bin candidate (empty bin) smoothly, more when other bins fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (fitting_bins_count as f64).sqrt() + 10.0 * progress;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - dead);
    }

    // Mild penalty for deviating from mean residual (encourage balanced fills).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: items dividing capacity into nice chunks
    let pr = post_residual;
    if pr > 0 {
        // residue classes modulo 10: residuals divisible by 10 are more reusable
        let m10 = pr % 10;
        score += match m10 { 0 => -6.0, 5 => -2.0, _ => (m10 as f64) * 0.4 };
        // perfect-fit class: post_residual == 0 handled by base; near classes
        if pr <= 5 { score -= 8.0; }
        else if pr <= 10 { score -= 4.0; }
        else if pr > 50 { score += 5.0; } // large dead space penalty
    } else {
        score -= 15.0; // perfect fit
    }

    // capacity fraction coupling: how full the bin becomes
    let fill = 1.0 - post / cap_f;
    score -= fill * fill * 6.0;

    // lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr { score -= 12.0; }
        else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 6.0 - (slack as f64) * 0.15;
        } else {
            // next item cannot use this residual: slight penalty proportional to gap
            score += ((next_item_size - pr) as f64).min(30.0) * 0.1;
        }
    }

    // last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // new-bin candidate handling: only open a new bin if all open bins fit poorly
    if bin_residual == bin_capacity {
        let tight = fitting_bins_count == 0 || (fitting_bins_count <= 1 && item_size < 40);
        if tight { score -= 4.0; } else { score += 12.0 + (open_bins_count as f64) * 0.3; }
    }

    // late-stream consolidation: prefer filling existing bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;
    score += (open_bins_count as f64) * 0.05;

    // mean residual context: if open bins are already roomy, discourage waste
    score += ((mean_residual - post) * 0.05).clamp(-3.0, 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 15.0 + open_bins_count as f64 * 2.0;
        // but if no open bin fits well, allow it via lookahead relief
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        // existing bins get mild reward scaled by how full they are
        let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= fullness * 8.0;
        score += open_bins_count as f64 * 0.3;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Slight progression adaptation: tighten tolerance late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement: mild reward scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize wasted residual that likely becomes dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Reward near-full bins (small post residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize bins whose residual deviates far below the mean (odd-sized leftovers),
    // unless this placement tightens them toward the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits reasonably well (few fitting bins) or residuals are already tiny/fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 200.0; // an open last-chance bin exists; use it instead
        } else {
            // Compare best achievable residual elsewhere: prefer new bin only if
            // existing bins would leave very fragmented space.
            let fragmentation = mean_residual / bin_capacity as f64;
            score += 150.0 * fragmentation;
        }
    }

    // Late in the stream, be more conservative: keep bins tight, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fits are poor. Give the empty-bin candidate a mild penalty
    // that shrinks when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 0.05 * open_bins_count as f64 - 0.02 * fragmentation;
    }

    // Prefer filling bins with larger residuals early; near the end of the
    // stream, be more greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);

    // Mild penalty for spreading across many open bins when mean residual is low
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear penalty for small-but-nonzero waste
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize residual that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Reward residual that exactly accommodates next item (smooth bump)
        let fit_next = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 6.0 * fit_next * fit_next * fit_next;
    }

    // Last-chance bonus: smooth, stronger late in the stream
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (0.5 + 0.5 * progress);

    // Mild pressure to prefer bins below mean residual (balance load) via cubic term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * dev;

    // Slight preference for fewer open bins early, more consolidation late
    score += (open_bins_count as f64).ln() * (1.5 * (1.0 - progress));

    // New-bin candidate: penalize mildly unless residual pattern is poor
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes (0..=10, i.e. unusable for most items) are good.
    let dead_class = post_residual / 11; // 0 => tight fit (best), higher => wasteful
    score += dead_class as f64 * 7.0;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post residual exactly divisible by common size quantum -> likely reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits: reward proportional to how snugly
        score -= 18.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; penalize leaving awkward gaps
        score += (post_residual % 17) as f64 * 0.8;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current residuals are all small (item likely won't fit well anywhere).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // penalize new bin when open bins have plenty of room on average
        score += 25.0 + mean_r * 0.5;
        // but if item is large and mean residual is tight, new bin is fine
        if item_size > 60 && mean_r < item_size as f64 {
            score -= 30.0;
        }
    }

    // Prefer filling more-loaded bins early in the stream (best-fit flavor):
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Stream progression: later in the stream, be more conservative about
    // leaving medium gaps (fewer future chances to reuse them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 10 && post_residual < 30 {
        score += progress * 10.0;
    }

    // Tie-break toward fewer open bins when scores are close.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 8.0; // gap in [1,9] is nearly unusable
    } else if dead >= 10.0 && dead < 20.0 {
        score += (20.0 - dead) * 2.0; // mildly awkward gap
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mild penalty scaled by number of open bins to avoid
    // bin proliferation when a reasonable existing fit exists.
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: penalize slightly unless open bins are crowded,
    // so a fresh bin is only opened when existing bins are poor fits.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 1.5;
        score += 10.0 - crowded.min(10.0);
        // New bin looks better if mean residual is small (bins mostly full).
        score += mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space after placement.
    score += 0.8 * post_residual as f64;

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills post_residual, this is a golden match.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: mild reward proportional to snugness.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space relative to gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving less than average is good; leaving much more is wasteful.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the item is large and would leave a big unusable gap elsewhere.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else {
            let min_gap = (post_residual as f64).max(0.0);
            20.0 + 0.6 * min_gap
        };
        score += urgency;
    } else {
        // Reward tight fits in existing bins (small post_residual).
        score -= 0.4 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;
    }

    // Late in the stream, consolidation matters more: favor tight existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, prefer fullest bins.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space < 10).
    if post_residual < 10 {
        score -= 8.0; // perfect closure is great
    } else if post_residual < 20 {
        score += 4.0; // awkward sliver
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 2.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrink if many bins already open and mean residual is high.
        score = (bin_capacity as f64) - 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open
        } else if mean_residual > item_size as f64 * 1.6 {
            score += 10.0; // existing bins have plenty of room, prefer them
        } else if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the last fitting bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Mild pressure to prefer bins below mean residual (rebalance toward emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for fewer open bins overall.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let fit = fitting_bins_count as f64;

    let mut score = post;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 40.0 * poly;

    // reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // penalize opening new bins when alternatives exist
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
    }

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fit > 1.0 {
        score += 2.0 * (fit - 1.0);
    }

    // lookahead: prefer bins whose post residual accommodates next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // mild pull toward mean residual
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into bands. Small leftovers are good (tight fit),
    // mid leftovers are dead-space risk, large leftovers are fine.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Band 1: post_residual < 10 -> near-perfect fit, strong reward.
    if post_residual < 10 {
        score -= 25.0;
    }
    // Band 2: post_residual in [10, 20) -> decent, small reward scaled.
    else if post_residual < 20 {
        score -= (20.0 - pr) * 1.2;
    }
    // Band 3: post_residual in [20, 40) -> dead-space danger zone,
    // penalize quadratically since few future items (>=10) fit usefully
    // and pairs are unlikely.
    else if post_residual < 40 {
        score += (pr - 20.0) * (pr - 20.0) * 0.15;
    }
    // Band 4: post_residual >= 40 -> roomy, mildly reward.

    // Harmonic class of the item itself via capacity fractions:
    // items > 50 (more than half capacity) pair poorly; putting them
    // into an existing bin is valuable, reward it.
    if item_size > bin_capacity / 2 {
        score -= 8.0;
    }

    // Modulo coupling: if (post_residual % 10) is small, the leftover
    // aligns with the coarse item-size grid, making it reusable.
    let rem = post_residual % 10;
    if rem <= 2 {
        score -= 3.0;
    } else if rem >= 8 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this is a harmonic pair — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays with slack; a follow-up fit leaving <10 is great.
            score -= 15.0 - slack * 0.5;
        } else {
            // Next item cannot use this bin's leftover; penalize tight fits
            // that strand space, scaled by how much the next item overflows.
            let over = (next_item_size - post_residual) as f64;
            if over < 10.0 {
                score += over * 0.8;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Only prefer it when the item is huge and no open bin offers a
    // reasonable fit; otherwise penalize opening new bins, more so when
    // many bins are already open.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 12.0 + open_pressure * 1.5;
        // Huge items (> 70) tolerate a fresh bin.
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Late in the stream, avoid opening bins (nothing left to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 4.0;
    }

    // Mild tie-break: prefer bins whose residual is above the mean
    // (keeps a spread of usable bins rather than one giant bin).
    if (bin_residual as f64) < mean_residual {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to ever be useful
    // (below the smallest possible item) are pure waste.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Tight fits are good: reward small-but-usable residuals.
        score -= 20.0;
    }

    // Reward filling a bin nearly full (post_residual close to 0 but >= 10).
    if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it only wins when fits are terrible.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 50.0;
    }

    // Slight preference to pack into bins with high residual (keep
    // tight bins for tight items) when mean residual is low.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Lookahead synergy: if the next item fits the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and this bin would leave a large gap, penalize.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 0.1 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Late-stream pressure: as the stream progresses, consolidate.
    score += (step_index as f64 / total_items.max(1) as f64) * (open_bins_count as f64 - 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead fit: reward closeness to the next item size.
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + gap / 10.0);
    }

    // Penalize small, likely-unusable residuals (dead space below the minimum item size).
    if post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins could fit, scaled by stream progress.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * progress;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below the mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Mild bonus for using an already-open bin (avoid bin proliferation).
    if bin_residual < bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already good; amplify.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit here but would fit better elsewhere, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin wastes existing residual.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 35.0;
        // Early in the stream, consolidating matters less; later, avoid sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with high mean residual -> prefer using an open bin.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 20.0;
        }
        // If no open bin fits well (large item), opening new bin is fine.
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // Mild preference for bins already below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Slight penalty for very fragmented bin state.
    if open_bins_count > 10 {
        score += 0.5 * (open_bins_count as f64 - 10.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_r = mean_residual / cap;
    let lookahead = next_item_size as f64 / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    // Later in the stream, tight packing (small post_residual) matters more.
    let mut score = pr * (1.0 + 1.6 * progress * (1.0 - norm_pr));

    // Smooth polynomial penalty for large dead space, amplified with progress.
    score += (norm_pr * norm_pr) * cap * (0.4 + 0.9 * progress * progress);

    // Reward filling a bin nearly exactly (post_residual near 0) smoothly.
    score -= (1.0 - norm_pr).powi(3) * 8.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (pr - lookahead) / cap;
        score -= 3.0 * fit_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Post-residual too small for the next item: penalize smoothly.
        score += 2.5 * (1.0 - pr / lookahead.max(1.0)) * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate handling: penalize opening a fresh bin, but relax the
    // penalty when the item is large relative to capacity and mean residuals are low.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 6.0 * openness * (1.0 - norm_item) - 5.0 * (1.0 - mean_r) * norm_item;
    }

    // Mild diversity term: prefer bins whose residual differs from the mean
    // when this bin is tighter than average (smooth cubic interaction).
    let tightness = 1.0 - norm_pr;
    score -= (tightness - mean_r).abs() * 1.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Small residuals (dead space) are penalized; medium residuals are useful.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if post <= 5 {
        score -= 25.0;
    } else if post <= 15 {
        score -= 10.0;
    } else if post <= 30 {
        score -= 3.0;
    } else if post <= 50 {
        score += 2.0;
    }

    // Modular harmonic classes on post_residual (capacity fractions).
    let frac = (post as f64) / (bin_capacity as f64);
    if (post % 10) == 0 {
        score -= 5.0; // decile-aligned residual stays useful for typical items
    }
    if (post % 25) == 0 && post > 0 {
        score -= 4.0;
    }
    if frac < 0.10 && post > 0 {
        score += 12.0; // thin sliver: dead space
    }
    if frac > 0.60 {
        score -= 6.0; // bin still mostly empty, keep filling it
    }

    // Integer-division thresholds: does the NEXT item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0; // next item exactly fills this bin
        } else if next_item_size < post {
            let chain = post / next_item_size.max(1); // how many copies of next item fit
            score -= (chain as f64) * 4.0;
        } else {
            // next item cannot go here; residual must hold something else later.
            // Penalize more if residual is awkwardly small.
            if post < 20 {
                score += 8.0;
            }
        }
    } else {
        // Last item of the stream: prefer tightest fit, exact fills strongly.
        score += (post as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the item
    // is large and open bins would be left with tiny residuals.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open a new bin
        }
        // If remaining space in existing bins is small, opening fresh is fine.
        if mean_residual < (item_size as f64) * 1.05 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for filling bins that are already relatively full.
    let fullness = 1.0 - frac;
    score -= fullness * 5.0;

    // Tie-break toward bins whose residual is close in size to the item.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small and hard to reuse
    // (below the smallest plausible item) are heavily penalized.
    let min_item = 1.0f64;
    let dead_zone = 20.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Exact fit is gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize open-bin sprawl: prefer consolidating when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 1.2 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item won't fit here -> mild penalty
    }

    // Mean residual coupling: bins deviating far below mean residual are
    // tighter fits; encourage filling tight bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize so we only open when truly necessary,
    // but relax late in the stream when consolidation pressure is high.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        score -= 6.0 * (1.0 / (1.0 + diff / 10.0)); // smooth match reward
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Post residual can't fit next item but is small (usable dead space)
        if post_residual < next_item_size && post_residual < 10 {
            score -= 4.0;
        }
        // Wasteful: leaves large unusable gap for next item
        if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0;
        }
        // Two-item fill: item + next item exactly fills bin
        if item_size + next_item_size == bin_residual {
            score -= 12.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Penalize creating very small dead space that nothing (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    let mr = mean_residual;
    if (bin_residual as f64) < mr - 1.0 {
        score -= 3.0;
    } else if (bin_residual as f64) > mr + 1.0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // New-bin candidate: keep neutral-ish baseline; slightly discourage unless current bin is poor
    if bin_residual == bin_capacity {
        score += 5.0;
        // If no existing bin fits well, allow new bin
        if post_residual as f64 > item_size as f64 * 0.5 && fitting_bins_count > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that can't hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            score += 10.0; // breaks the chain for the next item
        }
        // Chain bonus: next item leaves a good residual too
        if post_residual >= next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual < 10 {
                score += 15.0; // chain leaves sliver, mild penalty
            } else {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // current bin fits are poor (large post_residual) or no tight option exists.
    if bin_residual == bin_capacity {
        // New bin baseline: perfect fit for large items, penalized otherwise.
        score = (bin_capacity - item_size) as f64;
        if item_size >= 80 {
            score -= 35.0; // large item wastes nothing in a fresh bin
        }
        if fitting_bins_count > 0 {
            score += 45.0; // discourage opening when alternatives exist
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global pressure: many open bins with large mean residual -> encourage filling existing bins.
    if mean_residual > 40.0 && open_bins_count > 2 {
        score -= 6.0;
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + 0.5 * progress * pr_norm;

    // Reward tight fits (small post_residual) more strongly late in stream
    score += poly * cap * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 2.0 * (nxt - pr).min(cap) * (0.5 + progress);
        } else {
            // reward leaving space usable by next item
            score -= 1.5 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.8 * (mean_residual - pr) * (0.3 + 0.7 * progress);

    // Slight penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic dead-space classes: post_residual that cannot host the next item
    // is wasted capacity. Penalize by class (integer division thresholds).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead_class = (post_residual / 10) as f64; // coarse class 0..=9
        score += 8.0 + dead_class * 1.5 + (post_residual as f64) * 0.25;
    }

    // If next item fits with little slack left after, reward tight chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < 5 {
            score -= 5.0;
        } else if slack_after_next < 15 {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly,
    // but soften the penalty when the fresh bin leaves room for the lookahead item.
    if bin_residual == bin_capacity {
        score += 7.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.5;
        }
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Modulo-based micro-class on post_residual: prefer residuals that are
    // "clean" multiples of small granularities (easier future packing).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Harmonic threshold: residuals <= 10 are near-dead regardless of lookahead
    if post_residual > 0 && post_residual <= 10 {
        score += 4.0;
    }

    // Coupling with mean residual: prefer bins whose post-residual tracks the fleet average
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late-stream tightening: as the stream progresses, be pickier about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits proportionally.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // If the leftover could still fit the next item, this bin stays useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that can't take the known next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // packing tightly into existing bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is already below the mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to any
    // open bin's residual or open-bin pressure is low. Make it moderately costly
    // so it's chosen only for poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fill wins, but avoid useless near-full leftovers
    if post_residual > 0 {
        score -= 6.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly/into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Exact match is ideal: next item consumes all remaining space
        if slack == 0.0 {
            score -= 40.0;
        } else if slack <= 10.0 {
            score -= 25.0 - slack * 1.5;
        } else {
            score -= 12.0 / slack.sqrt();
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to mismatch
        let gap = (next_item_size - post_residual) as f64;
        score += 4.0 + gap * 0.15;
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean
    // are "almost full" -> favor packing them out; far above mean -> discourage
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.12 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive late in stream or when item
    // is large and no open bin gives a good fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        let poor_fit = next_item_size > 0 && post_residual < next_item_size;
        score += 55.0 - 20.0 * progress
            - if large_item { 25.0 } else { 0.0 }
            - if poor_fit { 10.0 } else { 0.0 };
        // Discourage hoarding many open bins early
        score += 1.5 * open_bins_count as f64;
    }

    // Small bonus for very tight fills regardless of lookahead
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: low post-residual is good, but dead space
    // below a "useless threshold" is extra-bad if it can't host the next item.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space relative to next item is penalized more late in the stream.
        score += 0.25 * (post_residual as f64).min(next_item_size as f64) * (0.5 + t);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins whose residual is already small (consolidate waste).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when current item is large relative to residual waste elsewhere, or when
    // mean residual across open bins is very low (all bins nearly full).
    if bin_residual == bin_capacity {
        let mean_res = mean_residual;
        // Cost of a fresh bin decreases late in stream if bins are congested.
        let congestion = (open_bins_count as f64).ln().max(1.0);
        let new_bin_penalty = 45.0 - 15.0 * t - (mean_res / bin_capacity as f64) * 30.0;
        score += new_bin_penalty.max(5.0) / congestion.sqrt();
        // A new bin is good if the item is huge and would leave awkward fits elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit sharpening).
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * (slack - slack.sqrt() * 2.0).max(0.0);

    // Slight early-stream exploration bonus: spread items when few bins exist.
    if t < 0.2 && open_bins_count < 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), non-linearly scaled.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: late in stream, tighten further (penalize waste more).
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 12.0 * norm_pr;

    // Interaction of post residual with mean residual across open bins:
    // if this bin's post residual is far below mean, it's a good tight fit.
    let mean_norm = mean_residual / cap;
    let dev = norm_pr - mean_norm;
    score += 6.0 * dev * dev - 8.0 * dev;

    // Next-item lookahead: reward leaving residual that can fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx).abs();
        let usable = if pr >= nx { 1.0 } else { fit_next / (nx + 1.0) };
        score -= 10.0 * usable * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + late);
    } else if fitting_bins_count > 1 {
        // mild competition pressure: tighten selection among many fits
        score += 2.0 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist,
    // but attractive late in the stream if open bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * norm_pr) + 15.0 * (1.0 - late) - 10.0 * late * (1.0 - mean_norm);
        if fitting_bins_count == 1 {
            score += 20.0; // don't open new bin when a unique fit exists
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are best, small dead space worst.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Class the dead space by integer division thresholds (harmonic buckets).
        let bucket = match pr {
            0..=5 => 0,
            6..=15 => 1,
            16..=30 => 2,
            31..=50 => 3,
            _ => 4,
        };
        // Dead space in [1..5] is nearly unusable -> strong penalty; large leftovers reusable -> mild.
        score += match bucket {
            0 => 45.0,
            1 => 18.0,
            2 => 5.0,
            3 => -3.0,
            _ => -10.0,
        };
        // Modulo arithmetic: residuals that are multiples of common item sizes (10,20,25,50)
        // are likely to be exactly filled by future items -> reward.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 25 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let frac = next_item_size as f64 / pr as f64;
            // reward high fill fraction of the leftover by the next item
            score -= 15.0 * frac * frac;
        } else {
            // next item won't fit here; penalize small dead leftovers more
            if pr < next_item_size && pr > 0 && pr <= 10 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bins when existing bins have plenty of room
        score += 30.0 + 40.0 * pressure;
        // early in the stream, opening bins is cheap-ish; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming, a fresh bin is useful
        }
    }

    // Slight preference for bins whose residual is far from mean (extreme fits)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Tie-break: favor fewer open bins (consolidation) via mild term
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // future item (1..100 interface) are "dead". Penalize unusable gaps
    // super-linearly; a gap that cannot hold even a small item is waste.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if post_residual as f64 > 0.0 && post_residual as f64 <= dead_threshold {
        score += 60.0 + 8.0 * (dead_threshold - post_residual as f64);
    }

    // Prefer bins whose residual is tight relative to the item placed:
    // high fill ratio = good packing.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual,
    // this bin becomes a perfect two-item chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 30.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mild penalty if this placement
            // leaves a tiny stranded gap.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // Last item: closing a bin fully is ideal.
        score -= 100.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // more bins; with few open bins, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: reserve it for items that fit no open bin well.
    // Penalize the fresh bin by its wasted capacity unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        if post_residual as f64 > bin_capacity as f64 * 0.4 {
            score += 40.0; // opening a bin for a small item wastes space
        }
    }

    // Slight preference for bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits tightly with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0);
    }

    // Penalize dead space below plausible minimum item size
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when plenty of open capacity exists
    if bin_residual == bin_capacity {
        score += 60.0 + 3.0 * open_bins_count as f64;
        // But allow new bin if mean residual is very fragmented
        if mean_residual < item_size as f64 * 0.3 {
            score -= 80.0;
        }
    }

    // Reward using bins with residuals close to mean (balance retention)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late in stream: prefer tight fills to close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 + 0.25 * post_residual as f64;
        } else if post_residual >= next_item_size {
            score -= 6.0; // bin remains useful for lookahead item
        }
        // Perfect pairing: item + next item fills bin nearly exactly
        let pair_waste = (bin_residual as i64 - item_size as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 8.0 * (1.0 - pair_waste / bin_capacity as f64).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening more when many bins are already open or residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But allow a new bin if mean residual across open bins is very low (fragmentation).
        if mean_residual < 0.35 * bin_capacity as f64 {
            score -= 40.0;
        }
        // Allow new bin if item is huge relative to typical residuals.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins with larger residual early, conserving small-residual bins.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer balanced global state: penalize when this bin is far below mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.03 * dev * dev * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let res_frac = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Non-linear waste penalty: squared/cubic residual terms scaled by progress
    score += 2.5 * res_frac * res_frac * cap * (0.5 + 0.5 * progress);
    score += 1.2 * res_frac.powi(3) * cap * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 3.0 * fit_frac * fit_frac * cap * (0.3 + 0.7 * progress);

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits in leftover: mild bonus for leaving usable space
            score -= 1.5 * (nx / cap) * (1.0 - (nx - pr).abs() / cap);
        } else {
            // leftover too small for next item: penalize dead space
            score += 2.0 * res_frac * cap * (1.0 - nx / cap);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Many open bins: discourage spreading; few bins: encourage filling
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 1.0 * open_norm * res_frac * cap * 0.5;

    // Mean residual divergence: prefer bins near the mean to balance
    score += 0.4 * ((pr as f64 - mean_residual) / cap).abs() * cap * 0.3;

    // New-bin candidate: penalize opening fresh bins unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - fit_frac) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in a
    // "useful" residue class (small remainders or multiples of common item
    // sizes) are preferred over bins leaving awkward mid-range dead space.
    let pr = post_residual;
    let dead_zone = (pr > 0 && pr < 10) as i32;
    let harmonic_bonus = match pr % 10 {
        0 => 6.0,           // clean multiple of 10: highly reusable
        1 | 2 | 3 => 4.0,   // nearly clean, tiny waste
        _ => 0.0,
    };
    score += harmonic_bonus - dead_zone as f64 * 2.0;

    // Penalize post-residuals in the "unfillable middle band" (11..=19):
    // most items are >= 10 and these gaps rarely admit anything.
    if pr >= 11 && pr <= 19 {
        score += 8.0;
    }
    // Odd residues that cannot pair with a next item are dead.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += (next_item_size - pr) as f64 * 0.5;
    }
    // Reward exact fill.
    if pr == 0 {
        score -= 25.0;
    }
    // Reward leaving exactly the space the next item needs.
    if next_item_size > 0 && pr == next_item_size {
        score -= 15.0;
    }
    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // New-bin candidate: prefer it only when item is huge or all open bins
    // would leave large waste. Penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 6.0 * (1.0 - progress);
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Tightness reward: the fuller the bin, the better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Mean-residual coupling: when open bins are generally full, discourage
    // spreading; when they are loose, encourage consolidation into tight fits.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // likely unusable "dead" gaps. Penalize them super-linearly.
    let pr = post_residual as f64;
    if !is_new_bin && post_residual > 0 && post_residual < 12 {
        score += 18.0 * (12.0 - pr) / 12.0; // gap too small for most items
    }
    // Reward near-perfect fits strongly.
    if !is_new_bin && post_residual < 4 {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; add pressure proportional to count.
    score += 0.35 * open_bins_count as f64 * (1.0 - pr / bin_capacity as f64);

    // Prefer bins whose residual is close to what we consume (tight packing).
    score += 0.5 * (mean_residual - pr).abs() * 0.1;

    // Lookahead: if next item would fit exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 12 {
        score -= 6.0;
    }
    // If next item cannot fit in post residual, mild penalty (fragmentation risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate must lose against any reasonable existing fit;
    // only chosen when all open bins score badly (poor fits / dead space).
    if is_new_bin {
        score += 22.0;
        // Slightly cheaper to open a new bin early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins where the next item exactly
    // matches the post-residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits too: chain bonus scaled by how snugly
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving space that
            // is just barely too small for the next item (dead space risk)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 20.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // post-residual stays near the mean (keeps future options open).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, opening bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference to consolidate across many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot fit here; penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Prefer filling already-open bins when many are open (avoid bin sprawl).
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;

    // New-bin candidate: make it attractive only when the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 50.0; // opening a new bin is fine when no good alternative exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: minimize post residual (tight fits preferred)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, leave room (mildly penalize very tight fits); late, squeeze hard.
    let poly = 1.0 - 3.0 * progress + 3.0 * progress * progress;
    score += 12.0 * pr_norm * pr_norm * poly * cap * 0.1;

    // Reward near-perfect fits, stronger as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= (item_size as f64 / cap) * (1.0 + progress) * 8.0 * tightness * tightness;

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize crowded bin field lightly to encourage consolidation
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space scaled by gap
        score += 0.05 * post;
    }

    // New-bin candidate: only attractive when all open residuals are small
    // and post_residual is large (fresh space). Smooth logistic-style gate.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        let mean_gap = (mean_residual - cap).abs();
        let gate = 1.0 / (1.0 + (-(mean_gap / cap - 0.5) * 6.0).exp());
        score = 30.0 + 40.0 * gate + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse buckets of 10.
    // Larger dead-space classes are penalized progressively (super-linear).
    let residual_class = (post_residual / 10) as f64;
    score += residual_class * 3.0;

    // Perfect closure: bin completely filled.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo-10 alignment bonus: residuals that are round numbers
    // compose better with typical item sizes.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Lookahead (k=2): does the next item fit in the resulting space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room for the next item.
            score -= next_item_size as f64 * 0.5;
            // Exact two-item closure (harmonic pair).
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Penalize creating a residual too small for the next item
            // (likely dead space).
            score += 10.0;
        }
    }

    // New-bin candidate: generally discouraged, but attractive for large
    // items that would otherwise strand tiny residuals in open bins.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 50 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 8.0;
        }
    } else {
        // Last-chance bin: if this is the only open bin that fits,
        // strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual across open bins: prefer placements
    // that bring this bin's residual toward the fleet mean (balance).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Integer-division threshold: residuals below 10 are nearly dead space
    // (min item size is 1); penalize heavily unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more than large residuals.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / (post_residual as f64 + item_size as f64)) * 8.0;
    }

    // Open bins pressure: penalize spreading across many bins when few fit.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.15;
    } else {
        // Last chance bin: strong reward to use it.
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // New-bin candidate: only attractive if no good fit exists (all fits are poor).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; pressure grows with stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + progress * 5.0 + open_bins_count as f64 * 0.5;
        // But if the only fitting bins would leave dead space, ease new bin.
        if fitting_bins_count == 1 && (post_residual as f64) < dead_threshold {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 400.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 2.0 * overshoot;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize creating tiny unusable residuals when many bins are open.
    if post_residual > 0 && post_residual < 5 && open_bins_count > 1 {
        score += 50.0;
    }

    // Late in the stream, tighten packing (fewer wasted residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mild penalty for opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 80.0;
        // But allow new bin if current item is large and next item is also large
        // (reserve space strategy).
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

