    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += residual_frac * residual_frac * 8.0;

    // Global state: if many bins are open with high mean residual, discourage
    // spreading items thin; prefer bins below mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Penalize opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost is its post_residual (already ~100),
        // plus a penalty that grows with number of open bins.
        score += 5.0 + open_bins_count as f64 * 1.5;
        // But if no open bin fits well (large post_residual would remain),
        // opening a new bin is fine: soften penalty.
        if post_residual == 0 {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is more wasteful.
        score += progress * 10.0;
    }

    // Mild penalty for leaving residuals in the awkward 1..10 dead-space band.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 - post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
