        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 14.0 * (1.0 - slack * 4.0).max(0.0);
        } else {
            score += 10.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Last-chance bin before opening a new bin: strong preference to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize bins that deviate from mean residual (encourage balanced filling),
    // with a smooth normalized deviation term.
    let dev = (res - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.abs().max(0.5);

    // New-bin candidate: make it mildly unattractive early, more acceptable late
    // or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap;
        score += 14.0 - 22.0 * progress - 18.0 * avg_fullness * avg_fullness;
    }

    // Slight preference for fuller bins overall (residual small => lower score).
    score += 0.08 * (res - item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // dead-space classes: residuals that are hard to fill later
        let class = post_residual % 10;
        if class >= 1 && class <= 3 {
            score += 8.0 + class as f64;
        }
        // mid-range residual is somewhat usable
        if post_residual >= 30 && post_residual <= 60 {
            score -= 6.0;
        }
    }

    // Lookahead pairing: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly chain
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap <= 5 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize more if residual small/dead
            if post_residual < 10 {
                score += 12.0;
            } else {
                score += 3.0;
            }
        }
    } else {
        // last item: prefer any bin that fits, close waste
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // open new bin if mean residual is low (open bins nearly full)
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
        // early stream: allow more bins
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer fuller bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Harmonic modulo coupling between item and residual classes
    let h = (item_size % 20) as f64;
    let r = (bin_residual % 20) as f64;
    score += (h - r).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for any plausible item (min size 1..~10 typical)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space for the known next item
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits into post_residual: mild reward proportional to how well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    }
    // Next item would NOT fit here: mild penalty for leaving awkward gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Compare residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 10.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when good existing options exist,
    // but allow it when the new bin would be much better used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin starts with score = capacity; adjust to compete with open bins.
        score -= 70.0;
        // Early in stream: be more willing to open bins.
        score -= 20.0 * (1.0 - progress);
        // If next item is huge and this item is small, opening fresh bin is fine.
        if next_item_size > 60 && item_size < 40 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item fits poorly anywhere else
    // or when open bins are already quite full on average.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / (bin_capacity as f64);
        let poor_fit = if fitting_bins_count <= 1 { 0.0 } else { (post_residual as f64) / (bin_capacity as f64) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 14.0 * mean_fill - 8.0 * poor_fit - 6.0 * progress;
        // Late in the stream, prefer consolidation into open bins.
        if progress > 0.8 {
            score += 8.0 * progress;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate emptier bins).
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.15 * dev;

    // Mild preference for keeping the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: minimize post residual, but with non-linear decay so tiny residuals are prized more
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize loose fits more strongly
    score += 15.0 * progress * norm_pr * (1.0 - fit);

    // Quadratic interaction between fit tightness and progress
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize bins deviating from mean residual (keep pool balanced), smoothly
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Last-chance bin: reward strongly with smooth saturation
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (nx / cap);
        } else {
            score += 4.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() + 8.0 * (1.0 - fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (likely to match future small items).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division of post_residual into octiles.
    let octant = post_residual / (bin_capacity / 8).max(1);
    match octant {
        0 => score -= 8.0,           // near-perfect fit, excellent
        1 => score -= 5.0,           // small gap, still very useful
        2 => score -= 2.0,
        3 => score += 0.5,
        4 => score += 1.5,           // mid-gap: dead-space risk
        5 => score += 0.5,
        6 => score -= 1.0,           // large residual, easy to refill
        _ => score -= 3.0,           // almost empty bin, flexible
    }

    // Modulo coupling: residuals divisible by small item sizes are reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        else if post_residual % 5 == 0 { score -= 1.5; }
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 4.0; // next item would fill bin exactly
        }
    }

    // Lookahead: strongly favor bins where next item also fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize if this creates stranded space.
        score += 2.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or
    // the fit is poor; penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64) < 0.5 * cap;
        let crowded = mean_residual < 0.25 * cap;
        let mut nb = 12.0;
        if poor_fit { nb -= 6.0; }
        if crowded { nb -= 4.0; }
        nb -= progress * 3.0;
        if open_bins_count == 0 { nb = -100.0; }
        score += nb;
    }

    // Slight preference for tighter existing bins beyond raw post_residual.
    score += (bin_residual as f64 - pr) * 0.0;
    score - (item_size as f64) * 0.02
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A post_residual that is too small for typical future items is wasted space.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize post_residuals that cannot fit the lookahead item if this bin
    // would otherwise be a good home for the next item too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward bins that can still host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; when few bins are open, tolerate
    // imperfect fits.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Mild mean-residual coupling: prefer bins close to the mean residual
    // (keeps residual distribution tight, leaving large gaps in few bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when current bin residuals are
    // heavily fragmented (high mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 {
            score -= 12.0 * (fragmentation - 0.5);
        } else {
            score += 15.0;
        }
    }

    // Late in the stream, tighten up: penalize leaving any residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already favored by base term).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            if gap < 1.0 {
                score -= 500.0;
            } else if gap <= 10.0 {
                score -= 100.0 - gap * 5.0;
            } else {
                // next item fits but leaves more slack: mild reward scaled by tightness
                score -= (post_residual as f64 / next).max(1.0).ln() * 10.0;
            }
        } else {
            // next item cannot fit in the remainder: penalize proportional dead space
            score += gap * 0.5;
        }
    }

    // Relative-to-mean-residual coupling: prefer filling bins that are already
    // below-average residual (consolidating slack), avoid dumping into large-residual bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Discourage opening a new bin when existing bins give a reasonable fit.
    if bin_residual == bin_capacity {
        // new-bin candidate: base score is bin_capacity (100) via post_residual;
        // add a penalty that shrinks late in the stream when consolidation matters most.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress;
        // but if no open bin fits well (item large relative to mean residual), ease penalty
        if item_size as f64 > mean_residual {
            score -= 60.0;
        }
    }

    // Mild preference for using more-open-bins states efficiently early on.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // next item can still go here; mild reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 5.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large awkward gaps
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.15 * gap;
            }
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: later in the stream, be more conservative about leaving gaps
    // (fewer chances to fill them), but more willing to use existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * progress * post_residual as f64;
    score -= 2.0 * progress * (fitting_bins_count as f64).ln().max(0.0);

    // Penalize scattering across many open bins when the item is large.
    if item_size > bin_capacity / 2 {
        score -= 3.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when open bins
    // are crowded or the fit elsewhere is poor; base penalty keeps them from winning by default.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count == 0 {
            score -= 20.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin can serve the larger upcoming item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * (1.0 + 2.0 * progress * (1.0 - progress));
    score += 40.0 * poly;
    // Reward tight fits, more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);
    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - nx / (pr + 1.0));
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }
    // Mild pressure to reuse existing bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);
    // New-bin candidate: prefer it only when residuals are mostly large
    if bin_residual == bin_capacity {
        let open = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let mean_frac = mean_residual / cap;
        score = 20.0 + 60.0 * mean_frac * mean_frac + 2.0 * open * progress - 25.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead zone" penalties.
    let post = post_residual;
    let residue = post % 10;
    // Penalize awkward residues (small unusable slivers like 1..9 on top of a packed bin)
    if post > 0 && post < 10 {
        score += 8.0; // tiny dead space is worthless
    } else if residue >= 1 && residue <= 4 {
        score += residue as f64 * 0.6;
    } else if residue >= 6 && residue <= 9 {
        score += (10 - residue) as f64 * 0.4;
    }
    // Perfect fits (post == 0) are golden
    if post == 0 {
        score -= 15.0;
    }

    // Harmonic fraction of capacity used by the item
    let frac = item_size as f64 / bin_capacity as f64;
    let octave = (frac * 4.0).floor() as f64; // quarter-capacity classes
    score -= octave * 2.5; // reward larger items placed (they close bins)

    // Integer-division thresholds: does post_residual still hold next_item_size?
    if next_item_size > 0 {
        if post >= next_item_size {
            // chainability reward, stronger when next item is harmonic with capacity
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            let bonus = 6.0 + (next_frac * 10.0).floor() * 0.5;
            score -= bonus;
            // extra reward if post is an integer multiple of next_item_size (exact chaining)
            if next_item_size > 0 && post % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally to the leftover gap
            score += (next_item_size - post) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Too many open bins: encourage consolidation
    if open_bins_count > 4 {
        score -= (open_bins_count as f64) * 0.4;
    }

    // New-bin candidate: default mild preference; override only when current fits are bad
    if bin_residual == bin_capacity {
        score = 55.0
            - (if next_item_size > 0 && next_item_size >= 50 { 10.0 } else { 0.0 })
            - (fitting_bins_count as f64) * 1.5;
    }

    // Stream progression: early on, be conservative with tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post < 10 && post > 0 {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space) more aggressively than large residuals.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 30.0;
    }
    // If next item fits in the post residual, mild reward.
    else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // Penalize leaving residual far from mean (fragmentation signal).
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or when open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.3;
        if post_residual == bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact closure of the bin.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward a post_residual that exactly matches the next item.
    if next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how snug the fit is
            score -= 150.0 * (ni / pr);
        } else {
            // next item cannot use the leftover: penalize dead space severity
            score += 40.0 * ((ni - pr) / ni);
        }
    }

    // Penalize small unusable residuals (dead space), except exact matches above.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bin: strong bonus to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty so a decent existing fit wins; reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 - 40.0 * progress;
        // If the next item is large, opening a fresh bin is less attractive.
        if next_item_size > 50 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize dead space relative to the smallest plausible future item (1..100 range).
        let dead = post_residual as f64;
        score += (dead / 100.0).powf(2.0) * 40.0;
        // If nothing else can ever fit in the leftover, treat it as waste.
        if post_residual < 1 {
            score += 50.0;
        }
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for the next item: mild penalty scaled by tightness.
        score += (next_item_size as f64 - post_residual as f64) * 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tighter bins: closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Global state: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += open_pressure * 0.6 * (1.0 - progress);

    // Mean residual coupling: if mean residual is large, discourage leaving more.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item, no lookahead compatibility, many open bins).
    if bin_residual == bin_capacity {
        let escape_bonus = 5.0 + (item_size as f64) * 0.3;
        score += 60.0 - escape_bonus * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = progress.clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base: prefer small post_residual, with growing urgency as stream advances.
    let norm_pr = pr / c;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) + norm_pr * (1.5 - t);

    // Smooth dead-space penalty: residuals that can't fit typical future items.
    let mean_r = mean_residual.max(0.0);
    let dead = (norm_pr * norm_pr) * (mean_r / c).sqrt() * (0.5 + t);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { 3.0 * (1.0 - norm_pr) * (0.5 + t) } else { 0.0 };

    // Lookahead: reward leaving space compatible with the next item.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        -2.0 * (-gap / c).exp() * (1.0 - t * 0.5)
    } else {
        0.0
    };

    // Mild pressure to consolidate into fewer bins late in the stream.
    let consolidation = (open_bins_count as f64).ln() * norm_pr * t * 0.3;

    let mut score = pr + poly * c * 0.5 + dead * c - last_chance * c * 0.2 + lookahead + consolidation;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in low classes (near 0) are "dead space".
    let class = post_residual / 10; // 0..10 harmonic class
    let class_penalty = match class {
        0 => -18.0,            // near-perfect fill: strongly reward
        1 => -10.0,
        2 => -5.0,
        3 => 2.0,
        4 => 4.0,
        5 => 6.0,              // half-full residual: mediocre
        6 => 5.0,
        7 => 3.0,
        8 => 1.0,
        9 => -3.0,             // nearly empty bin: reusable
        _ => -6.0,             // untouched bin
    };
    score += class_penalty;

    // Non-linear dead-space penalty: small residuals are quadratic bad.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Modulo coupling: if the next item would fit exactly into the post residual
    // (post_residual % next_item_size == 0 with quotient >= 1), reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let k = post_residual / next_item_size;
        if post_residual % next_item_size == 0 && k >= 1 {
            score -= 8.0 + 2.0 * k as f64;
        } else {
            // leftover after next item placement
            let next_left = post_residual - next_item_size;
            if next_left <= 5 {
                score -= 7.0; // chain of near-perfect fills
            } else if next_left > 20 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 0.05 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // good existing fits, but keep it competitive when fits are poor.
    if bin_residual == bin_capacity {
        score += 14.0;
        // If item is large, opening a fresh bin is more attractive.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mean residual coupling: when open bins are already sparse, penalize
    // spreading items into many bins.
    if open_bins_count > 0 {
        let ratio = mean_residual / bin_capacity as f64;
        if ratio < 0.15 {
            score -= 3.0; // bins nearly full; use them up
        } else if ratio > 0.6 {
            score += 2.0 * ratio; // many empty bins; consolidate
        }
    }

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (given minimum item size 1, but practically < ~12) are poison.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual matches the lookahead item (chain fits).
    if next_item_size > 0 {
        let d = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if post_residual as u32 >= next_item_size {
            score -= (20 - d.min(20)) as f64 * 1.5;
        } else if d <= 12 {
            score += (12 - d) as f64 * 2.0; // lookahead barely doesn't fit: bad
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is attractive only when no open
    // bin offers a good fit. Penalize it mildly so tight fits in open bins win,
    // but let it win when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        if post_residual < 12 {
            score -= 40.0; // fresh bin keeps residual large: fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches of post_residual with next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: next item fills bin exactly
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last item: reward tight packing
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize dead space: small post_residual that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make empty bins moderately unattractive unless existing fits are terrible
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // Early in stream: opening bins is cheaper; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Large item relative to residual: penalize waste proportionally
    score += 0.3 * (item_size as f64 / bin_residual.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit gets a large bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: reward bins whose post-residual fits the next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual < next_item_size {
        // bin becomes useless for the known next item; mild penalty
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Time horizon: late in the stream, be more conservative, prefer tight packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: when mean residual is high, encourage using existing space
    score -= 5.0 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: penalize opening a new bin unless current bin is very poor
    if bin_residual == bin_capacity {
        // opening new bin is only attractive if item is huge and fits poorly elsewhere
        score += 30.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically, scaled by progress (late stream => more waste matters).
    score += 1.5 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 1.2 * tightness * (1.0 - pr_norm);

    // Lookahead: penalize if next item cannot use the resulting post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 0.9 * (nxt / cap) * (0.4 + progress);
        } else {
            score -= 0.5 * (nxt / cap) * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.15 * (open_bins_count as f64).sqrt() * (mean_residual / cap) * (1.0 - pr_norm);

    // New-bin candidate: keep its score moderate so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 0.6 + 1.0 * progress - 0.3 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes; small residuals are dead space.
    let post = post_residual;
    let class = post % 10;
    if post > 0 {
        // Penalize residuals that no plausible item (1..=100) can use well.
        if post < 10 {
            score += 12.0; // tiny dead space
        } else if post < 20 {
            score += 4.0;
        } else if post <= 25 {
            score -= 2.0; // sweet spots: usable by small items
        }
        // Exact-fill harmony: residual divisible into nice chunks
        if post % 25 == 0 { score -= 3.0; }
        if post % 20 == 0 { score -= 2.0; }
        if class == 0 { score -= 1.5; }
    } else {
        score -= 10.0; // perfect fill
    }

    // Lookahead coupling: does next item fit the post-residual harmonic class?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits perfectly or near-perfectly here
            let gap = post - next_item_size;
            if gap == 0 { score -= 8.0; }
            else if gap < 10 { score -= 4.0; }
            else { score -= 1.0; }
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += (next_item_size - post) as f64 * 0.08;
            if post < next_item_size && post < 20 { score += 5.0; }
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Prefer tight fits (low waste fraction) with non-linear reward
    let waste_frac = post as f64 / cap;
    score -= (1.0 - waste_frac) * (1.0 - waste_frac) * 3.0;

    // Early in stream: be pickier about opening new bins (favor reuse)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline near capacity cost, adjusted by state
        let mut newbin = cap * 0.62;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            newbin += 8.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size >= 60 {
            newbin -= 6.0; // big next item benefits from fresh bin
        }
        if mean_residual < 15.0 && open_bins_count > 0 { newbin -= 4.0; }
        score += newbin;
    } else {
        // mild preference to keep bins balanced around mean residual
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.03;
        // favor using bins with smaller residual (tighter packing)
        score += bin_residual as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for the smallest plausible item.
    let dead_threshold = 9.0; // items >= 10 in classic regime; small margin for 1..100 streams
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger usable residuals are mildly favored (leave room for future items).
        score -= 0.25 * post_residual as f64;
    }

    // Dead space is worse if the next item cannot use it either.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0 * (post_residual as f64 / dead_threshold);
    }
    // Reward if next item exactly fills the resulting gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large, flexible residual and few bins are open.
    if bin_residual == bin_capacity {
        let flex = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - flex)          // penalize if item eats most of fresh bin
               + 15.0 * open_bins_count as f64; // opening new bins gets costly as bins accumulate
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can also host the lookahead item
        }
    }

    // Slight alignment with mean residual: prefer bins whose residual is close to need.
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect lookahead match: next item exactly fills this bin
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain fill bonus
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here: penalize wasted lookahead potential
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fit)
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.5 * mean_gap;

    // Penalize tiny unusable dead space unless lookahead rescues it
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_load = 1.0 - mean_residual / bin_capacity as f64;
        score += 55.0 - 50.0 * avg_load;
    }

    // Early stream: be more conservative, keep bins open for future flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (min size 1).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 10.0 * (item_size as f64) / (bin_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible;
    // late in the stream, aggressively close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 8.0 * tightness;

    // Global state: many open bins with high mean residual -> favor consolidation
    // into existing bins over opening new ones.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin gets a mild default penalty so it is
    // only chosen when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        // But if no open bin can fit at all (this is the only candidate), it wins naturally.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Small penalty on very large item relative to residual (near-full usage is good,
    // but item barely fitting leaves fragile residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.95 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post_residual (tight fit), scaled by capacity.
    let mut score = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (super-linear penalty).
    let pr_norm = pr / cap;
    score += 1.6 * pr_norm * pr_norm * (0.5 + progress);

    // Reward very tight fits with a smooth saturating term.
    score -= 0.9 * (-pr_norm * 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else {
        // Mild penalty when many bins compete (prefer spreading via best fit anyway).
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 0.7 * (-slack * 6.0).exp();
        } else {
            // Smooth penalty if next item cannot use the leftover space.
            score += 0.4 * ((nxt - pr) / cap);
        }
    }

    // Mild global pressure: fewer open bins relative to mean residual is fine;
    // penalize placements into bins far above mean residual (fragmentation avoidance).
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // New-bin candidate handling: empty bin has pr = cap; discourage opening a new
    // bin unless the item is large relative to capacity (smooth term).
    if bin_residual == bin_capacity {
        score += 1.2 - 1.2 * (item_size as f64 / cap);
    }

    // Slight preference to fill bins with more content already (larger item_size use).
    score -= 0.15 * (item_size as f64 / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: bins partitioned by capacity fraction ---
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Integer-division thresholds: classify post_residual into harmonic bands
    // (0..12.5, 12.5..25, 25..50, 50..100). Small dead space is good.
    let harmonic_class = post_residual / (bin_capacity / 8); // 0..=8 bands
    match harmonic_class {
        0 => score -= 40.0,                       // near-perfect fill
        1 => score -= 22.0,                       // excellent
        2 => score -= 10.0,                       // good
        3 => score -= 3.0,                        // decent
        4 | 5 => score += 8.0,                    // half-empty: mediocre
        6 => score += 18.0,
        7 => score += 26.0,
        _ => score += 34.0,                       // bin barely touched
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonically
    // compatible" with common small items (multiples of 5/10) are reusable.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 12.0;
    } else if m10 == 5 {
        score -= 6.0;
    } else {
        score += (m10 as f64) * 0.8; // awkward remainder penalized
    }

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals the next item cannot use at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect two-item chaining
        } else if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            // reward tight next-fits (nfrac near 1)
            score -= 25.0 * nfrac * nfrac;
        } else {
            score += 10.0; // next item can't use this residual
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor-fit situation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual, which
    // the harmonic bands already penalize; add extra bias so a new bin is only
    // opened when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        }
    }

    // Stream progression: early on, be slightly conservative (keep bins open
    // for flexibility); late, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / cap);

    // Mean-residual coupling: if this bin's residual deviates strongly from
    // the mean, normalize slightly toward balanced packing.
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward perfect closure.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item's needs.
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Open-bins pressure: mildly prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to how many bins are open,
        // and to how many bins could otherwise fit the item.
        score += 25.0 + 4.0 * open_bins_count as f64 + 8.0 * fitting_bins_count as f64;
        // But allow opening a new bin late in the stream if mean residual is low.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Existing-bin bonus, stronger when this is the only fitting bin.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Slight stream-progression damping to stay adaptive.
    score *= 1.0 - 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else {
        score += (post_residual as f64).powf(1.35) * 0.35;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 55.0;
        } else {
            score -= 25.0 * (1.0 - next_fit as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here; penalize dead space proportional to gap.
        score += (next_item_size - post_residual) as f64 * 0.45;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.30;

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer using existing bins over opening new ones, more so late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * progress;
    }

    // Slight preference for keeping many small bins consolidated when many open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let last_chance = fitting_bins_count == 1 && !is_new_bin;

    // Reward near-perfect fits: subtract bonus proportional to tightness.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Reward if the lookahead item can also fit in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 0.15 * post_residual as f64;
    }

    // Last usable bin: strongly favor using it to avoid opening a new bin.
    if last_chance {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: only attractive when the item is large (fills well)
    // or the global mean residual suggests open bins are nearly full.
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        let openness = (mean_residual / bin_capacity as f64).min(1.0);
        // Penalize opening new bins by default...
        score += 18.0;
        // ...but discount the penalty when the item fills the new bin well
        // and existing bins are already tight on average.
        score -= 18.0 * fill * fill * (1.0 - openness);
        // Early in the stream, opening bins is cheaper (more items to come
        // to fill them); late in the stream, be conservative.
        score += 6.0 * progress;
        // If many bins are already open, discourage spreading further.
        score += 0.05 * open_bins_count as f64;
    }

    // Mild penalty for tiny leftovers that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 30.0 * poly * (1.0 - progress * 0.5);

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 5.0 * (gap / cap) * (1.0 + progress);
    } else if next_item_size > 0 && post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    // Slight preference to keep new bins closed mid-stream
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: prefer residuals that are
    // "perfect fits" (0), or leave space usable by common small items.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, close the bin
    } else if pr <= 10 {
        score -= 300.0; // near-perfect, dead space is minimal
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are more likely
    // to be exactly filled by future items (sizes often multiples of 10).
    if pr % 10 == 0 && pr > 0 {
        score -= 60.0;
    } else if pr % 5 == 0 {
        score -= 25.0;
    }

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0; // chain of perfect fits
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            if (pr - next_item_size) % 10 == 0 {
                score -= 40.0;
            }
        } else {
            // next item cannot reuse this residual: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.6 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 250.0; // nothing else fits: open a new bin
        }
    }

    // Late in the stream, consolidate: prefer tightest fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Tie-break with mean residual divergence: avoid bins far from the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size (1) are impossible,
    // but residuals in the small-gap band are highly likely to be wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: fraction of residual consumed, non-linearly amplified.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that cannot host the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer filling existing ones.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than average (below mean residual => better packed).
    score += 3.0 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin offers a good fit;
    // penalize opening new bins while plenty of bins are open.
    if bin_residual == bin_capacity {
        score += 35.0 + 6.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
