pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared penalty on wasted space, stronger early
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64 * (1.2 - 0.7 * t);

    // Strong reward for exact / near-exact fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (item_size as f64 / bin_residual as f64);
    }

    // Many fitting bins => be picky; few fitting bins => accept looser fits
    if fitting_bins_count > 1 {
        score += 6.0 * (fitting_bins_count as f64 - 1.0).min(8.0);
    }

    // Penalize bins far from the mean residual when the item leaves big slack
    score += 0.15 * (bin_residual as f64 - mean_residual).abs()
        * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: reward if the post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.2 * (next_item_size as f64);
            // bonus if next item then nearly fills the bin
            if post_residual - next_item_size <= 10 {
                score -= 10.0;
            }
        } else {
            // post residual is dead space relative to the next item
            score += 0.25 * post_residual as f64;
        }
    } else {
        // last item: prefer filling the fullest bin
        score -= 0.4 * (bin_capacity - bin_residual) as f64;
    }

    // Prefer filling already-open bins when many are open (avoid bin proliferation)
    if bin_residual < bin_capacity {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * t);
    } else {
        // new-bin candidate: only attractive when item is large or open bins are crowded
        let crowded = open_bins_count as f64 > 3.0 + 4.0 * t;
        if item_size >= 60 && !crowded {
            score += 18.0; // discourage new bin for large items that fit elsewhere
        } else if crowded {
            score -= 10.0;
        }
    }

    // Mild time-horizon term: early on, conserve space; late, fill aggressively
    score -= 10.0 * t * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += poly * 40.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Penalize leaving residuals close to next item size mismatch
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let gap_norm = gap / bin_capacity as f64;
        score += gap_norm * gap_norm * 15.0;
        // Reward exact-enough fit for next item
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - gap_norm);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 8.0 + 10.0 * (1.0 - progress) + pressure;
    }

    // Coupling with mean residual: prefer bins deviating from mean in the right direction
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 10.0 - dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it's not dead space.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        // Unusable sliver: heavily penalize, worse the more space is wasted relative to capacity.
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class: how well does post_residual partition into capacity fractions?
    // Residuals that are multiples of common item classes (multiples of 10/20/25) are reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable && post_residual >= 10 {
        score -= 8.0;
    } else if post_residual >= 10 {
        score += 4.0;
    }

    // Lookahead: if next item fits into post_residual, reward keeping this bin viable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
            // Extra reward if next item exactly fills the remaining space after this placement.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize slightly, scaled by leftover waste.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residual below the mean (denser bins) mildly.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly worse than a good fit, better than a bad one.
        score = 30.0 - 5.0 * progress + 0.1 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open a new bin when an existing one is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small leftover gaps (< 10, min item size) are unusable.
    if post_residual < 10 {
        score -= 25.0; // perfect or near-perfect fill, reward heavily
    } else if post_residual <= 20 {
        // gap only usable by tiny items; mild penalty relative to base
        score += (20 - post_residual) as f64 * 0.5;
    } else {
        // larger gaps are flexible; slight reward for keeping usable space
        score -= 2.0;
    }

    // Reward exact fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize creating a bin that strands the next item
        score += 8.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to residual use
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Prefer bins tighter than the mean residual (better fits)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 500.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - nxt;
            // penalize residual that is just barely above next item (awkward gap)
            score += gap * 0.3;
        } else {
            // next item cannot fit here; penalize small dead space
            score += 50.0 + (nxt - post_residual as f64) * 0.5;
        }
        // if post_residual fits next item, mild bonus scaled by tightness
        if post_residual >= next_item_size && post_residual as f64 != nxt {
            score -= 20.0 * (1.0 - gap_abs(post_residual as f64, nxt) / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.4;
    } else {
        score += (resid - mean_residual) * 0.2;
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin early in stream unless fit is terrible
    if bin_residual == bin_capacity {
        // new-bin candidate: base score high unless item is large
        score += 300.0 - item_size as f64;
        // if next item is large, prefer keeping current bins for it
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 100.0;
        }
    }

    // Stream progression: later in stream, tighten packing more aggressively
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.5 * progress;

    score
}

#[inline]
fn gap_abs(a: f64, b: f64) -> f64 {
    if a > b { a - b } else { b - a }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit via post_residual, with a superlinear waste penalty
    // so that small leftover slivers are strongly discouraged.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    }
    // Penalize near-miss: next item almost fits (dead-end risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many competing bins: prefer the tightest one, dampen spread noise.
    if fitting_bins_count > 3 {
        score += 0.05 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: when mean residual across open bins is large,
    // we can afford looser fits; when it is tight, prefer frugal placements.
    score += 0.1 * (mean_residual - pr);

    // Time horizon: early in the stream, be conservative about opening
    // bins (favor filling existing ones); late in the stream, allow
    // opening fresh bins since leftover space matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    // Penalize it mildly by default so existing bins are preferred, but
    // discount the penalty when the item is large and no bin fits well
    // (large post_residual everywhere), letting the fresh bin win when
    // existing placements would strand the item's size class.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let large_item_relief = (item_size as f64 / cap) * 20.0;
        let crowd_relief = 0.5 * open_bins_count as f64;
        score += base_penalty - large_item_relief - crowd_relief;
    }

    // Exact-fit celebration: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: residual^2 scaled by mean residual context
    let mean_norm = mean_residual / cap;
    score += 30.0 * pr_norm * pr_norm * (1.0 - mean_norm);

    // Reward tight fits smoothly (small post_residual relative to item)
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_quality * fit_quality;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item smoothly
    let nxs = next_item_size as f64;
    if nxs > 0.0 {
        let room = (pr - nxs) / cap;
        if room >= 0.0 {
            score -= 15.0 * room * (1.0 - room);
        } else {
            score += 10.0 * (-room) * (1.0 - progress);
        }
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits and residuals
    // that are exact divisors of the capacity are highly reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit: ideal
    } else if cap as u32 % pr == 0 {
        score -= 120.0; // harmonic residual (e.g. 50, 25, 20, 10)
    } else if pr % 10 == 0 {
        score -= 40.0; // decade residual: still fairly reusable
    } else if pr < 10 {
        score += 150.0; // dead space below smallest item
    }

    // Integer-division threshold: bucket the residual into coarse classes
    // and penalize low utility classes.
    let class = pr / 15; // coarse harmonic bucket
    score += class as f64 * 6.0;

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 30.0;
            if pr == next_item_size {
                score -= 60.0; // next item fills bin exactly
            }
        } else {
            score += 25.0; // next item cannot use this residual
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are crowded or the fit here is bad.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // residual of a fresh bin
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: must open
        } else {
            score += (fitting_bins_count as f64) * 8.0
                + mean_residual * 0.5; // prefer reusing roomy open bins
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0; // fresh bin can host a pair
        }
    }

    // Stream progression: early on, be conservative with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small leftover gaps (1..=10) are
    // nearly unusable for future items; penalize them heavily so that
    // a bin leaving a tiny gap loses to one leaving a usable gap.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    }

    // Moderately small gaps (11..=20) are mildly risky too.
    if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer
    // using it over opening a new bin unless the dead space is bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the stream is early
    // (room to grow) or all existing fits would create dead space.
    if bin_residual == bin_capacity {
        score += 25.0; // default bias toward existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If the next item is large and this new bin stays empty-ish,
        // a fresh bin can absorb it: small bonus.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 5.0;
        }
        // Many open bins with large mean residual: opening more bins is wasteful.
        score += (open_bins_count as f64).sqrt() * 3.0 + (mean_residual / 20.0);
    }

    // Prefer bins whose residual is close to the item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward leaving exactly next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);
        // Penalize leaving space that is too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 30.0;
    }

    // Reward bins tighter than the mean residual (denser bins get priority)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a needless new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64) < 0.8;
        let poor_fit = (item_size as f64 / bin_residual as f64) < 0.5;
        if !(crowded || poor_fit) {
            score += 150.0;
        } else {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins early in the stream
    score -= 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits strongly (non-linear)
    score -= 40.0 * fill * fill;

    // Penalize leaving small dead space that nothing can use later:
    // post_residual in (0..10) is nearly useless waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Reward post_residual that could fit a typical small item (>=10)
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits into the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.3 * next_item_size as f64;
    }
    // If next item almost fits (small miss), mild penalty for wasting the slot
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: prefer the tightest one naturally via fill term;
    // slight penalty to spread out selection noise
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: when mean residual is high, prefer packing into existing bins
    let mean_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
    score -= 0.15 * mean_res;

    // Penalize opening new bins more as the stream progresses (less time to fill them)
    let new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if new_bin {
        let open_pressure = (open_bins_count as f64).ln() + 4.0 * progress;
        score += 20.0 + 5.0 * open_pressure;
        // But if no open bin fits at all, new bin must be attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early stream with big items: opening bins is cheaper
        if progress < 0.2 {
            score -= 15.0 * (0.2 - progress) / 0.2;
        }
    }

    // Mild preference for bins with larger residual when many bins open
    score -= 0.05 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let fill = 1.0 - pr / cap; // fill fraction after placement

    // Base: reward tight fits via non-linear post-residual penalty
    let mut score = (pr / cap).powf(1.6) * 40.0;

    // Smooth coupling: residual penalty amplified as stream progresses
    score += (pr / cap).powi(2) * (1.0 + 3.0 * progress) * 30.0;

    // Reward high fill ratio non-linearly
    score -= fill.powf(2.5) * 25.0;

    // Interaction between item size and current residual (big item into full bin good)
    score -= (it / cap) * (br / cap) * 12.0;

    // Last-chance bin bonus (smoothly weighted)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= last_chance * (18.0 + 10.0 * progress);

    // Crowding penalty: many open bins with high mean residual => prefer consolidating
    let crowd = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += crowd * 6.0;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by leftover gap
        score += 4.0 * (pr / cap);
    }

    // New-bin candidate: empty bin gets a progress-dependent handicap so early
    // stream it's cheap, later it's discouraged unless residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress - 8.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // coarse integer-division buckets over the capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect fit -> heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class: leftover smaller than the smallest useful item (10)
        // is unusable dead space -> penalize strongly.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic buckets via integer division on post_residual:
        // bucket 0..=9 dead, 10..=24 tiny, 25..=49 small, 50..=74 medium, 75..=99 large.
        let bucket = post_residual / 25; // 0,1,2,3
        // Larger bucket = more useful leftover = lower score.
        score -= (bucket as f64) * 12.0;

        // Fractional capacity coupling: residual as fraction of capacity.
        let frac = post / cap;
        // Sweet spots: residual near multiples of common item sizes (10,20,25,50)
        // reward residuals that are close to a "harmonic" size divisible by 25 or 10.
        let near25 = (post_residual % 25) as f64;
        let near10 = (post_residual % 10) as f64;
        score -= (25.0 - near25) / 25.0 * 4.0 * frac;
        score -= (10.0 - near10) / 10.0 * 2.0;

        // Lookahead: does the next item fit in the post residual?
        if next_item_size > 0 && next_item_size <= post_residual {
            // Reward leaving room for the next item, more so for tight fits.
            let tightness = (next_item_size as f64) / post;
            score -= 15.0 + 10.0 * tightness;
        } else if next_item_size > 0 {
            // Next item won't fit here: mild penalty, worse if leftover is tiny.
            score += 8.0 * (1.0 - frac);
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor using it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        } else if fitting_bins_count > 1 {
            // With many candidates, prefer the tightest fit (small post residual).
            score += 0.0;
        }

        // New-bin candidate handling: an empty bin has huge residual; make it
        // attractive only when no open bin fits well (large mean residual spread)
        // or the item is large.
        if bin_residual == bin_capacity {
            // Base new-bin score: keep it competitive but not dominant.
            score = cap * 0.35 + item_size as f64 * 0.5;
            // If few fitting bins exist, opening fresh is more attractive.
            if fitting_bins_count == 1 {
                score -= 20.0;
            }
            // Late in the stream, prefer consolidating into open bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 15.0;
            // Large items start fresh bins happily.
            if item_size >= 50 {
                score -= 25.0;
            }
            // If mean residual across open bins is small, open bins are nearly
            // full anyway -> new bin is fine.
            if mean_residual < 15.0 {
                score -= 10.0;
            }
        }

        // Global pressure: many open bins -> discourage spreading, favor tight fits.
        if open_bins_count > 4 {
            score += post * 0.15 * ((open_bins_count as f64).ln());
        }
    }

    // Tight-fit bonus scaled by item size: placing big items tightly is valuable.
    let fill = item_size as f64 / cap;
    score -= fill * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size ~1, but practically tiny gaps)
    // are heavily penalized as unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Dead space relative to typical item scale: gaps below the smallest
    // useful chunk of the current item are doubly punished.
    if post_residual > 0 && (post_residual as f64) < (item_size as f64) * 0.15 {
        score += 12.0;
    }

    // Prefer bins whose residual is tight but not dead: reward closeness
    // of item to residual (good fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Next item fits but leaves a gap; mild reward scaled by tightness.
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        }
    }

    // Open bins pressure: mildly discourage spreading across many bins
    // when mean residual is already high (bins are mostly empty).
    if open_bins_count > 1 && mean_residual > 50.0 && bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate: opening a new bin is only attractive when no
    // open bin gives a decent fit (post residual here is large by
    // definition, base score already high). Add a fixed tax so we prefer
    // reusing a reasonable open bin, unless all fits are terrible.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be slightly greedier about
    // keeping bins tight (fewer chances to recover dead space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fits exactly-ish: strong reward
            let match_quality = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 12.0 * match_quality;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 0.05 * (nxt - post).min(bin_capacity as f64);
        }
        // Perfect 2-item fill bonus
        if (item_size as f64 + nxt) >= bin_residual as f64 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: bins below mean residual are already tight; prefer tightening them
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        if post_f < mean_residual {
            score -= 3.0 * (mean_residual - post_f) / mean_residual;
        } else {
            score += 2.0 * (post_f - mean_residual) / mean_residual;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving large dead space early in stream when many bins open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_f > 0.0 && post_f < 10.0 {
        score -= 8.0 * (1.0 - progress); // nearly-full bins are valuable early
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // neutral baseline slightly worse than a good fit
        score = bin_capacity as f64 * 0.75;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // discourage abandoning the last-chance bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Perfect fit: strong reward (subtract heavily) ---
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Tightness reward: exponential decay of residual.
        let tight = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score -= 25.0 * (1.0 - tight);
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The leftover can host the next item: reward proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover is dead space relative to the next item: penalize.
            let dead = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 18.0 * dead;
        }
        // If the next item fits this bin exactly after placement, big reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize residual, no future concerns.
        score -= 10.0;
    }

    // --- Last-chance bin protection ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that can take the item; strongly prefer using it
        // over opening a new bin.
        score -= 35.0;
    }

    // --- Global state coupling ---
    // Many open bins with high mean residual => prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 * pressure * (open_bins_count as f64).sqrt().min(6.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream when open
        // bins are nearly full on average, or when many bins exist but are
        // too full to be useful (high pressure means little consolidation room).
        let open_attraction = 30.0 * (1.0 - pressure) * (1.0 - progress);
        score += open_attraction;
        // Mild penalty for spawning bins early when few exist.
        if open_bins_count < 3 {
            score += 10.0;
        }
        // If no existing bin fits, opening is unavoidable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // --- Time horizon: as stream progresses, be greedier about tight fits ---
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are too small for the smallest useful item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr * pr / cap;

    // smooth polynomial coupling with stream progress
    let progress_term = (0.5 - progress) * (progress - 1.0); // peaks mid-stream
    score -= 12.0 * progress_term * norm_item * norm_item;

    // reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // penalize dead space relative to mean residual
    score += 0.6 * (pr - mean_residual);

    // lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * norm_next * (1.0 - progress);
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // discourage opening new bins when good fits exist, more so late in stream
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket does it fall in?
    let frac = post_residual as f64 / cap; // 0..1
    // Penalize residuals in "dead zone" classes: too small for typical items (1..100 unknown dist)
    // Buckets via integer division on post_residual (harmonic classes of 100):
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => score -= 12.0,           // near-perfect fit, excellent
        1 => score -= 6.0,            // residual <= 19, likely dead space -> but small residual is fine if unavoidable
        2 => score += 3.0,            // 20-29: awkward class
        3 => score -= 1.0,            // 30-39: fits medium items
        4 => score += 2.0,            // 40-49: awkward
        5 => score -= 2.0,            // 50-59: good class (half-full)
        6 => score += 1.0,
        7 => score -= 1.0,
        8 | 9 => score += 0.5,
        _ => {}
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // chain fit: reward proportional to how well next item fills remainder
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fill;
            // exact modulo harmony: post_residual % next_item_size small => future fit
            let r = post_residual % next_item_size;
            if r == 0 {
                score -= 4.0;
            } else if r <= 10 {
                score -= 2.0;
            } else {
                score += (r as f64) * 0.05;
            }
        } else {
            // next item won't fit here: penalize if this bin was the only fitting one
            score += 3.0;
        }
    } else {
        // last item: just minimize post residual
        score -= 5.0;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish baseline; prefer it only when
    // open bins have poor fits (high mean residual spread).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 2.0;
        }
        // late in stream, favor closing out open bins rather than spawning
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the smallest item size (1..10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual > 0 && post_residual < 25 {
        // Medium-small gaps are partially usable; moderate penalty.
        score += 8.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, new bin becomes attractive:
        // handled implicitly since poor fits accumulate dead-space penalties.
        // Slight discount early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual can't host next item: penalize if it's a small gap.
        if post_residual < 20 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter bins get priority).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Progression: as stream advances, slightly favor reusing bins over opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted potential
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual to mean residual: prefer bins that end below average (tighter packing)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin if lookahead says nothing fits well anyway
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
