pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth polynomial weighting: early stream favors tight fits, late stream tolerates spread
    let poly_weight = 1.0 - 0.5 * progress * progress - 0.25 * progress * (1.0 - progress);
    score *= poly_weight;

    // Dead-space penalty: cubic in normalized post residual, modulated by progress
    score += 60.0 * norm_pr * norm_pr * norm_pr * (1.0 + 0.5 * progress);

    // Reward near-perfect fits with quadratic dip around small residuals
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Mean residual coupling: penalize deviating far from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Last-chance bin: smooth sigmoid-like reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 / (1.0 + (-5.0 * (progress - 0.5)).exp()));
    }

    // Lookahead: reward leaving space for next item (quadratic interaction)
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        score -= 0.3 * (cap - gap) * progress;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small residues are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic residue class: post_residual mod 10 buckets
    let residue_class = post_residual % 10;
    match residue_class {
        0 => score -= 6.0,   // perfectly reusable slots (10/20/30... remainders)
        1 | 9 => score += 3.0, // nearly-dead slivers
        2 | 8 => score += 1.5,
        5 => score -= 2.0,   // half-class slots pair well with ~5 items
        _ => {}
    }

    // Integer-division thresholds: how many "unit-10" items still fit
    let unit_fits = post_residual / 10;
    score -= (unit_fits as f64) * 1.2;

    // Fraction of capacity wasted
    let waste_frac = pr / cap;
    if waste_frac > 0.5 {
        score += 4.0; // large leftover: prefer tighter fills elsewhere
    } else {
        score -= 2.0 * (0.5 - waste_frac); // reward tight fits
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // harmonic match: next item leaves another clean class
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 2.5; // next item won't fit here; this bin becomes dead-ish
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are full-ish
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
        score = cap - 12.0 * (1.0 - progress) - openness.min(6.0);
        if fitting_bins_count == 0 {
            score -= 15.0; // no alternative
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 3.0; // next item also won't fit a fresh bin's logic check
        }
    }

    // Mild tie-break toward bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: penalize adding to a bin when many bins are open,
    // favoring consolidation unless the fit is good.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits into the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If post-residual is smaller than next item but nonzero, mild penalty.
    else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Prefer bins with lower residual than the mean (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it attractive only when current fits are poor
    // (post_residual large means poor fill, so a fresh bin competes).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
