pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual (tight fit), scaled non-linearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste; // quadratic penalty for dead space

    // Lookahead (k=2): reward bins whose post-residual can still host the next item,
    // extra reward if it can host it snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 10.0 * (1.0 - snug);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how far off we are.
        let gap = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 4.0 * gap;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to
    // capacity or open bins are all poor fits (high mean residual mismatch).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a fresh bin is good when the item is big (fresh bin keeps large residual
        // for future items) and we are early/mid stream with many items remaining.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let horizon = (remaining / (total_items.max(1) as f64)).sqrt();
        let openness = 30.0 - 20.0 * item_frac; // big items get cheaper new bins
        score = openness + 8.0 * (1.0 - horizon) + 0.05 * open_bins_count as f64;
        // If an existing bin would leave almost no waste, never open a new one.
        if post_residual <= 3 {
            score += 50.0;
        }
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    } else {
        // Existing-bin placement: prefer bins with residual close to item (perfect fit),
        // penalize bins that are much larger than needed only mildly (post_residual term
        // already handles it); add tiny tie-break favoring fuller bins.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 2.0 * fill_ratio;
    }

    // Global coupling: when many bins are open, slightly discourage spreading items
    // (consolidation), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 6.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 10.0 * (waste / cap) * (waste / cap);
    }

    // Last-chance bonus (smooth, progress-scaled)
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Slight preference for bins deviating from mean residual (diversification)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: mild penalty that grows with progress
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual (small residue is gold)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    }

    // Harmonic classes: dead space in (0,10] is only reusable by tiny items.
    // Penalize residues in awkward modulo bands of capacity fractions.
    if pr > 0 {
        let band = pr % 25; // quarter-capacity harmonic
        if band == 0 {
            score -= 8.0; // residue divisible into quarter classes is useful
        } else if band >= 20 {
            score -= 4.0;
        } else if band <= 5 {
            score += 6.0; // sliver residue: likely dead space
        } else {
            score += 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr && pr - next_item_size <= 5 {
            score -= 18.0;
        } else if next_item_size > pr {
            score += 5.0; // next item won't fit here anyway; keep flexibility
        }
        // Integer-division threshold: residue can host half of next item
        if pr >= (next_item_size + 1) / 2 && pr < next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, only attractive when
    // existing bins are fragmented or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are mostly full or many bins open
        score += 15.0 * fragmentation;
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Opening a fresh bin is bad if a good fit exists elsewhere
        if fitting_bins_count > 0 && pr >= 0 {
            score += 12.0;
        }
    }

    // Slight preference for fuller bins when many bins are open (bin consolidation)
    score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.05;

    // Mean-residual coupling: when mean residual is low, treasure remaining space
    score += (post_residual as f64) * (mean_residual / 200.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Post-residual usable for the lookahead item: reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.1 * next_item_size as f64;
    }

    // Open-bins pressure: penalize placements that leave many bins open.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Progress-based mild adaptation: tighten dead-space penalty late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: bin becomes perfectly full after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Penalize post_residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward if post_residual can still accommodate the next item with slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + (post_residual - next_item_size) as f64 * 0.1;
    }
    // Prefer bins tighter than the mean residual (well-filled bins).
    score -= (mean_residual - post_residual as f64) * 0.3;
    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }
    // Penalize leaving very small unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }
    // Slight preference for opening new bins early in the stream when current bins are loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 1.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: reward near-perfect fills nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Perfect fit is overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize tiny dead space that nothing small can reuse later,
    // but only mildly — dead space below the minimum item size is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual,
    // this placement is doubly valuable (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty scaled
        // by how much it misses by, but only if we leave moderate residue.
        let miss = next_item_size - post_residual;
        if miss <= 30 {
            score += 0.2 * miss as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Scarcity pressure: when few bins can fit the item, prefer using
    // any fitting bin over opening a new one.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are
    // relatively full (low mean residual) or crowded with many bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If existing bins are quite full on average, opening new is fine.
        score -= 0.5 * mean_residual;
        // If many bins are open and mostly full, spreading is reasonable.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * t;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already committed heavily (larger residual
    // used) — reward bins with small residual to consolidate.
    score += 0.3 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Mild global pressure: as the stream progresses, discourage hoarding
    // residual space across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    // Prefer bins whose residual is below mean residual (denser bins).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: squared/cubic residual terms, weighted by stream progress.
    let pr_n = pr / c;
    score += 12.0 * pr_n * pr_n * (1.0 + progress);
    score -= 20.0 * pr_n * pr_n * pr_n * progress;

    // Reward tight fits more strongly as stream progresses.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / c;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * ((nxt - pr) / c);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 { mean_residual / c } else { 1.0 };
        score += 30.0 - 25.0 * congestion * congestion;
        score += 10.0 * progress;
    }

    // Mild dispersion penalty: prefer bins deviating favorably from mean residual.
    score += 3.0 * ((pr - mean_residual) / c).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded,
    // small dead space (<10) heavily penalized since it is unusable.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // dead-space penalty
    } else {
        // Class by decade: prefer residuals that are multiples of 10 or 20
        let r = post_residual;
        if r % 20 == 0 {
            score -= 12.0;
        } else if r % 10 == 0 {
            score -= 6.0;
        }
        // harmonic weight: residual / (residual + item) ratio favors dense packing
        score -= 10.0 * (r as f64) / ((r + item_size) as f64);
    }

    // Exact-fit lookahead: if next item exactly matches post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // If next item fits in post_residual, mild reward (chain-friendly)
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item would NOT fit, residual risks becoming waste: penalize large residuals
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin
        score = 100.0 + post_residual as f64;
        // Open a new bin early in the stream when many bins are open but mean residual is low
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 30.0 * (1.0 - progress);
        }
        // Never open a new bin if a perfect fit exists elsewhere
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 2000.0;
        }
    }

    // Mild preference to fill already-open bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= (item_size as f64) * 2.0;

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open bins pressure: penalize creating many open bins; encourage filling existing ones.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins with residual below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make empty bins attractive only when the fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0 + (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // ---- Aggressive 2-step lookahead: reward exact match with next item ----
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect 2-chain fit: post_residual == next_item_size
        if gap == 0.0 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else {
            // Proximity bonus: closer post_residual to next item is better
            score -= 30.0 / (1.0 + gap);
            // Penalize overshoot that leaves next item unplaceable here
            if (post_residual as f64) < next_item_size as f64 {
                score += 10.0 + gap * 0.25;
            } else {
                // Overshoot: penalize leftover waste after the hypothetical next placement
                score += 0.1 * (gap as f64);
            }
        }
        // If next item is large, slightly prefer bins that keep it feasible
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste, scaled by tightness
        score += 0.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // ---- Relative-to-mean-residual coupling ----
    let dev = post_residual as f64 - mean_residual;
    // Prefer bins tighter than average (pack big items into emptier bins)
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // ---- Last-chance bin before opening a new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is bad early (wasteful) but acceptable late
        // or when this item is huge and would leave a big hole in an existing bin.
        let hole_penalty = 0.4 * post_residual as f64;
        let open_cost = 40.0 * (1.0 - progress) + 10.0;
        score = open_cost + hole_penalty;
        // If next item is tiny, a fresh bin wastes little; slightly favor it
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 5.0;
        }
    }

    // ---- Small general tie-breakers ----
    // Slight preference for filling nearly-full bins (small post_residual) harder later in stream
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    // Mild penalty for proliferating open bins when many already exist
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, non-linear)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress2 = progress * progress;
    let progress3 = progress2 * progress;

    // Normalized post-residual and its polynomial coupling with progress
    let pr = post_residual as f64;
    let pr_n = pr / cap;
    let pr2 = pr_n * pr_n;
    let pr3 = pr2 * pr_n;

    // Smooth non-linear coupling: dead-space penalty grows non-linearly with progress
    score += 30.0 * (pr2 * progress + pr3 * progress2);

    // Perfect-fit reward, modulated smoothly by progress
    if post_residual == 0 {
        score -= 25.0 * (1.0 + progress);
    } else if post_residual < 5 {
        score -= 12.0 * (0.5 + progress);
    }

    // Last-chance bin: reward more strongly as stream progresses
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress2);
    }

    // Interaction with mean residual: penalize bins far from the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Lookahead coupling: reward residual that can smoothly accommodate next item
    if next_item_size > 0 {
        let fit_next = pr >= next_item_size as f64;
        if fit_next {
            score -= 8.0 * (1.0 - progress3);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild preference for tighter bins overall
    score += 0.1 * (item_size as f64 / cap) * (1.0 + progress);

    // New-bin candidate: penalize opening new bins unless residual is truly large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it is small but nonzero.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Dead space below 10 is nearly unusable (items >= 1, but typical sizes larger);
        // penalize the "unfillable" band harshly, scaled by how tight it is.
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64 * 2.0;
        } else if pr < 25 {
            score += 8.0;
        }
        // Modulo-10 harmonic class: residuals that are multiples of 10 align with
        // common item-size quantiles and are more reusable.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: reward if the next item fits the post-residual (chaining),
    // penalize if the next item is stranded by our choice.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (pr as f64 - next_item_size as f64).min(20.0) * 0.5;
        } else {
            // Next item won't fit here; mildly prefer leaving coherent space anyway.
            score += 2.0;
            // If next item fits only in this bin currently, keep it usable.
            if next_item_size <= bin_residual && pr < next_item_size {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large raw score (post_residual = capacity).
    // Only let it win when existing residuals are poor: give empty bins a calibrated handicap
    // so open bins with decent fits beat it, but very fragmented states don't.
    if bin_residual == bin_capacity {
        score -= 15.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open with scattered residuals, prefer consolidation instead.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Existing bin: slight preference for bins tighter than the mean (better packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild global pressure: when few bins fit the item, push toward whichever fits best.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward bins whose residual tightly matches the item (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Lookahead: if the next item could use this post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: apply pressure plus a fixed hesitation.
        score += pressure * 2.0 + 8.0;
        // But if no existing bin fits well, allow opening a new one.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled against capacity.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: reward if next item fits exactly/into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this placement sets up an exact fit next step.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: dead space penalty grows with gap.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // Relative-to-mean coupling: a bin much tighter than average is precious,
    // avoid wasting it; a bin looser than average is a good dumping ground.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): penalize unless it's genuinely better.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if no good chaining exists,
        // i.e. when the item is large and would leave a big awkward residual
        // anywhere. Mild penalty so existing tight fits win.
        score += 25.0;
        // But if the item is huge, a fresh bin is actually ideal.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in wasted space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space.
            score += 8.0;
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0;
    }
    if open_bins_count > 8 {
        score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of empty bin is large, so base score already high).
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 && post_residual < 50 {
            score += 20.0; // an open bin leaves decent residual; don't open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && item_size >= 60 {
            score -= 35.0; // big item + big next item: fresh bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, superlinearly (quartic-smooth).
    let mut score = pr as f64 + 30.0 * x * x * (1.0 + x * x);

    // Smooth progress coupling: late in the stream, waste matters more.
    score += 60.0 * x * x * progress;

    // Interaction of post residual with mean residual: prefer bins whose
    // post residual deviates smoothly from the fleet mean (consolidation).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Next-item lookahead: reward post residual that smoothly matches next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        let tight = 1.0 / (1.0 + diff * diff / (cap * cap));
        score -= 25.0 * tight;
        // Penalize post residual that is too small to ever be useful again.
        score += 10.0 * (1.0 - tight) * x;
    }

    // Last-chance bonus: only fitting bin -> strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    // New-bin candidate: smooth sigmoid gate on residual fullness of open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are fairly full
        // on average or the item is large relative to typical residual.
        let fullness = 1.0 - mean_residual / cap;
        let urgency = 1.0 / (1.0 + (-8.0 * (fullness - 0.5)).exp());
        score += 55.0 * urgency - 25.0 * (1.0 - urgency);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction classes: prefer bins whose post_residual falls in "usable" harmonic classes.
    // Class boundaries at multiples of capacity/4 (25, 50, 75): residual near these is more reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Harmonic class of post_residual via integer division thresholds
    let class = post_residual / quarter; // 0..4
    match class {
        0 => score -= 12.0,          // tiny leftover: near-perfect fit, great
        1 => score -= 4.0,           // leftover in [25,50): still very usable
        2 => score -= 0.0,           // [50,75): average
        3 => score += 6.0,           // [75,100): large waste, penalize
        _ => score += 10.0,          // nearly empty bin used for small item: wasteful
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common item sizes
    // (or near multiples) pair well with future items.
    for m in [10u32, 20, 25, 50] {
        let r = post_residual % m;
        let d = r.min(m - r) as f64;
        score += d * 0.15; // penalize distance from harmonic multiples
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0; // perfect two-item chain
        } else if slack < quarter {
            score -= 10.0;
        } else {
            score -= (quarter as f64 - slack.min(quarter as f64)) * 0.1;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0; // next item can't use this bin's leftover
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream or with many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 15.0 * progress - (open_bins_count.min(10) as f64) * 0.5;
        // if next item is large and current item small, opening a fresh bin is fine
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mean residual context: if this bin's residual is far below mean, it's a "junk" bin;
    // filling junk bins is good (consolidate dead space).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.2; // prefer bins with less residual than average
    } else {
        score += (-diff) * 0.05;
    }

    // Mild preference for tighter fits overall
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space only matters if nothing (incl. lookahead) can use it
    if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // Open-bin pressure: fewer bins favored when many open
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strong reward to use it instead of opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer reusing existing bins unless residual is tiny
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    }

    // Lookahead synergy: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.35;
    }
    // Dead space: next item cannot fit into what remains.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize residuals that are too small to ever be useful for typical items.
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Prefer opening new bins only when no open bin offers a good fit:
    // make the new-bin candidate less attractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 - 0.1 * mean_residual;
    }

    // Late in the stream, favor consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small dead space that can't fit typical items is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits into post_residual (pairing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty if we leave awkward space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or few bins are open. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 10;
        // Base penalty for opening a new bin; reduced when many open bins are
        // fragmented (high mean residual) or fit is terrible.
        let mut new_bin_penalty = 12.0;
        if mean_residual > 30.0 {
            new_bin_penalty -= 4.0;
        }
        if poor_fit {
            new_bin_penalty -= 20.0;
        }
        // Early in stream, keep bins open (consolidate); late, allow spreading.
        new_bin_penalty += 6.0 * (1.0 - progress);
        if open_bins_count == 0 {
            new_bin_penalty = -100.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins among open bins.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial coupling to stream progress.
    let pr_norm = pr / cap;
    let coupling = pr_norm * (1.0 + 0.9 * progress * progress) - 0.55 * progress * pr_norm * pr_norm;
    score += 30.0 * coupling;

    // Penalize residual that cannot plausibly hold the next item (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += 0.35 * gap * gap;
        } else {
            score -= 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Prefer bins with residuals near the mean (smooth deviation penalty).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Mild reward for consolidating into fewer bins.
    score -= 0.4 * open_bins_count as f64;

    // New-bin candidate: prefer it only when post-residual would be very large
    // (i.e., item is small) and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0 - 55.0 * pr_norm * pr_norm - 25.0 * progress;
        score += new_bin_penalty.max(-20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets capture "usable" vs "dead" space.
    let pr = post_residual;
    let harmonic_class = pr % 10;
    // Residuals that are multiples of 10 pair well with the 10..80 size grid.
    if harmonic_class == 0 && pr > 0 {
        score -= 6.0; // perfectly aligned leftover
    } else if harmonic_class <= 3 && pr > 0 {
        score += 3.0; // sliver: near-dead space
    } else if harmonic_class >= 7 {
        score += 1.5; // awkward large-but-unusable chunk
    }

    // Integer-division thresholds on post_residual: which next-item classes fit.
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size;
        if fits_next {
            // Reward proportional to how tightly the next item would fill the bin.
            let tightness = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * tightness;
        } else {
            // Penalize bins that strand the lookahead item.
            score += 8.0;
            // Extra penalty if the stranded next item is large (hard to place elsewhere).
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should win only when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Cheaper to open new bins early in the stream / when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        score -= (open_bins_count as f64).recip() * 5.0;
        // If mean residual across open bins is small, new bin is justified.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
        // If no open bin fits well (post_residual would be tiny), prefer new bin.
        if bin_residual >= item_size && item_size as f64 >= 0.8 * bin_residual as f64 && bin_residual != bin_capacity {
            score -= 0.0; // placeholder guard (new bin has full residual anyway)
        }
    } else {
        // Reward filling bins tightly: small post_residual is good (already base score).
        // Extra reward when the bin becomes exactly "harmonically" full.
        if pr == 0 {
            score -= 20.0;
        }
        // Penalize leaving a residual just below the smallest item size (dead space).
        if pr > 0 && pr < 10 {
            score += 10.0;
        }
        // Mild preference for bins whose residual is large when many bins are open
        // (consolidation pressure), modulated by mean residual.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score -= 4.0 * dev;
    }

    // Coupling: if next item exactly matches post_residual, big reward (perfect chain).
    if next_item_size > 0 && pr == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead gap: hard penalty scaled by gap smallness.
            score += (10.0 - post_residual as f64) * 12.0;
        } else if post_residual < item_size.min(80) {
            // Gap too small for the current item size class: moderate penalty.
            score += 8.0;
        }
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor compacting
    // into existing bins when many are open.
    score += (open_bins_count as f64) * 0.35;

    // Prefer bins with residual below the mean (pack fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize opening a new bin, more so early in the stream and when
    // the current item leaves a large, useful gap that an open bin could serve.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        // If the post-residual of this placement is large and usable by the next
        // item, opening a new bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // But if no open bin can fit the item at all, new bin is forced anyway;
        // soften the penalty so it is chosen.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that the next item almost fits but cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect 2-step match bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (fuller bins)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins fit, unless residual would be tiny
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible = if next_item_size > 0 { next_item_size } else { 0 };
        let waste = (bin_capacity as f64 - item_size as f64) - best_possible as f64;
        if waste > 0.0 {
            score += 0.4 * waste;
        }
        // New bin more attractive late in stream
        score += 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for opening new bins when many are open (diversity control)
    if bin_residual == bin_capacity {
        score -= 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tight * tight;

    // Lookahead: penalize if next item cannot fit in the post residual (dead-end risk).
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 0.35 * next_item_size as f64 * (1.0 - post_residual as f64 / cap);
    }
    // Lookahead reward: if next item exactly fits post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 0.25 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to keep diversity of residuals.
        score += 2.0 * (fitting_bins_count as f64).min(8.0);
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as stream progresses (commitment cheaper early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * (1.0 - 0.5 * progress);
        // If the item leaves a "perfect" residual for the next item, opening is attractive.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
        // If no open bin fits, this is forced anyway; soften cost.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global-state coupling: prefer filling bins when mean residual is high (fragmentation risk).
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Prefer placing large items into already-open bins early (avoid many half-empty bins).
    score += 0.1 * item_size as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = fitting_bins_count as f64;

    // Base: post-residual (waste), with non-linear shrink of small residuals
    let mut score = pr
        - 24.0 * (1.0 - (pr / cap).powi(2)) * (pr / cap)
        + 10.0 * (pr / cap).powi(4);

    // Stream-progress coupling: early stream tolerates slack, late stream punishes it
    score += 18.0 * (pr / cap) * (1.0 - progress).powi(2);
    score -= 14.0 * (pr / cap) * progress.powi(2);

    // Mean-residual interaction: prefer bins whose residual deviates from mean
    score += 6.0 * ((bin_residual as f64 - mean_residual) / cap).powi(2);

    // Last-chance bonus (smooth): fewer fitting bins -> stronger reward
    score -= 20.0 / (fit * (fit + 1.0));

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 8.0 * ((-gap) / cap);
        }
    }

    // Slight penalty for proliferation of open bins
    score += 0.4 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it splits into capacity fractions.
    let q = post_residual / (bin_capacity / 4); // 0..=4 harmonic quarter class
    match q {
        0 => score -= 60.0,                     // near-perfect fit
        1 => score -= 15.0,                     // good fill
        2 => score += 0.0,                      // neutral
        3 => score += 20.0,                     // poor: >50 dead space
        _ => {}
    }

    // Dead-space penalty via modulo: residuals that waste a large chunk
    // of the capacity (post_residual % 25 in the awkward band) are risky.
    let awkward = post_residual % 25;
    if awkward >= 10 && awkward <= 20 {
        score += 12.0;
    }

    // Integer-division threshold on next_item_size vs post_residual:
    // if the lookahead item fits exactly, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // lookahead leaves a tiny unusable sliver -> discourage
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 && nxt_post > 0 {
                score += 18.0;
            }
        } else {
            // lookahead cannot use this bin's remainder: penalize large leftovers
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large (would leave little residual anyway) or no bin fits well.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        if fill_fraction > 0.7 {
            score -= 55.0; // big item: fresh bin is efficient
        } else if fitting_bins_count > 1 {
            score += 70.0; // discourage abandoning usable open bins
        } else {
            score -= 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight stream-position adaptation: later in stream, prefer tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Tie-break toward bins with low mean residual spread (compactness).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 {
        score -= 60.0; // perfect (or near-perfect) fill is excellent
    } else if post_residual < 20 {
        score -= 25.0; // very tight residual still good
    } else if post_residual < 35 {
        score += 8.0;  // moderate dead space
    } else {
        score += 20.0; // large leftover space: wasteful placement
    }

    // Dead space is worse late in the stream (fewer chances to reuse it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual >= 10 && post_residual < 20 {
        score -= 15.0 * progress;
    }

    // Reward exact-fit of the lookahead item into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        if snug < 10.0 {
            score -= 18.0;
        } else {
            score += snug * 0.3;
        }
    }

    // Last fitting bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new space.
    score += open_bins_count as f64 * 1.5;

    // Penalize bins far from the mean residual (fragmentation signal).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.4;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin leaves big dead space) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit && open_bins_count > 0 {
            score -= 12.0;
        } else if open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual,
    // this bin remains useful; reward proportionally to how well it matches.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 4.0;
        if slack == 0.0 {
            score -= 250.0; // perfect 2-item packing chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space left behind.
        let dead = post_residual as f64;
        score += dead * 0.5;
        // Extra penalty if next item is small (we squandered space on it).
        if (next_item_size as f64) < dead {
            score += (dead - next_item_size as f64) * 0.8;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Penalize deviating from the mean residual: keep bin pool homogeneous.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are poor.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual < item_size as f64) as i32;
        let big_item = (item_size > 60) as i32;
        let mut penalty = 150.0;
        if pressure == 1 {
            penalty -= 100.0;
        }
        if big_item == 1 && mean_residual < item_size as f64 {
            penalty -= 120.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < mean_residual {
            penalty -= 60.0;
        }
        score += penalty;
    }

    // Late in the stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Penalize large dead space relative to smallest plausible item (unknown dist: assume ~1).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / 100.0).powi(2) * (200.0 + 400.0 * progress);

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    } else if fitting_bins_count >= 2 {
        // Mild penalty when many alternatives exist; prefer tightest fit anyway.
        score += fitting_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / 100.0).max(0.0);
        } else {
            // Penalize leaving residual too small for the next item (dead space risk).
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64 - 3.0) * 5.0;
    }
    if mean_residual > 50.0 {
        score -= (mean_residual - 50.0) * 1.5;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early when
    // open bins exist and item could fit elsewhere; less so late in the stream.
    if bin_residual == bin_capacity {
        let open_penalty = if open_bins_count == 0 { 0.0 } else { 120.0 + 60.0 * (1.0 - progress) };
        score += open_penalty;
        // If next item is huge, opening fresh bin may be fine.
        if next_item_size > 70 {
            score -= 60.0;
        }
    }

    // Favor bins that are already somewhat loaded (keep bins concentrated).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = pr * pr * (0.5 + 1.5 * progress);
    score += 20.0 * coupling;

    // Reward tight fits, stronger late in the stream
    let tight = (pr * (1.0 - pr)) * 4.0; // peaks at pr=0.5, zero at extremes
    score -= 8.0 * tight * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let waste = if (post_residual as u32) < next_item_size { 1.0 } else { 0.0 };
        score += 6.0 * waste * pr;
    } else if next_item_size > 0 {
        score -= 4.0 * (next_item_size as f64 / bin_capacity as f64) * (1.0 - pr);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - pr);
    }

    // Prefer bins below mean residual (larger residuals get penalized smoothly)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr;

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress) - 8.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (10/20/25/50) are "usable" classes; reward them.
    let usable: [u32; 6] = [0, 10, 20, 25, 30, 50];
    let mut class_bonus = 0.0;
    for &u in usable.iter() {
        if post_residual % u == 0 {
            class_bonus = 12.0;
            if u >= 25 { class_bonus += 6.0; }
            break;
        }
    }
    score -= class_bonus;

    // Dead-space penalty: tiny residuals that no item (1..=100, min size 1)
    // can usefully fill relative to stream position.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (1.5 + progress);
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let chain = post_residual % next_item_size;
            score -= (chain == 0) as i32 as f64 * 10.0;
            score += (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: prefer reusing open bins whose residual is
    // small; penalize opening a new bin when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        // brand-new bin: base score is capacity; make it attractive only if
        // the current item is large relative to capacity or many bins are open.
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        score -= big_item_bonus;
        score += open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin leaves room for the next item too
        }
    } else {
        // Tight fits in existing bins: reward small post_residual relative to mean.
        if (mean_residual > 0.0) && (post_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Integer-division threshold: post_residual bucketed by quarters of capacity.
        let q = post_residual / (bin_capacity / 4);
        score -= q as f64 * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // A gap is "dead" if it cannot fit the lookahead item (or any plausible item).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect fit for the next item: strong reward.
            score -= 25.0;
        }
    }

    // Dead space relative to the smallest plausible item (items >= 1, but reward
    // gaps that remain broadly reusable).
    if post_residual > 0 && post_residual < 12 {
        score += 10.0 * (1.0 - progress * 0.5);
    }

    // Tight fit reward: leaving near-zero residual means the bin was well used.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect-fill pressure: prefer bins whose residual exactly matched the item.
    if bin_residual == item_size {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // encouraging consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are "emptier" than
    // average; filling them is slightly less urgent than filling above-average ones.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good fit exists (large dead space
    // would otherwise be created). Fresh bin has full residual.
    if bin_residual == bin_capacity {
        // Neutral base; the dead-space penalties above make bad fits lose to a new bin.
        score += 2.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item exactly or near-exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let match_bonus = 60.0 * (1.0 - gap / bin_capacity as f64);
        score -= match_bonus;
        // Perfect chain fit: item fills bin, next item fills remainder.
        if gap == 0.0 {
            score -= 80.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual is dead space relative to the lookahead item.
        // Penalize proportionally, but less if post_residual is tiny.
        let dead = post_residual as f64;
        score += 0.35 * dead;
        if dead < 5.0 {
            score += 15.0; // nearly-full bin: excellent
        }
    }

    // Compare against mean residual: prefer bins that are more filled
    // than average (below-mean residual is good).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; relax for large items late in stream.
        let new_bin_penalty = 40.0 - 25.0 * large_item - 10.0 * progress;
        score += new_bin_penalty.max(5.0);
        // If next item is huge and current bin residual is small, new bin
        // preserves space for it.
        if next_item_size > 50 && bin_residual < next_item_size + 10 {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving awkward mid-range dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // small leftovers are nearly perfect fills
    }

    // Slight consolidation pressure when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity (non-linear)
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead_frac * dead_frac;
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize wasting space
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // Opening a new bin is attractive when next item is large and would waste space here
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Late in the stream: prefer tight fits, discourage new bins
    score += 15.0 * progress * (open_bins_count as f64);

    // Small penalty proportional to item size to prefer bins where item is a large fraction
    score -= 0.2 * item_size as f64 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post_residual (tight fit), non-linearly shaped.
    let mut score = post;

    // Quadratic coupling of post_residual with stream progress:
    // dead space becomes more costly as the stream advances.
    let dead = post / cap;
    score += 30.0 * dead * dead * (0.5 + progress);

    // Reward excellent fits (post_residual small relative to capacity).
    let tight = 1.0 - dead;
    score -= 12.0 * tight * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if nxt <= post {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bin: penalize opening new bins when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: make it mildly attractive only when existing residuals
    // are poor (mean residual small) or the item is large.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post) / cap; // negative if mean residual < cap
        score -= 5.0 + 10.0 * (1.0 - item_size as f64 / cap) * mean_gap.max(-1.0);
        score -= 3.0 * progress;
    }

    // Mild penalty for spreading across many open bins with high mean residual.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size: heavy penalty
        score += 45.0;
    } else {
        // Harmonic class bonus: residuals that align with common item granularity
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: does this bin remain useful for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin when open bins can fit the item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 20.0 + mean_residual * 0.4;
        // Early in the stream, fewer open bins exist; opening bins is cheaper then
        new_bin_penalty *= (1.0 - 0.3 * progress);
        score += new_bin_penalty;
    }

    // Slight preference for consolidating into bins with lower mean residual (tighter packing)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), already handled by base term.

    // Strict dead-space avoidance: a leftover gap that is too small to be
    // useful is pure waste. Penalize tiny-but-nonzero post residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, strongly discourage
    // opening yet another bin (the new-bin candidate has the largest
    // post_residual, so an explicit penalty on the fresh-bin case plus a
    // mild global open-bin term keeps consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to how many bins
        // already fit the item elsewhere.
        score += 30.0 + (open_bins_count as f64) * 2.0 + progress * 20.0;
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Allow a new bin when the item is huge and would leave a very
        // unusable gap in any existing bin anyway.
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid wasting it
    // on a placement that leaves a large gap; but if the fit is tight, favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 15 {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead: if the next item would fit snugly into the post residual,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        }
    }

    // Mild coupling with mean residual: prefer bins that are already below
    // average fullness (consume slack where it is abundant).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: residual after this placement exactly fits next item
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        // Bonus if next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: post residual too small for the next item
        score += 12.0 + 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to current residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Compare post_residual to mean residual: avoid creating outliers of wasted space
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline plus pressure from existing open bins
        score += 8.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Lookahead: opening a new bin is good if next item also large
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (post_residual as f64 + 1.0).ln();

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.4;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins compete: prefer the one that wastes least.
        score += (fitting_bins_count as f64 - 1.0).ln() * 2.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward residuals.
            score += 4.0;
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    } else {
        // Last item: minimize waste aggressively.
        score -= 10.0;
    }

    // Global state coupling: when many bins are open, prefer consolidation into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).ln();
    score += 0.8 * consolidation * (0.5 + progress);

    // Prefer bins below mean residual early (spread load), above mean residual late.
    let res_diff = bin_residual as f64 - mean_residual;
    score += if progress < 0.5 { 0.3 * res_diff } else { -0.3 * res_diff };

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 8.0 * (1.0 - tightness) };
        score += desperation - 5.0 * progress;
    }

    // Mild penalty for very loose fits overall.
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits, with a non-linear (quartic) penalty on residual
    let mut score = 2.0 * norm_pr * norm_pr * norm_pr * norm_pr + pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; late, squeeze harder
    let coupling = (1.0 - progress) * norm_pr * (1.0 - norm_pr) * 30.0;
    score += coupling;

    // Reward filling more than half the bin, smoothly
    score -= 12.0 * norm_item * (1.0 - norm_item);

    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tightness = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 8.0 * fits * tightness * tightness;
    } else {
        // last item: strongly prefer minimal residual
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: reward using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    let mean_norm = mean_residual / cap;
    score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * mean_norm * mean_norm;

    // New-bin candidate: make it unattractive unless residual would be huge waste elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "useful" for typical items
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_ratio = 1.0 - pr / cap;

    // Reward high fill ratio non-linearly
    score -= 40.0 * fill_ratio * fill_ratio;

    // Harmonic classes: post_residual divisible by small harmonics is more reusable
    let p = post_residual;
    if p == 0 {
        score -= 25.0; // perfect fit
    } else {
        let mut harmony = 0.0;
        for d in [5u32, 10, 20, 25, 50].iter() {
            if p % d == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
        // Penalize awkward dead space: tiny unusable remainders
        if p < 10 {
            score += 18.0;
        } else if p < 20 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0;
            } else {
                score += (slack as f64) * 0.15;
            }
        } else {
            // next item cannot fit here regardless; mild penalty scaled by overshoot
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * (1.0 - progress) - 0.1 * (open_bins_count as f64);
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 35.0; // big item with no home: new bin is fine
        }
    }

    // Mean residual context: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - pr) * 0.2;

    // Integer division threshold on item size: large items prefer tightest fits
    if item_size / 20 >= 3 {
        score += 0.05 * (pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum item size (1..10) are nearly worthless -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space for the known next item
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure, but allow
        // when current bin would leave bad dead space.
        score += 25.0 + 10.0 * pressure;
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0; // opening a bin beats creating dead space
        }
    } else {
        score -= 3.0 * pressure.min(6.0);
    }

    // Prefer bins with below-average residual (consolidate emptier bins usage).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    // (next item will fit perfectly), or where next item still fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after hypothetical placement
            let after_next = post_residual - next_item_size;
            score -= 50.0 - 0.5 * after_next as f64;
        } else {
            // next item won't fit here: penalize small unusable dead space
            score += 0.3 * (nxt - post_residual as f64);
        }
    }

    // Penalize small but nonzero dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item, or when mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0;
        score -= 0.5 * mean_residual; // opening a bin more attractive when mean residual low
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < item_size as f64 {
            // pair item + next item in a fresh bin when they complement
            if item_size + next_item_size <= bin_capacity {
                score -= 200.0;
            }
        }
        let _ = progress;
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic decay of score as post_residual shrinks.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can chain into this bin's post-residual,
    // penalize if this placement blocks a better next-item fit.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        }
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        }
        if next_item_size > bin_residual && next_item_size <= post_residual {
            score -= 30.0; // next item only fits here after this placement
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current
    // residuals are large/fragmented or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 55.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        open_cost += progress * 30.0;
        // If mean residual is small (bins nearly full), opening is more justified.
        open_cost -= (mean_residual / bin_capacity as f64) * 40.0;
        // Very fragmented state favors opening fresh space.
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            open_cost -= 20.0;
        }
        let _ = fragmentation;
        score += open_cost;
    } else {
        // Mild penalty for very poor fits into open bins (dead space < 5).
        if post_residual > 0 && post_residual < 5 {
            score -= 10.0;
        }
        // Prefer bins whose residual is close to the item (best-fit sharpening).
        let gap = (bin_residual as f64 - item_size as f64);
        score += gap * 0.15;
    }

    // Slight preference for fuller bins overall (global balance).
    score -= (1.0 - (bin_residual as f64 / bin_capacity as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Polynomial shaping of normalized residual: penalize both tiny and large leftovers
    let shape = 4.0 * norm_post * (1.0 - norm_post);
    score += (1.0 - shape) * cap * (0.3 + 0.4 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - post) * (0.2 + 0.5 * progress);

    // Last-chance bonus: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= cap * (1.2 + 0.6 * progress);
    }

    // Penalize bins far from mean residual (fragmentation signal), scaled by open bins
    let dev = (post - mean_residual).abs();
    score += dev * (0.15 + 0.1 * (open_bins_count as f64).ln().max(0.0));

    // Lookahead coupling: favor leaving space usable by the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let usable = if post >= n { post - n } else { post };
        score -= usable * 0.25;
        score += (n - post).max(0.0) * 0.15;
    }

    // Mild penalty for opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.4 * (1.0 - progress));
        if fitting_bins_count > 0 {
            score += cap * 0.5 * (fitting_bins_count as f64).min(3.0) / 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class decomposition of post_residual ----
    // Class items into capacity fractions; dead space in low harmonic classes
    // is more exploitable, so penalize it less.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes of post_residual (harmonic bands of C/8)
    let band = post_residual % (bin_capacity / 8).max(1); // 0..12
    let band_penalty = match band {
        0 => -8.0,                       // perfectly divisible: highly reusable
        1 | 2 => -4.0,                   // near-divisible residuals pack well
        3 | 4 | 5 => 0.0,
        6 | 7 => 3.0,                    // awkward slivers
        _ => 5.0,                        // tiny dead space (< C/16)
    };
    score += band_penalty;

    // Integer-division threshold: post_residual >= C/2 is prime territory
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 6.0; // small hole, likely wasted
    }

    // ---- Lookahead coupling (harmonic match with next item) ----
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // Next item fits exactly in this residual: strong reward
            let exact = (pr - nx).abs() < 1.0;
            if exact {
                score -= 25.0;
            } else {
                // reward proportional to fill fraction of the leftover
                score -= 12.0 * (nx / pr.max(1.0));
            }
            // modulo harmony: next item keeps residual in a good class
            let new_band = (post_residual - next_item_size) % (bin_capacity / 8).max(1);
            if new_band == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual at all
            score += 5.0 + 0.1 * (nx - pr);
        }
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0; // only bin that fits: strongly prefer using it
    } else if fitting_bins_count > 1 {
        // tightness competition: prefer the tightest fit via post_residual (already core)
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when it will be well-used,
        // but penalize when existing bins can absorb the item acceptably.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_load = (item_size as f64) / cap; // fraction filled on open
        score = 0.6 * cap - 40.0 * new_bin_load - 20.0 * progress;
        if post_residual < bin_capacity / 4 {
            score += 15.0; // opening a bin that will end mostly empty
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin serves the lookahead too
        }
    }

    // ---- Global context nudges ----
    let mr = if open_bins_count > 0 { mean_residual } else { 0.0 };
    // If mean residual is large, discourage spreading; prefer filling tight bins
    score += 0.05 * mr;

    // Slight preference to keep bin count low as stream matures
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty for awkward mid-range gaps unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening yet another bin.
    let open_pressure = open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive if it avoids
        // leaving bad gaps in existing bins.
        score += 30.0 + open_pressure;
        // If the next item could combine well with current item in a fresh bin, ease opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward fitting the lookahead item too (chain fits).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual {
            score += 5.0;
        }
        // Slight preference for bins with lower residual (tighter bins first).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Stream maturity: as the stream progresses, discourage opening new bins further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // Perfect closure bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 8.0; // tiny dead space is bad
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter bins)
    score -= 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        score += 20.0 + poor_fit * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Late-stream consolidation: keep bin count low as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: fraction of residual consumed by this item
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };

    // Reward tight fits (near-perfect packing) more strongly as the stream progresses
    let tightness_reward = fit_ratio * fit_ratio * (20.0 + 40.0 * progress);
    score -= tightness_reward;

    // Penalize leaving dead space that is too small to be useful for typical items.
    // Dead space in (0, 10) is nearly unusable; larger post-residuals are more flexible.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress); // early dead space is worse (long horizon ahead)
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this bin;
    // if the next item is bigger than post-residual but smaller than bin_residual,
    // placing here may strand the next item -> penalize.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            // chain fit: reward proportionally to how snugly next item fills the remainder
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_fit * (1.0 + progress);
        } else if (bin_residual as f64) >= next_item_size as f64 && post_residual > 0 {
            // this placement wastes space the next item could have used
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer bins with smaller residual (best-fit flavor)
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Global state coupling: when many bins are open with large mean residual,
    // discourage opening new bins implicitly by favoring reuse of scattered space.
    if open_bins_count > 1 {
        let reuse_bonus = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 8.0 * reuse_bonus.max(0.0);
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless current item leaves a very flexible remainder
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 12.0 + 18.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        score += new_bin_penalty;
        // but if item is large and leaves balanced residual, soften the penalty
        if item_size >= 50 && post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Mild non-linear shaping of post_residual: prefer remainders that are "round"
    // multiples of common small sizes (10/20), which are easier to fill later.
    let pr = post_residual;
    if pr >= 10 && pr % 10 == 0 {
        score -= 3.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let tight = 1.0 - pr / cap; // tightness of fit (0 = loose, 1 = perfect)
    let poly = tight * tight * (3.0 - 2.0 * tight); // smoothstep coupling
    score -= poly * (0.6 + 0.8 * progress) * 12.0;

    // Penalize dead space that is too small to be useful later, smoothly.
    let dead = (1.0 - pr / cap).exp();
    score += dead * dead * 5.0;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * 8.0;
        } else {
            score += (nx - pr) / cap * 10.0;
        }
    }

    // Mild pressure toward consolidation as stream progresses.
    score += (pr / cap - mean_residual / cap).abs() * (2.0 + 4.0 * progress);

    // Slight bias against opening new bins early.
    score += progress * 3.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 classes) ---
    // Residuals divisible by 10 are "harmonic" with typical item sizes; keep them.
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_bonus = match class {
        0 => 6.0,                          // perfectly harmonic residual: strongly reward
        5 => 3.0,                          // half-harmonic: mild reward
        2 | 4 | 6 | 8 => 0.5,              // even but non-harmonic: neutral-ish
        _ => -2.0,                         // odd non-harmonic: penalize (dead space risk)
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: how many size-10 quanta remain
    let quanta = pr / 10;
    if quanta == 0 {
        // Perfect fit — huge reward
        score -= 40.0;
    } else if quanta <= 2 {
        // Small residual: good if it can still host a small item later
        score -= 8.0;
    } else if quanta >= 7 {
        // Large residual left: wasteful placement, mild penalty
        score += 5.0;
    }

    // --- Lookahead coupling: does post_residual fit the next item exactly / at all? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                // Next item would land harmonically: strong reward
                score -= 15.0;
            } else {
                score -= 5.0;
            }
            if next_item_size == pr {
                // Perfect two-item chain
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: residual becomes dead unless reusable
            score += 10.0;
        }
    } else {
        // Last item of the stream: minimize residual outright
        score -= 30.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor it ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- New-bin candidate handling: penalize opening a new bin unless current
    //     residuals are all badly fragmented ---
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline is its full residual; adjust by stream state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // If open bins are fragmented (low mean residual), opening a new bin is fine;
        // otherwise discourage it so we fill existing bins first.
        score += 12.0 * (1.0 - fragmentation) + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 18.0; // extra penalty: some open bin fits, prefer it over new bin
        }
        // Harmonic check: item_size itself harmonic with capacity
        if bin_capacity % item_size == 0 {
            score -= 10.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual deviates below mean
    //     (tighter bins get filled first, keeping large-residual bins flexible) ---
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // --- Mild preference for filling bins when many are open ---
    score -= 0.5 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // Small non-linear shaping on residual fraction
    let frac = pr as f64 / bin_capacity as f64;
    score += 10.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later.
    let dead_threshold: f64 = 9.0; // items >= 10 in classic streams, but sizes 1..100 allowed
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual == item_size {
        // symmetrical fill (bin exactly half used) - mild reward
        score -= 8.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (open_bins_count as f64 * 2.5 + 10.0);

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual can host the next item exactly/tightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where next item leaves minimal new dead space.
            score -= 25.0 - slack.min(30.0);
            // Perfect chain (post_residual == next_item_size) is a jackpot.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item cannot follow: penalize proportionally to the orphaned space.
            let orphan = next_item_size as f64 - post_residual as f64;
            score += 12.0 + orphan.min(40.0);
        }
    } else {
        // Last item: simply minimize post residual.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, smallest item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early stream: be greedy about consolidation; late stream: more open bins acceptable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fits are all bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if lookahead chain works perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // If no open bin fits (this call is only option), effectively neutral.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver under min item size
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't chain here; mild penalty proportional to waste
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize new bins when existing bins are fairly full or few fit.
        score += 45.0 + 30.0 * (1.0 - progress) + 20.0 * avg_fit_quality + 2.0 * open_bins_count as f64;
        // If next item is large and no bin chains, opening fresh is slightly better.
        if next_item_size >= 60 && post_residual == bin_capacity as u32 - item_size {
            score -= 25.0;
        }
    }

    // Prefer bins below mean residual (balances load, keeps mid-size bins usable).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover space, but with a non-linear (quartic) dead-space curve.
    let mut score = norm_pr.powi(4) * 40.0;

    // Smooth polynomial coupling between post-residual and stream progress:
    // early in the stream, leftover space is cheap; later, it becomes costly.
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 6.0
                 - norm_pr * progress * 10.0
                 + norm_pr * norm_item * 4.0;
    score += coupling;

    // Reward tight fits: exact fill strongly favored via smooth term.
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Penalize opening a new bin when existing bins could fit, scaled by progress.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 5.0 + 15.0 * (1.0 - progress);
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= norm_item * 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead: if next item could use the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_ratio = if pr > 0.0 { nx / pr } else { 2.0 };
        if fit_ratio <= 1.0 {
            score -= (1.0 - fit_ratio).powi(2) * 10.0;
        } else {
            score += (fit_ratio - 1.0).powi(2) * 5.0;
        }
    }

    // Mild penalty when this bin's residual deviates from the mean residual.
    score += ((pr - mean_residual) / cap).powi(2) * 4.0;

    // Slight preference for bins with more open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: waste grows super-linearly
    // for residuals that are hard to fill with typical item sizes.
    let pr = post_residual;
    // Class boundaries via integer division on residual magnitude.
    let class = pr / 10; // 0..=10 harmonic band
    score += (class as f64) * (class as f64) * 1.5;

    // Penalize residuals that no plausible next item (1..=100) can use well:
    // dead space is worst when small but nonzero and unusable.
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny unusable slivers
    }

    // Modulo arithmetic on capacity fractions: residuals that are
    // multiples of common item sizes are more reusable.
    let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
    if reusable {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item still fits: mild reward proportional to tightness
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item will not fit here; if this is the only fitting bin,
            // opening a fresh bin may be better for the next item.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin (new bin costs ~a full residual of waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): baseline cost of opening a bin.
    // Prefer it only when the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: charge the capacity minus what we place now,
        // i.e. the post_residual itself is already the score base; add fixed cost.
        score += 30.0;
        // But if item is large relative to capacity, a fresh bin is attractive
        // since large items fragment residuals elsewhere.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Early in stream, allow more bins to stay flexible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small (all bins tight),
        // a new bin is more justified.
        score -= 0.5 * mean_residual.max(0.0).min(bin_capacity as f64);
        // If many bins already fit the item, opening new is wasteful.
        score += 5.0 * (fitting_bins_count as f64);
    } else {
        // Reward using bins that are already well-filled (low residual),
        // best-fit style: base score post_residual already does this.
        // Slight extra pull toward the fullest bin.
        score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Prefer keeping the number of open bins low when many are open.
    if open_bins_count > 8 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste -> heavy quadratic penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, ideal
    }
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits relative to bin residual (fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer compact bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 5.0;

    // Penalize bins whose residual deviates far above mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post residual but this bin is nearly full, mild reward.
    if next_item_size > post_residual && post_residual < 10 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many competing bins means reusing is likely fine).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * scarcity + open_bins_count as f64 * 2.0;
        // Late in stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving dead space
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly matches the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            score += 0.3 * slack; // mild penalty for leftover after the chain
        } else {
            // next item cannot follow into this bin's remainder
            score += 12.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0;
        // early stream: opening bins is fine; late stream: discourage proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer consolidating into fewer bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits after this placement: mild reward
            score -= 5.0;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 4.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    if open_bins_count > 1 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global context: if this bin's residual deviates from mean residual,
    // prefer bins with below-average residual (drain nearly-full bins first).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.15 * (post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear penalty on large post_residual, growing with stream progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (50.0 + 100.0 * progress);

    // Reward tight fits: subtract when post_residual is small
    score -= (1.0 - norm_pr).powi(3) * 30.0;

    // Dead-space coupling: post_residual too small for average next item is bad
    if next_item_size > 0 {
        let nis = next_item_size as f64;
        if pr < nis {
            score += (nis - pr) * (0.5 + progress);
        } else {
            score -= 5.0 * (1.0 - (pr - nis) / cap);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when open bins exist with room
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    score += 0.2 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Class A (post_residual % 10 == 0): perfectly aligned leftover -> strong reward.
    // Class B (post_residual % 10 == 5): half-aligned -> mild reward.
    // Class C (small nonzero dead space 1..=9): penalize dead space quadratically.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else {
        let r10 = pr % 10;
        if r10 == 0 {
            score -= 12.0;
        } else if r10 == 5 {
            score -= 4.0;
        } else if pr <= 9 {
            score += (10 - pr) as f64 * 1.5; // tiny dead space penalty
        } else {
            score += (r10 as f64) * 0.4;
        }
    }

    // Integer-division threshold bands on post_residual (harmonic capacity fractions).
    if pr > bin_capacity / 2 {
        score -= 8.0; // leftover still fits large items
    } else if pr > bin_capacity / 4 {
        score -= 3.0;
    } else if pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // Next item fits here: reward, scaled by alignment class of (pr - nxt).
            let gap = pr - nxt;
            let gap_class = gap % 10;
            let bonus = if gap == 0 { 20.0 } else if gap_class == 0 { 14.0 } else if gap_class == 5 { 8.0 } else { 2.0 };
            score -= bonus;
        } else {
            // Next item won't fit after placing here: penalize more when tight.
            score += (nxt - pr) as f64 * 0.15;
        }
        // Modulo coupling: next_item in same decade class as pr is harmonious.
        if nxt % 10 == pr % 10 && nxt <= pr {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; slightly discourage early in stream,
    // encourage late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 + 15.0 * progress - (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Mean-residual context: prefer bins near the mean residual (balanced packing).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Mild penalty for too many open bins relative to stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 4.0 + 10.0 * progress {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 1.5 * open_bins_count as f64 * (1.0 - fill);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize leaving a residual that the next item can almost but not quite use.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Slight bias toward fuller bins relative to mean residual of open bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Late in the stream, prefer packing into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item exactly fills the post residual (perfect 2-chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // exact match => -60, decays with slack
        if slack == 0.0 {
            score -= 40.0; // bonus: chain closes bin completely later
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in this residual: penalize dead space mildly.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
    }

    // Prefer bins whose residual is already tight relative to mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score -= (open_bins_count as f64) * 1.5;
        score += mean_residual * 0.3;
    }

    // Late in stream: be greedier, keep residuals tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: post_residual too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if the leftover exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leftover wastes space relative to lookahead item
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let pressure = fit_ratio; // high when item nearly fills a bin
        if pressure > 0.8 {
            score -= 20.0; // opening a fresh bin for a big item is fine
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64; // discourage wasteful new bins
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if bin_residual < bin_capacity {
        score += 0.05 * mean_residual;
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight preference for bins with residual close to item (perfect packing).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    let mut score = pr as f64;

    // Non-linear penalty on wasted residual (quartic coupling)
    score += 8.0 * fit_norm * fit_norm * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: later in stream, favor tighter fits more strongly
    let tightness = 1.0 - fit_norm;
    score -= (0.5 + 2.5 * progress) * tightness * tightness * item_size as f64 * 0.1;

    // Penalize bins far from mean residual (fragmentation), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus (smooth): if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: reward residual that can still fit next item (smooth sigmoid-ish)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let margin = (pr - ns) / cap;
            score -= 3.0 * (1.0 - margin * margin);
        } else {
            score += 2.0 * (ns - pr) / cap * cap / 10.0;
        }
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress - 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues modulo 10 measure "usability"
    // of leftover space for typical small items (sizes 1..100 unknown dist).
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -40.0,           // round leftover: maximally reusable
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 3.0,
        4 | 6 => 1.5,
        _ => 0.0,             // residue 5
    };
    score += dead_penalty;

    // Integer-division thresholds: leftover in "half" classes of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual > half {
        score -= 15.0;        // large leftover: bin still very usable
    } else if post_residual >= quarter {
        score += 0.0;
    } else if post_residual > 0 {
        score += 10.0;        // small dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item leaves a round residue too
            let nr = (post_residual - next_item_size) % 10;
            if nr == 0 {
                score -= 60.0;
            } else {
                score -= (post_residual - next_item_size) as f64 / 4.0;
            }
        } else {
            // next item won't fit here: penalize slightly, less if last chance
            score += 5.0;
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only prefer it when no open bin fits well
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin is attractive
        }
    }

    // Stream progression: tighten packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Mild preference to fill bins with high residual among many open bins
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tightness relative to bin capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.15 * pressure;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it is a brand-new bin candidate.
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0; // chain fit with small leftover
            } else {
                score -= 5.0;
            }
        } else {
            score += 10.0; // dead space for the known next item
        }
    }

    // New-bin candidate: only attractive when existing bins would create
    // bad dead space or open-bin pressure is low.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.35;

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let leftover_after_next = post_residual - next_item_size;
            score -= 25.0 - (leftover_after_next as f64) * 0.25;
        } else {
            // next item does not fit here: penalize more if we leave large dead space
            score += (next_item_size - post_residual) as f64 * 0.18;
        }
    } else {
        // last item: just minimize post residual strongly
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins that become below-average residual
    // (keeps large residuals concentrated in few bins)
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.30;
    } else {
        score += (post_f - mean_residual) * 0.12;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more so early in the stream and when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress) + (open_bins_count as f64) * 1.5;
        // but if next item is huge and would waste current bins, soften slightly
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for very small unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed residual gap
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Strong reward for near-perfect packing
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fit;
        }
    }

    // Last-chance bin: strong penalty to open a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly, but reduce penalty when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * (1.0 - crowding) - 5.0 * progress;
        // If item is large and fits poorly anywhere else, new bin is attractive
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 8.0;
        }
    }

    // Penalize leaving dead space that likely no future item (min size 10) can use
    if post_residual < 10 {
        score -= 6.0; // dead space anyway, prefer consuming it
    } else {
        let waste = (post_residual as f64 % 10.0) / 10.0;
        score += 3.0 * waste;
    }

    // Mild penalty for spreading across too many bins when residuals are high
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual > mean_residual {
        score += 4.0;
    }

    // Time-horizon modulation: late in stream, consolidate aggressively
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = base;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals (waste less penalized); late, punish waste.
    let progress_weight = 0.35 + 1.15 * t * t;
    score += progress_weight * base * base * cap * 0.5;

    // Reward tight fits: item filling most of the bin residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 1.6 * fill * fill;

    // Lookahead: penalize residuals that cannot fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.9 * (nx - pr) / cap;
        } else {
            score -= 0.35 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * base;

    // Penalize bins far from mean residual (prefer uniform depletion).
    score += 0.25 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 0.45 + 0.5 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: dead space that no item (>=1) can use
    // is worthless, but residual that could fit a "small" class item is valuable.
    let pr = post_residual;
    if pr > 0 {
        // Class thresholds via integer division on capacity fractions.
        let quarter = bin_capacity / 4;   // 25
        let half = bin_capacity / 2;      // 50
        if pr < 10 {
            // Tiny dead space: mostly harmless but slightly wasteful.
            score += 5.0;
        } else if pr < quarter {
            // Could still fit a small item: keep these bins attractive.
            score -= 10.0;
        } else if pr < half {
            // Mid-class residual: moderate value.
            score -= 3.0;
        } else {
            // Large residual wasted on a small item: penalize.
            score += (pr as f64) * 0.5;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit anywhere else, this bin matters.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= 30.0;
        } else {
            // Next item won't fit here; slight penalty for chaining badly.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = (bin_capacity as f64) + 50.0;
        // If existing bins fit poorly (large item, few options), new bin is OK.
        if item_size > bin_capacity / 2 || fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
        // Many open bins with slack: discourage opening another.
        score += (open_bins_count as f64) * 3.0 + mean_residual * 0.2;
    }

    // Modulo harmonic nudge: residuals that are multiples of common small sizes
    // (e.g. divisible by 10 or 25) are more likely reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Dead space relative to capacity: penalize leaving large-but-unusable gaps
    // (gaps smaller than the smallest plausible item).
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized accordingly.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if lookahead item won't fit the new bin's future residual anyway,
        // opening a fresh bin is less attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
        // Early in the stream, allow new bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
    } else {
        // Favor placing into existing bins when open bin count is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (smaller residual than average means tighter packing).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

