    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged early,
    // more attractive late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 20.0 * progress;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size > 70 {
            score -= 10.0;
        }
        // Avoid opening new bins when a perfect fit exists elsewhere is already
        // handled by the chain-fit bonuses above.
    }

    // Mild penalty for wasting a large bin on a tiny item.
    if item_size < 20 && bin_residual > 80 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
