pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: penalize residual quadratically, weighted by progress.
    let x = pr / cap; // normalized residual in [0,1]
    let coupling = x * x * (0.5 + 1.5 * progress) + x * (1.0 - progress) * 0.25;
    score += 40.0 * coupling;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * progress;
        }
    }

    // Slight penalty for spreading across many open bins when residuals are large.
    let mean_x = mean_residual / cap;
    score += 5.0 * mean_x * mean_x * (open_bins_count as f64).ln().max(1.0) * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste buckets by modulo classes.
    let pr = post_residual as i64;
    let cls = pr % 12; // 12 harmonic residue classes on capacity 100
    // Penalize residues that historically become dead space (small odd residues),
    // reward residues that align with common item sizes (10..80 grid).
    let residue_penalty: [f64; 12] = [
        -6.0, 8.0, -4.0, 10.0, -2.0, 12.0, -5.0, 9.0, -3.0, 11.0, -1.0, 7.0,
    ];
    if pr >= 0 {
        score += residue_penalty[cls as usize];
    }

    // Integer-division thresholds: post_residual / 10 tiering.
    let tier = (post_residual / 10) as f64;
    score -= 1.5 * tier; // larger usable chunks are good (extra reward beyond raw residual)

    // Perfect fits: zero waste is golden.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is pure loss.
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: strongly reward, scaled by how snugly next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * snug;
            // Harmonic bonus if next item leaves a multiple-of-10 residual again.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: mild penalty for blocking the chain.
            score += 3.0;
            // But if residual is in a "collectible" class (sum of two common items), soften.
            if post_residual >= 20 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // it only wins when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * mean_residual + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // opening fresh helps if next item is large too
        }
        if fitting_bins_count <= 1 {
            score += 20.0; // don't open new bins when an existing bin is the only fit
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when open bins are already loose, prefer tight placements here.
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are "dead space". Penalize hard.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 45.0 + (dead_threshold - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: mild penalty to prefer larger leftovers
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (bin_residual as f64 + 1.0);
    score -= (1.0 - tightness) * 25.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }
    // If next item cannot fit in post residual, penalize slightly
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow
        score += 12.0 + bin_pressure * 3.0;
        // But if no existing bin fits well (large item, huge mean residual spread),
        // new bin becomes more attractive
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward scaled by open bins count
        score -= bin_pressure * 0.5;
    }

    // Prefer filling bins with small residuals first (consolidation)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Progress-based mild adjustment: later in stream, be more conservative
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 0.5 * (post_residual as f64 - nxt).min(50.0);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize new empty bin unless current fit is terrible or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 12.0; // poor fit elsewhere -> new bin attractive
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Slight preference for filling bins with many open bins (reduce spread).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of residual after placement
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strong bonus to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling bins with small residuals relative to fleet mean
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Encourage bin consolidation when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Time horizon: early in stream, be conservative (favor new bins slightly less);
    // late in stream, squeeze everything into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = 25.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, avoid opening new bins
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_res = post_residual as f64 / bin_capacity as f64;
    // reward tight fits: non-linear decay of wasted space
    score -= (1.0 - norm_res).powi(3) * bin_capacity as f64 * 0.5;
    // polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; later penalize it more strongly
    let coupling = norm_res.powi(2) * (0.5 + 2.0 * progress);
    score += coupling * 30.0;
    // last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }
    // lookahead: if next item fits into the post residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - gap).powi(2);
    } else if next_item_size > post_residual {
        score += 5.0 * progress;
    }
    // mildly prefer consolidating into fewer bins
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);
    // small pull toward mean residual to balance loads
    score += (mean_residual - post_residual as f64).abs() * 0.1;
    // new-bin candidate: penalize slightly so real bins win unless fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted pairing potential
        score += 0.15 * (next_item_size - post_residual.min(next_item_size)) as f64;
    }

    // Harmonic class of post_residual modulo 10:
    // residuals that are multiples of 10 are more reusable for typical item sizes
    score -= (post_residual % 10) as f64 * 0.4;
    // Residuals in the awkward 1..10 dead zone are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Very large residuals (>50) mean the bin is still half-empty; fine, slight bonus
    if post_residual > 50 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins could fit,
    // unless the item is large and deserves fresh space
    if bin_residual == bin_capacity {
        score += 22.0;
        if item_size > 50 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Nudge toward bins whose residual is near the mean (keeps bin states uniform)
    score += (mean_residual - post_residual as f64) * 0.12;

    // Slight preference for consolidating into fewer bins as the stream progresses
    score -= open_bins_count as f64 * 0.05 * prog;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (<= 10) are "dead" — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Semi-dead gaps: 10..=20 can only fit the smallest items; soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate gets penalized via open_bins_count indirectly;
    // here we reward consolidation into existing bins).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when nothing fits well
    // or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let next_fits_existing = next_item_size > 0 && next_item_size <= mean_residual as u32;
        if fitting_bins_count > 0 && next_fits_existing {
            score += 18.0 + fragmentation.min(30.0);
        } else {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheap; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward creating that chain opportunity.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; slight penalty for leaving a stranded gap.
        score += 5.0;
    }

    // Mild preference for bins below mean residual (balance avoidance of
    // many half-empty bins when mean residual is large).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual fit is better; sharpen with square.
    score = score * score / bin_capacity as f64 + post_residual as f64 * 0.5;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chain: post_residual exactly equals next item size -> huge reward.
        let gap = (post_residual as f64 - nxt).abs();
        if gap < 1.0 {
            score -= 120.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits into this bin's leftover: reward proportionally.
            score -= 25.0 + 30.0 * (nxt / post_residual as f64);
        } else {
            // Next item won't fit here: penalize dead space, worse when gap is small
            // (we nearly could have chained) and when post_residual is tiny.
            score += gap.min(30.0) * 0.8 + if post_residual < 10 { 15.0 } else { 0.0 };
        }
        // Coupling with mean residual: bins far below mean residual are "wasted" slots.
        let dev = mean_residual - post_residual as f64;
        score += 0.3 * dev.max(0.0);
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoid opening a new bin unless residual
        // after placement is essentially unusable (< 10) and next item is small.
        let dead = post_residual < 10 && next_item_size > 0 && next_item_size >= 10;
        if !dead {
            score -= 60.0;
        } else {
            score -= 10.0; // mild preference still, new bin may chain better
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when many bins are
        // already open and current fit is poor; discourage otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 - 20.0 * progress - 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 40.0; // next item is huge, fresh bin is very useful
        }
    }

    // Mild penalty for leaving exactly-zero residual if next item exists (bin closes,
    // which is fine, but tie-break toward chaining fits).
    if post_residual == 0 && next_item_size > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 1.0 };
    score -= 6.0 * (1.0 - (1.0 / (1.0 + tightness))).min(1.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize leaving dead space that no plausible item can fill.
    // Items are >= 1; small residuals below ~10 are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for hoarding space.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: if many bins fit the item, prefer the fullest (post_residual already does this),
    // but add mild tie-break toward bins below mean residual (relatively emptier gets penalty).
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mean_term = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 3.0 * mean_term * (0.5 + 0.5 * t);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are poor and item is small
        // relative to mean residual (i.e., existing bins would waste a lot).
        let waste = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = 60.0 - 30.0 * waste - 10.0 * t;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, with non-linear emphasis.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals are rewarded more aggressively.
    let tightness = 1.0 - (pr / cap);
    let progress_coupling = tightness * tightness * (1.0 + 2.0 * progress * progress);
    score -= 0.8 * progress_coupling;

    // Penalize residuals that are small-but-nonzero (dead space) quadratically.
    score += 0.35 * (pr / cap) * (pr / cap);

    // Reward filling a large fraction of the bin with this item.
    let fill = item_size as f64 / cap;
    score -= 0.5 * fill * fill;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= 0.6 * (1.0 - gap / cap);
        } else {
            score += 0.3 * (next_item_size as f64 / cap);
        }
    }

    // Mild penalty for spreading across many bins; encourage consolidation.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is close to what this item consumes.
    let mean_dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score += 0.2 * mean_dev * mean_dev;

    // New-bin candidate: penalize opening a new bin, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 0.9 + 0.8 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: post_residual mod 10 as "waste class"
    let waste_class = (post_residual % 10) as f64;
    score += waste_class * 0.9; // penalize residuals not on the harmonic lattice

    // Exact / near-exact fits get strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Integer-division threshold: residual usable by small future items (<= residual)
    // Reward bins whose residual stays "harmonically useful" (multiple of 10 or 20)
    if post_residual % 20 == 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly: big reward, scaled by how tight
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.15;
        } else if next_item_size <= bin_residual {
            // next item would fit current bin but not after this placement: mild penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.5 + mean_residual * 0.35;
        score = 40.0 + pressure; // base cost of a fresh bin, higher when many open bins
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin has room for the lookahead too
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Penalize bins far from mean residual (fragmentation outliers)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are "dead space" -> heavy penalty.
    let min_item = 1u32;
    let dead_threshold = 12u32; // small gap rarely reusable
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that can fit neither the next item nor anything small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(dead_threshold) {
        score += 15.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
        // But early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
    }

    // Mild preference for bins below mean residual (balance across bins).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain: bin fully consumed
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after the chain
            let chain_leftover = post_residual - next_item_size;
            score -= 40.0;
            score += chain_leftover as f64 * 0.8;
        } else {
            // next item won't fit here: dead space risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Relative to mean residual: bins below mean residual are "richer" targets
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty so tightest fit wins among many
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        let pressure = open_bins_count as f64 * avg_waste / bin_capacity as f64;
        // new bin is cheap early / when open bins are nearly full or item fits nothing well
        let poor_fit = (fit_ratio < 0.55) as i32 as f64;
        score -= 25.0 + 15.0 * poor_fit + 10.0 * pressure;
        // but discourage hoarding many open bins mid-stream
        score += (open_bins_count as f64).powf(1.3) * 2.0;
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 35.0;
    }

    // Penalize leaving small unusable slivers (<10) unless exact
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving small unusable fragments (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if the next item can use the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here; slight penalty for wasting space.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so we only
    // open new bins when existing bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Opening a new bin is cheap early, expensive late or when bins are scarce.
        let openness = 20.0 - 15.0 * progress;
        score += openness + 10.0 * (1.0 - scarcity) + (open_bins_count as f64).sqrt() * 2.0;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // Last-chance bin: strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Prefer bins below the mean residual (fill the emptier ones first
        // keeps tight bins available for tight items).
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: wasted space, with non-linear penalty on small residuals
    let mut score = prn.powf(1.0 + 0.8 * progress);

    // Smooth coupling: residual quality interacts with stream progress
    let dead_zone = (0.15 - prn).max(0.0) / 0.15;
    score += dead_zone * dead_zone * (2.0 + 6.0 * progress);

    // Reward tight fits (post_residual near zero)
    score -= (1.0 - prn).powi(6) * (1.0 + progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 1.5 * (1.0 - (nxt / pr - 0.5).abs()) * (1.0 + progress);
        } else {
            score += 0.5 * (prn / (nxt / cap)).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 1.0 + 0.02 * open_bins_count as f64 - 0.5 * progress;
    }

    // Slight preference for bins with residuals near the mean (balance)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual into integer-division buckets of capacity/10.
    let class = post_residual / (bin_capacity / 10).max(1);
    // Small residual classes are good (tight packing); large classes waste.
    score += (class as f64) * 3.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportional to how well it uses the remainder.
        score -= 50.0 * (next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a residual in a dead zone
        // (too small to be useful for typical items).
        if post_residual > 0 && post_residual < 20 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless
    // this bin is a really bad fit (large post_residual).
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * (open_bins_count as f64);
        // But if opening a new bin keeps mean residual low relative to stream
        // progress, make new bin more attractive for large items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > 0.7 * cap {
            score -= 60.0 * (1.0 - progress);
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first).
    score -= 0.3 * (mean_residual - pr);

    // Harmonic modulo bonus: residuals that are multiples of 5 pair well
    // with common item sizes.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    // Penalize residuals in awkward classes (1..4, 11..14 mod 15 dead zones).
    let m = post_residual % 15;
    if m >= 1 && m <= 4 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfectly full or nearly-dead bin: strongly reward closing it out.
        score -= 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    } else {
        // Penalize residuals that are dead for the NEXT item too (can't fit lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else if next_item_size > 0 && post_residual == next_item_size {
            // Perfect fit for the lookahead: big reward.
            score -= 40.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= tightness * 3.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate / spreading items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (bin_residual == bin_capacity) as i32 as f64 * 15.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., closer to being filled), penalize above-mean residuals.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.4;

    // New-bin candidate: make it unattractive unless it's genuinely better
    // (i.e., item is large and all open residuals are poor).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how wasteful current bins are.
        let waste = if fitting_bins_count > 0 {
            (post_residual as f64) // 100 - item, waste of a fresh bin
        } else {
            0.0
        };
        score += 20.0 + waste * 0.3;
        // If item nearly fills a fresh bin, opening new is fine.
        if item_size >= 80 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching: reward post_residual close to next item size ---
    if next_item_size > 0 {
        let gap = (post - nxt).abs();
        // Perfect 2-step match: post_residual exactly equals next item -> big reward
        if gap < 0.5 {
            score -= 45.0 + 25.0 * (1.0 - progress);
        } else if gap <= 10.0 {
            // Near match: reward proportional to closeness
            score -= 30.0 * (1.0 - gap / 10.0);
        } else {
            // Poor match: penalize leftover space that next item cannot use
            if post > nxt {
                score += 0.35 * (post - nxt);
            } else {
                // Next item won't fit here either; dead space penalty scaled by gap
                score += 0.15 * gap;
            }
        }
        // Bonus when next item is large and would consume most of the leftover
        if nxt >= post * 0.8 && nxt <= post {
            score -= 12.0;
        }
    } else {
        // Last item: minimize wasted residual directly
        score += 0.5 * post;
    }

    // --- Relative to mean residual across open bins ---
    // Placing into a bin whose resulting residual is below mean is good (tight packing)
    score -= 0.30 * (mean_residual - post);
    // Penalize bins much tighter than mean (fragmenting small bins)
    if post < mean_residual * 0.4 {
        score += 0.20 * (mean_residual * 0.4 - post);
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening a bin is expensive unless current bins fit badly
        let mut nb = 55.0 + 30.0 * (1.0 - progress);
        // If no open bin fits well (post_residual large everywhere), opening is attractive
        if next_item_size > 0 {
            let good_fit_exists = mean_residual - item_size as f64 <= nxt + 5.0;
            if good_fit_exists {
                nb += 25.0;
            } else {
                nb -= 20.0;
            }
        }
        // Few open bins -> cheaper to open (amortize)
        if open_bins_count <= 2 {
            nb -= 15.0;
        }
        score += nb;
    } else {
        // Reward using existing bins, more when many bins are open
        score -= 5.0 + 1.5 * open_bins_count as f64;
    }

    // Small tightness term: prefer minimal post residual overall
    score += 0.10 * (post / cap) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by placing the item here.
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward near-perfect fits strongly (non-linear coupling).
    score -= 12.0 * tightness * tightness * (0.5 + fill);

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward partial reusability, scaled by how much of the next item is covered.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Leftover dead space relative to the next item: penalize small unusable slivers.
            let dead = post_residual as f64 / next_item_size as f64;
            if dead < 1.0 {
                score += 6.0 * (1.0 - dead);
            }
        }
    } else {
        // Last item: prefer the bin that leaves the least waste overall.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (item_size as f64 / bin_residual as f64);
    }

    // Many open bins: prefer consolidating into existing bins to close them out.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far below mean residual are "odd" bins;
    // placing items there when the mean is high wastes future flexibility.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual).abs() / mean_residual;
        score += 2.0 * dev;
    }

    // Time horizon: early in the stream, keep bins balanced (favor bins close to mean residual);
    // late in the stream, just minimize waste aggressively.
    if progress < 0.5 {
        score += 3.0 * progress * (1.0 - progress) * dev_penalty(res, mean_residual);
    } else {
        score -= 5.0 * progress * tightness;
    }

    // New empty bin candidate: it has bin_residual == bin_capacity. Penalize opening a new
    // bin when existing bins fit, but less when the item is large (hard to place later).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 10.0 + 20.0 * scarcity - 8.0 * fill;
    }

    // Small absolute sliver penalty: residuals of 1..5 are nearly useless.
    if post_residual > 0 && post_residual < 6 {
        score += 5.0;
    }

    score
}

#[inline]
fn dev_penalty(res: f64, mean_residual: f64) -> f64 {
    if mean_residual <= 0.0 { 0.0 } else { (res - mean_residual).abs() / mean_residual }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr;

    // Polynomial interaction: residual value decays in usefulness as stream progresses
    let poly = norm_pr * (1.0 - progress) + norm_pr * norm_pr * (progress - 0.5).abs();
    score += 40.0 * poly;

    // Penalize large residuals late in the stream (dead space becomes costly)
    score += 25.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) more strongly early on
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward residual that fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: neutral baseline with slight penalty so it's chosen
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * norm_pr * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: capacity divided into classes of 10
    let class = |x: u32| x / 10;
    let post_class = class(post_residual);
    let item_class = class(item_size);

    // Reward placements whose post_residual falls on a "harmonic" class
    // (divisible residual classes are more reusable by common item sizes)
    let harmonic_bonus = match post_class {
        0 => 6.0,          // perfect fit: dead space zero
        1 | 2 => 3.0,      // small residual, still usable by small items
        3 | 4 | 5 => 1.5,  // mid classes
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize odd/prime-ish residuals (less likely to match future items)
    if post_residual % 10 != 0 {
        score += 1.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            score -= 2.0;
        } else {
            // next item won't fit here: penalize leaving large awkward residual
            score += (post_residual as f64) / 20.0;
        }
        // harmonic match between next item and post residual classes
        if class(next_item_size) == post_class && post_residual >= next_item_size {
            score -= 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits for the item.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let avg_fit_penalty = (mean_residual - item_size as f64).max(0.0);
        // opening a new bin is fine early or when open bins barely fit the item
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = waste * (0.5 + 0.5 * progress) + 4.0 - avg_fit_penalty * 0.5;
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Prefer tighter (fuller) bins generally
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.02;

    // Slight preference for bins whose residual is close to the item's class
    let class_gap = (class(bin_residual) as i32 - item_class as i32).abs() as f64;
    score += class_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 4.0;
    }
    // Small-but-usable gaps are also mildly penalized to prefer filling
    // larger residual bins where the item leaves a healthier remainder.
    if post_residual >= 12 && post_residual < 25 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // When many bins can fit the item, prefer the tightest one
    // (post_residual already encodes tightness; add mild tie-breaking).
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // loose fits; encourage closing bins out by tight placements.
    let open_pressure = (open_bins_count as f64).powf(1.2) * 0.3;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 12 {
            score += 10.0; // would create dead space for the next item
        }
    }

    // New-bin candidate handling: an empty bin is a safe fallback; make it
    // mildly attractive unless an open bin gives a very tight fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64; // residual after placement
        if open_bins_count > 0 {
            score += 5.0; // slight preference to reuse open bins
        }
        if fitting_bins_count == 1 {
            score += 30.0; // but never starve the sole fitting bin
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr {
            let slack = post_residual as f64 - nr;
            // Perfect chain fit (post_residual == next_item_size) is highly desirable.
            score -= 18.0 * (-slack / 15.0).exp();
            // Penalize leaving a residual that no small item can use later.
            if slack > 0.0 && slack < 8.0 {
                score += 6.0; // dead space too small for typical items
            }
        } else {
            // Next item cannot chain into this bin: mild penalty scaled by gap.
            score += 4.0 * (nr - post_residual as f64) / 40.0;
        }
        // If next item fits EXACTLY, strong reward (2-item perfect packing).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "almost full",
    // prefer using them (close them out) rather than leaving them hanging.
    let dev = (bin_residual as f64 - mean_residual).max(-80.0);
    score -= 0.10 * dev; // lower residual than mean -> lower score

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a penalty so we only open
    // new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight preference for bins that would become exactly full.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * mean_residual;
        // Early in stream, opening new bins is fine; late, discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins that deviate below mean residual (consolidate emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins over many open bins (reduce bin count pressure).
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, prefer tight fits (small post_residual) more aggressively;
    // later, larger residuals become more acceptable as bins close out.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap * 0.3;

    // Smooth interaction: post_residual vs mean residual deviation.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead coupling: penalize residuals that neither fit the next item well
    // nor are near zero — smooth quadratic in the gap.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.4 * (gap / cap) * (gap / cap) * cap;
        // Reward if next item fits exactly-ish
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.5 };
        score -= 0.25 * fit_next * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize gently unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of small item granules) are favored.
    let granule: u32 = 10;
    let residue = post_residual % granule;
    score += residue as f64 * 0.8; // penalize off-granule dead space

    // Quotient class: how many granules remain after placement.
    let q = post_residual / granule;
    score -= q as f64 * 2.0;

    // Exact-fill bonus: item perfectly closes the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tiny unusable leftover is bad: post_residual in (0,10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let next_res = post_residual - next_item_size;
            // prefer leaves where next item also lands on a granule boundary
            score -= 10.0 + (next_res % granule) as f64 * -0.5;
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a base opening cost so we
    // prefer existing bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // opening is more attractive early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // tighter fit (smaller post_residual relative to item) preferred
        score -= item_size as f64 * 0.3;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // balances the pool; reward moving residual toward mean.
    let post_f = post_residual as f64;
    score -= (mean_residual - post_f).abs() * -0.2; // i.e., reward closeness

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are nearly unusable
    // (min item size is 1..100 unknown, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0; // penalty for creating dead space
    }
    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (fill fraction of the bin's space).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: penalize using bins when many are open, to avoid
    // scattering items across many half-empty bins.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when open bins are crowded.
        let mut nb = 35.0;
        if fitting_bins_count == 0 {
            nb -= 50.0; // no alternative: open a new bin
        }
        // If next item is small it can use leftover space elsewhere; discourage new bin.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            nb -= 10.0; // next item won't fit mean residual; new bin may help
        }
        score += nb;
        // Dampen base residual so new bin isn't unfairly favored by raw post_residual.
        score -= post_residual as f64 * 0.5;
    }

    // Slight preference for bins with residual below mean (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in the stream, prefer closing bins tightly (fewer leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual gets strong discount).
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        score += pr * pr / (bin_capacity as f64 * 0.5); // penalize dead space quadratically
    }

    // 2-step lookahead: reward bins whose residual after placement matches next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        if diff <= 5.0 {
            score -= 80.0 * (1.0 - diff / 5.0); // next item fits almost exactly
        } else if pr >= n {
            score -= 25.0 * (n / pr); // next item still fits, prefer tighter bins
        } else {
            score += 15.0 * (diff / bin_capacity as f64); // next item won't fit here
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let dev = (bin_residual as f64 - mean_residual).max(0.0);
    score += dev * 0.6;

    // Last-chance bin: strong bonus to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it unattractive unless current bin would leave huge waste.
    if bin_residual == bin_capacity {
        let waste_if_used = pr;
        let baseline = if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
        score = 200.0 + waste_if_used as f64 * 0.5 + baseline;
        if next_item_size > 0 && next_item_size as f64 >= pr {
            score -= 120.0; // fresh bin serves current + next item well
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to item).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 12.0 * fit_ratio;

    // Reward near-full bins after placement.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space: residuals that are too small to host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave a bad residual.
    if bin_residual == bin_capacity {
        score += 15.0
            + 0.5 * open_bins_count as f64
            + 20.0 * (1.0 - (step_index as f64 / (total_items as f64).max(1.0)));
    } else {
        // Favor bins whose residual deviates below the mean (fill the emptier ones).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in stream, prefer consolidation; late, prefer any fit.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 - 0.15 * progress;

    // Mild penalty for many open bins to encourage reuse.
    score += 0.2 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward small post residual (good fill), quadratically.
    let mut score = pr as f64;

    // Non-linear coupling with stream progress: early on, tolerate slack;
    // later, strongly penalize leaving unusable dead space.
    let progress_pressure = 1.0 + 3.0 * t * t;
    score += progress_pressure * 40.0 * x * x;

    // Smooth interaction: post residual vs next item size — reward bins whose
    // post residual smoothly matches the upcoming item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        score += 25.0 * diff * diff * (1.0 - t);
        // Reward a perfect lookahead fit smoothly.
        let fit = (-diff.abs() * 8.0).exp();
        score -= 20.0 * fit;
    } else {
        // Last item: reward tight packing aggressively.
        score -= 30.0 * (1.0 - x) * (1.0 - x);
    }

    // Penalize bins far from the mean residual (fragmentation), smoothly scaled.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + t);

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 * (1.0 + t);
    }

    // Crowding effect: many open bins favor consolidation into existing ones.
    let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score -= 12.0 * crowding * x;

    // New-bin candidate: penalize opening a bin unless current fit is poor,
    // with smooth dependence on progress (later = more reluctant to open).
    if bin_residual == bin_capacity {
        let reluctance = 60.0 + 60.0 * t;
        score += reluctance;
        // But if the item is large relative to capacity, opening is fine.
        score -= 50.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space penalty grows super-linearly for small unusable residuals
    // (residuals below typical item size are hard to fill).
    if post < 10.0 {
        score -= 60.0 * (10.0 - post) / 10.0; // near-perfect fit reward
    } else if post < 20.0 {
        score -= 15.0 * (20.0 - post) / 10.0;
    } else if post < 34.0 {
        // awkward zone: too big to ignore, too small for most items
        score += 8.0 * (1.0 - frac);
    }

    // Integer-division harmonic classes: residuals divisible into nice chunks
    let cls = post_residual / 10; // decade class 0..=10
    match cls {
        0 => score -= 25.0,
        1 => score -= 10.0,
        2 => score += 2.0,
        3 => score += 5.0,
        4 => score += 8.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste = post - nxt;
            if waste < 5.0 {
                score -= 40.0; // perfect chain
            } else {
                score -= 25.0 * (1.0 - waste / cap);
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 12.0 * frac;
        }
    } else {
        // last item: any placement fine, prefer tight fit
        score -= 20.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin has huge residual; make it attractive
    // only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; open bins with tight fits will beat this.
        score = cap * 0.5 + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // compete with the lone fitting bin only if its residual is bad
            score = cap * 0.5 + 5.0 + 30.0 * frac;
        }
        // early stream: keep few bins, favor new bin slightly when many open bins
        if open_bins_count > 4 && (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (fills fuller bins first, classic best-fit flavor).
    score += (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (sizes >= 1, but practically < ~10) are "dead space" -> heavy penalty.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill: strongly favored
    }

    // Reward tight fits relative to the bin's prior residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit in the leftover, mild penalty proportional to gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins (penalize new-bin candidate which has full residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        score += 10.0 + pressure;
        // New bin is attractive only when it enables a great pairing:
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates below the mean (denser bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0); // full reward at exact fit, decays to 0
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space, more so if tiny residual.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // unusable sliver
        } else {
            score += 0.5 * (pr / 10.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Relative-to-mean shaping: bins tighter than the mean are better targets.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer filling existing bins over opening new ones (new bin has residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But if no open bin gives a decent fit (large post_residual gap vs mean), soften.
        if next_item_size > 0 && post_residual as f64 > mean_residual + 20.0 {
            score -= 20.0;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_residual < bin_capacity) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that likely can't be reused by the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 4.0;
        }
        // Perfect pairing: post residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded
    // and the current fit is loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let loose_fit = post_residual as f64 > 0.4 * bin_capacity as f64;
        // Base penalty for opening a new bin; reduced when bins are crowded and fit is bad.
        score += 14.0 + 5.0 * (1.0 - progress) - 4.0 * crowded;
        if loose_fit {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 6.0; // pairing impossible elsewhere, fresh bin attractive
        }
    }

    // Global residual pressure: when mean residual is low, preserve large-residual bins
    // for bigger future items; prefer dumping items into low-residual bins.
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    // Time horizon coupling: early on, keep bins flexible (penalize very small residuals);
    // late in the stream, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0 * progress; // late-stage small residual is great (near-full bin)
        score += 6.0 * (1.0 - progress); // early-stage small residual is wasted space
    }

    // Mild preference to spread load when many bins are open (balance residuals).
    score += 0.05 * (open_bins_count as f64) * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: reward tight fills (small post_residual), non-linearly.
    let mut score = pr.powf(1.3);

    // Polynomial coupling: tight fits matter more as stream progresses.
    score -= (1.0 - pr / cap).powi(3) * 18.0 * (0.4 + 0.6 * progress);

    // Penalize large wasted fraction quadratically.
    let waste = pr / cap;
    score += 12.0 * waste * waste;

    // Lookahead: bonus if post_residual exactly fits next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * snug * snug;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    } else {
        // Last item: strongly prefer any bin that fits.
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.6 * open_bins_count as f64 * (pr / cap);

    // Prefer bins below mean residual slightly (balance residuals).
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: penalize unless current bins are hopelessly loose.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / cap;
        score += 30.0 - 25.0 * avg_tightness * avg_tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets and reward/punish accordingly.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1 fraction of capacity wasted

    // Integer-division thresholds on post_residual (harmonic classes):
    // class 0: residual <= 10  (nearly perfect)
    // class 1: 11..25
    // class 2: 26..50
    // class 3: >50 (half-empty bin, very bad)
    let class = post_residual / 13; // harmonic divisor
    score += match class {
        0 => -6.0,
        1 => 0.0,
        2 => 4.0,
        _ => 9.0,
    };

    // Non-linear penalty growing with fraction of wasted capacity.
    score += 14.0 * frac * frac;

    // Modulo arithmetic on post_residual: residuals divisible by small
    // integers are more reusable by typical item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely: reward proportionally to tightness
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 5.0 * tight;
            // harmonic bonus if post_residual is an exact multiple of next size
            if post_residual % next_item_size == 0 {
                score -= 2.5;
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.06 * gap.min(60.0);
        }
    } else {
        // last item: just minimize leftover
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., when best open fit would leave a large residual).
    if bin_residual == bin_capacity {
        // neutral base, slightly penalized so tight fits win
        score += 8.0;
        // but if many open bins are nearly full, a fresh bin is fine
        if mean_residual < 15.0 {
            score -= 6.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild pressure to prefer filling fuller bins when many bins are open.
    score += 0.02 * (open_bins_count as f64).sqrt() * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward large usable residual relative to capacity.
    let usable = post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * usable;

    // Open-bin pressure: fewer open bins is better when fits are plentiful.
    if fitting_bins_count > 1 {
        score += 2.0 * open_bins_count as f64;
    } else {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin is decent.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: prefer leaving space that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Early stream: slightly favor consolidation into fewer bins.
    if (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this is a chain fit — strongly reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits after this one; residual stays usable.
            let leftover = post_residual - next_item_size;
            score -= (leftover as f64).min(30.0) * 1.5;
        } else {
            // Next item won't fit in the leftover: penalize proportionally
            // to how much dead space this creates relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare post residual against the mean residual across open bins:
    // leaving less than average is good (tightening bins), leaving more is bad.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when plenty of
    // open bins exist and the stream is early/mid (bins stay reusable).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 200.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
    }

    // Mild preference for filling fuller bins (smaller residual first).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if not, penalize leaving a residual that is useless for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (smaller residual).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more willing to open/spread bins;
    // late in the stream, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, penalize bins far from mean
    // (encourage balanced packing); if mean residual is low, prefer tight fits more.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = if next_item_size > 0 && next_item_size <= bin_capacity {
            18.0 - 10.0 * progress
        } else {
            10.0
        };
        score += new_bin_penalty;
        // If this is a last-chance situation with zero fitting bins context, allow opening.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty on very large dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 1.0; // small awkward gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty growth
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, be lenient with large residuals; late, penalize them harder.
    let progress_coupling = 1.0 + 1.6 * progress * progress + 0.8 * progress * norm_pr;
    score *= progress_coupling;

    // Reward near-perfect fits with a smooth quadratic bonus
    let perfectness = 1.0 - norm_pr;
    score -= 12.0 * perfectness * perfectness * perfectness;

    // Last-chance bin: strongly favor using it (smoothly scaled by fit quality)
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * perfectness;
    }

    // Lookahead: bonus if next item fits the post-residual (smooth quadratic in slack)
    if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        if slack >= 0.0 {
            let s = slack / cap;
            score -= 6.0 * (1.0 - s) * (1.0 - s);
        } else {
            score += 2.0 * (-slack / cap);
        }
    }

    // Mild preference for filling bins when many bins are open
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * perfectness;

    // Penalize bins far from mean residual (encourage residual homogenization)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it slightly unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot we land in.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class the residual into eighths of capacity; penalize odd/awkward classes.
    let eighth = (cap / 8.0).max(1.0);
    let class = (post / eighth).floor();
    score += (class % 2.0) * 3.0; // odd eighths are less reusable for mid-size items

    // Integer-division threshold: residual divisible into common item sizes is valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 10 {
        score -= 15.0; // near-perfect, dead space minimal
    } else {
        // reward if residual is a multiple of common sizes (10,20,25,50)
        let mut mult_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                mult_bonus += 6.0;
            }
        }
        score -= mult_bonus;
        // penalize residuals that no plausible item (1..=80) can use well
        if pr > 80 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        score = 20.0 + 40.0 * progress - 30.0 * (1.0 - pressure) - open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual.max(0) {
            score -= 10.0;
        }
    }

    // Late stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Prefer fuller bins slightly (tighter packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Penalize residuals too small to fit the smallest plausible item range.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: fewer open bins favored mildly; more bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow opening a new bin when the item is large and few bins fit it.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: does the next item fit in the post residual?
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: next item can follow, reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * tight;
        } else {
            // Next item won't fit here; penalize leftover dead space more strongly
            score += 0.5 * (post_residual as f64).powf(1.3);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // wasting them is bad, using them well is good.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        if res_f < mean_residual {
            score -= 15.0 * (mean_residual - res_f) / mean_residual;
        } else {
            score += 10.0 * (res_f - mean_residual) / mean_residual;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // no good fit exists (large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score += 90.0 + 60.0 * early;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin can host the next item too
        }
    }

    // Prefer consolidating into fewer bins when many are open
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Dead space relative to the next item's need.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it when residuals are fragmented or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0
            - 40.0 * progress
            - (open_bins_count as f64).sqrt() * 5.0
            + mean_residual * 0.3
            + item_size as f64 * 0.2;
    } else {
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins whose current residual is close to the item (tight packing).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Small time-horizon modulation: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Late in the stream, tight residuals (small post_residual) become more valuable,
    // while large wasted residuals are penalized super-linearly.
    let tightness = 1.0 - pr / cap;
    let progress_weight = progress * progress;
    score -= progress_weight * cap * tightness * tightness;

    // Super-linear penalty on dead space that can never fit a typical item.
    let dead = (pr / cap).powi(3);
    score += (1.0 + progress) * cap * dead;

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals that strand the lookahead, smoothly scaled by progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= fits_next * (1.0 + progress) * (nxt / cap) * cap * 0.5;
        let gap = ((nxt - pr).max(0.0)) / cap;
        score += progress * cap * gap * gap;
    }

    // Last-chance bin: strong smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 && bin_residual < bin_capacity { 1.0 } else { 0.0 };
    score -= last_chance * (1.0 + progress) * cap * 0.75;

    // Mean-residual context: bins far below mean residual are less attractive
    // (their space is more reusable); smooth quadratic deviation term.
    let dev = (pr - mean_residual) / cap;
    score += (1.0 - progress) * cap * dev * dev * 0.5;

    // Mild preference for consolidating into few bins as stream progresses.
    score += progress * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by modulo buckets.
    let m = post_residual % 10;
    // Small leftovers are "dead space" -> penalize their class; classes near a
    // full small-item slot (0,1,2 mod 10) are valuable.
    let class_bonus = match m {
        0 => -14.0,
        1 | 2 => -9.0,
        3 | 4 => -4.0,
        5 | 6 => 3.0,
        7 | 8 => 7.0,
        _ => 10.0,
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: does the leftover still
    // hold a typical small item?
    let can_hold_small = (post_residual / 10) >= 1;
    if can_hold_small {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 12.0; // pure dead space, unusable for min item size 1
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match: next item's complement class aligns
            if (post_residual - next_item_size) % 10 <= 2 {
                score -= 4.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual here.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: capacity minus item, penalized.
        score = (bin_capacity - item_size) as f64 + 15.0;
        // Early in the stream, fresh bins are cheaper (more items to come).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If existing bins are fragmented (high mean residual but none good), keep new bin.
        if mean_residual > 0.35 * bin_capacity as f64 {
            score -= 6.0;
        }
    } else {
        // Reward tight fits relative to capacity fraction.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // Mild penalty for bin sprawl when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (1..100 range => assume ~10 minimum
    // useful chunk, but interface allows size 1) are "dead". Penalize
    // non-zero post_residuals below a usable threshold heavily.
    let dead_threshold = 9.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin_residual (waste ratio coupling).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // filling existing bins, especially when mean residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; grows with number of already open bins.
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 4.0;
        // If lookahead item can combine with current item to nearly fill a bin,
        // opening a fresh bin is attractive (pairing potential).
        if next_item_size > 0 {
            let pair_waste = (bin_capacity as f64 - (item_size + next_item_size) as f64).abs();
            if item_size + next_item_size <= bin_capacity && pair_waste < 15.0 {
                new_bin_score -= 70.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        new_bin_score += progress * 20.0;
        score = score.max(new_bin_score);
        return score;
    }

    // Lookahead coupling: if post_residual exactly fits the next item,
    // reward this placement (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward when next item still fits in the leftover.
        score -= 10.0;
    }

    // Mean residual coupling: bins deviating far above mean residual are
    // looser; slightly prefer bins tighter than the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 80.0; // perfect chain: fill this bin with next item too
        }
        // Penalize residuals that are too small for next item but nonzero (dead space)
        if next_item_size > post_residual && post_residual > 0 {
            score += 15.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 10.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 5.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving large unusable residuals
    if pr > 0 && pr < 10.0 {
        score -= 20.0; // tiny residual is fine (nearly full bin)
    } else if pr >= 10.0 {
        score += pr * 0.15;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        score = 45.0 + pr * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 40.0; // keep the last-chance bin alive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared decay of post-residual favors near-perfect fits.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 30.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Partial compatibility: mild reward scaled by how much room remains for it.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap that is "almost but not enough".
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += gap * 0.8;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized more when existing bins have plenty of room.
        score += 12.0 + 2.0 * crowding * avg_pressure;
        // Early in the stream, opening bins is cheaper (builds a portfolio of residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin always fits the next item; slightly reward that.
            score -= 3.0;
        }
    }

    // Global-state coupling: prefer placing into bins whose residual deviates
    // below the mean (consolidate small leftovers into fewer, tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Mild preference for using existing bins as the stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Penalize creating dead space that no plausible item (>=1) can use only if
    // it is small and isolated: tiny residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear penalty on small residuals
    let mut score = pr as f64;
    score += 40.0 * x * (1.0 - x) * (1.0 - progress); // penalize mid-range waste early
    score -= 30.0 * x * x * progress;                 // reward tight fits late in stream

    // Exact fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 25.0 * (1.0 - ((pr - nx) / cap)) * (1.0 - progress);
        } else {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong preference when only one bin fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Slight preference to fill bins with low mean residual (avoid fragmenting)
    score += 5.0 * (mean_residual - pr / cap.max(1.0)).abs() / cap;

    // New-bin candidate: penalize mildly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 25 are "clean".
    let clean_class = post_residual % 25 == 0;
    if clean_class {
        score -= 6.0;
    }
    // Penalize awkward residuals in (0..10) — dead space likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Integer-division thresholds: how many size-10 chunks fit in post residual.
    let chunks = post_residual / 10;
    score -= chunks as f64 * 1.5;

    // Capacity fraction coupling: reward filling bin past 70% full.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 4.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_res = post_residual - next_item_size;
        score -= 5.0;
        if nxt_res % 25 == 0 {
            score -= 3.0;
        }
        if nxt_res < 10 {
            score += 4.0; // but avoid leaving tiny remainder after next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin should only win when current
    // fits are poor and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual;
        if item_size >= 50 && poor_fit && fitting_bins_count > 1 {
            score -= 7.0;
        } else {
            score += 12.0;
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    // Many open bins: discourage spreading, favor tightest fits.
    if open_bins_count > 4 {
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to host any realistic future item
    // (below the minimum plausible item size) are pure waste: penalize hard.
    let min_useful_gap = 10.0;
    if (post_residual as f64) < min_useful_gap && bin_residual != bin_capacity {
        score += (min_useful_gap - post_residual as f64) * 8.0;
    }

    // Gaps that can only fit small items are semi-dead: superlinear penalty
    // on tight-but-wasteful residuals.
    if post_residual > 0 && post_residual < item_size {
        score += (post_residual as f64).powf(1.35) * 0.6;
    }

    // --- Reward near-perfect fits ---
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 6.0 * fit_ratio;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fill, close the bin
    }

    // --- Coupling with mean residual across open bins ---
    // Prefer bins that are already below-average fullness? No: prefer bins
    // whose residual is close to the item (tight packing) relative to mean.
    let gap_to_mean = (bin_residual as f64 - mean_residual).abs();
    score += gap_to_mean * 0.08;

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: competition, slight penalty to avoid careless choice.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // --- Open-bins pressure ---
    // More open bins => discourage spreading, favor filling existing bins,
    // especially later in the stream.
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // --- Lookahead: if the next item fits the post-residual, reward heavily ---
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * slack;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual cannot host next item: mild penalty scaled by gap.
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable only when the item is large or
        // existing bins are nearly saturated; otherwise penalize.
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if large_item {
            score -= 4.0;
        } else {
            score += 10.0 + 8.0 * progress + 0.5 * open_bins_count as f64;
        }
        // A fresh bin has no dead space yet: baseline of capacity residual
        // already dominates, keep it competitive for big items only.
        score -= 3.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item's size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-match: next item fits with small slack left afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 1.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: penalize dead space proportionally.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when open bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 1.0;
        // But a new bin is fine late in the stream or if it enables a perfect follow-up.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 150.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild bonus for filling bins more completely as stream progresses.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    score
}
